#!/usr/bin/env bash
# install.sh — LLM API Proxy installer
# Generated by build-installer.sh — do not edit manually.
#
# Usage: download and externally verify the signed installer bundle, then run:
#   Linux: sudo bash install.sh [install|upgrade|reconfigure|uninstall] [OPTIONS]
#   macOS: unavailable in this emergency release (fails before host mutation)

# Apply strict mode for real execution only. When the installer is sourced for
# unit testing (`source install.sh.template --source-only`), inheriting
# `set -euo pipefail` into the BATS shell breaks BATS' own error handling
# (failing assertions stop emitting TAP results — "Executed 0 instead of N").
# The `--source-only` sentinel is passed as $1 at source time, so we can detect
# the test context here and skip strict mode; real CLI invocations never pass
# `--source-only` as $1, so their behavior is unchanged.
if [[ "${1:-}" != "--source-only" ]]; then
    set -euo pipefail
    if [[ "$(/usr/bin/uname -s 2>/dev/null || true)" != "Linux" ]]; then
        printf '%s\n' \
            "ERROR: This emergency LLAP release requires Linux. Other platforms are disabled until their credential and recovery authority has completed a separate R3 review." \
            >&2
        exit 1
    fi
    if (( BASH_VERSINFO[0] < 4 )); then
        printf '%s\n' \
            "ERROR: LLAP requires Bash >= 4. On macOS, install Homebrew Bash and run /opt/homebrew/bin/bash install.sh (Apple Silicon) or /usr/local/bin/bash install.sh (Intel)." \
            >&2
        exit 1
    fi
fi

# ── Full-script parse guarantee ───────────────────────────────────────────────
# Wrapping the entire body in _main() forces bash to parse through the closing
# brace before executing anything. This guarantees that all
# variable definitions—including EMBED_* injected at the bottom by
# build-installer.sh—are parsed and available before main() runs.
# The old tmpfile re-exec pattern is no longer needed.
_main() {

# ── Constants ────────────────────────────────────────────────────────────────
INSTALLER_VERSION="0.0.144"
# Reviewed production trust anchor. A downloaded public key is accepted only
# when its primary fingerprint matches this exact value.
RELEASE_SIGNING_FINGERPRINT="4F2BBCD92F7AEC826BF4C156D6443D2B4B6AB71F"
# shellcheck disable=SC2034  # Used by phase functions appended by build-installer.sh
INSTALL_DIR_LINUX="/opt/llm-api-proxy"
# shellcheck disable=SC2034
INSTALL_DIR_MACOS="/usr/local/lib/llm-api-proxy"
# shellcheck disable=SC2034
METADATA_DIR_LINUX="/etc/llm-api-proxy"
# shellcheck disable=SC2034
METADATA_DIR_MACOS="${HOME}/.config/llm-api-proxy"
# shellcheck disable=SC2034
SERVICE_USER="llm-proxy"
if [[ "${1:-}" == "--source-only" ]]; then
    LOG_FILE="${LOG_FILE:-}"
else
    # Real executions always allocate this themselves. Do not inherit a
    # caller-selected path across sudo or the signed wrapper's env boundary.
    LOG_FILE=""
fi
CLEANUP_FILES=()
REMOTE_CHECKSUMS_FILE=""
REMOTE_SIGNATURE_FILE=""
INSTALLER_SINGLE_FLIGHT_BACKEND=""
INSTALLER_SINGLE_FLIGHT_FD=""
INSTALLER_SINGLE_FLIGHT_OWNED="false"
INSTALLER_SELF_CHECK_VERIFIED="false"
DEPLOY_EMBEDDED_FILE_STAGING_FILE=""
DEPLOY_EMBEDDED_FILE_STAGING_PARENT=""
DEPLOY_COMPOSE_COMMAND_STAGING_FILE=""
DEPLOY_ENV_STAGING_FILE=""
DEPLOY_ENV_STAGING_PARENT=""
DEPLOY_UPGRADE_ENV_REFERENCE_STAGING_DIR=""
DEPLOY_BIND_MOUNT_RECREATE_SERVICES=()
if [[ "${1:-}" == "--source-only" ]]; then
    INSTALLER_SINGLE_FLIGHT_LOCK_PATH="${INSTALLER_SINGLE_FLIGHT_LOCK_PATH:-/var/run/llm-api-proxy-installer.lock}"
    INSTALLER_SINGLE_FLIGHT_EXPECTED_UID="$(id -u)"
else
    # These values are deliberately not caller-configurable for a real run.
    INSTALLER_SINGLE_FLIGHT_LOCK_PATH="/var/run/llm-api-proxy-installer.lock"
    INSTALLER_SINGLE_FLIGHT_EXPECTED_UID="0"
fi

# Privilege escalation — empty when already root, "sudo" otherwise
if [[ $EUID -eq 0 ]]; then
    SUDO=""
else
    SUDO="sudo"
fi

# ── Security ─────────────────────────────────────────────────────────────────
umask 077

# ── Signal traps ─────────────────────────────────────────────────────────────
cleanup() {
    if declare -F deploy_discard_embedded_file_staging >/dev/null 2>&1; then
        deploy_discard_embedded_file_staging || true
    fi
    if declare -F deploy_discard_env_staging >/dev/null 2>&1; then
        deploy_discard_env_staging || true
    fi
    if declare -F deploy_discard_upgrade_env_reference_staging >/dev/null 2>&1; then
        deploy_discard_upgrade_env_reference_staging || true
    fi
    if declare -F deploy_discard_image_lock_staging >/dev/null 2>&1; then
        deploy_discard_image_lock_staging || true
    fi
    if declare -F database_close_validated_backup_dump >/dev/null 2>&1; then
        database_close_validated_backup_dump || true
    fi
    if declare -F database_discard_validation_staging >/dev/null 2>&1; then
        database_discard_validation_staging || true
    fi
    if declare -F database_discard_journal_staging >/dev/null 2>&1; then
        database_discard_journal_staging || true
    fi
    if declare -F database_discard_image_lock_staging >/dev/null 2>&1; then
        database_discard_image_lock_staging || true
    fi
    if declare -F database_discard_enumeration_staging >/dev/null 2>&1; then
        database_discard_enumeration_staging || true
    fi
    if declare -F database_discard_backup_staging >/dev/null 2>&1; then
        database_discard_backup_staging || true
    fi
    if declare -F database_discard_restore_staging >/dev/null 2>&1; then
        database_discard_restore_staging || true
    fi
    if declare -F database_discard_source_snapshot_staging >/dev/null 2>&1; then
        database_discard_source_snapshot_staging || true
    fi
    if declare -F database_abort_rollback >/dev/null 2>&1; then
        database_abort_rollback || true
    fi
    # Abort recovery can itself allocate protected extraction/enumeration
    # staging. Sweep again so an interrupted or failed recovery cannot leave a
    # database dump or secret-bearing deploy tree behind.
    if declare -F deploy_discard_embedded_file_staging >/dev/null 2>&1; then
        deploy_discard_embedded_file_staging || true
    fi
    if declare -F deploy_discard_env_staging >/dev/null 2>&1; then
        deploy_discard_env_staging || true
    fi
    if declare -F deploy_discard_upgrade_env_reference_staging >/dev/null 2>&1; then
        deploy_discard_upgrade_env_reference_staging || true
    fi
    if declare -F deploy_discard_image_lock_staging >/dev/null 2>&1; then
        deploy_discard_image_lock_staging || true
    fi
    if declare -F database_close_validated_backup_dump >/dev/null 2>&1; then
        database_close_validated_backup_dump || true
    fi
    if declare -F database_discard_validation_staging >/dev/null 2>&1; then
        database_discard_validation_staging || true
    fi
    if declare -F database_discard_journal_staging >/dev/null 2>&1; then
        database_discard_journal_staging || true
    fi
    if declare -F database_discard_image_lock_staging >/dev/null 2>&1; then
        database_discard_image_lock_staging || true
    fi
    if declare -F database_discard_enumeration_staging >/dev/null 2>&1; then
        database_discard_enumeration_staging || true
    fi
    if declare -F database_discard_backup_staging >/dev/null 2>&1; then
        database_discard_backup_staging || true
    fi
    if declare -F database_discard_restore_staging >/dev/null 2>&1; then
        database_discard_restore_staging || true
    fi
    if declare -F database_discard_source_snapshot_staging >/dev/null 2>&1; then
        database_discard_source_snapshot_staging || true
    fi
    local file
    for file in "${CLEANUP_FILES[@]}"; do
        rm -rf -- "$file" 2>/dev/null || true
    done
    if [[ "${INSTALL_PHASE:-}" != "" ]]; then
        echo ""
        echo "Installation interrupted during: ${INSTALL_PHASE}"
        echo "System state: phases before '${INSTALL_PHASE}' completed successfully."
        echo "Re-run install.sh to resume."
        echo ""
    fi
    release_installer_single_flight_lock
}
# Register signal traps for real execution only. A leaked EXIT trap interferes
# with BATS' test teardown/reporting (see the strict-mode guard above).
if [[ "${1:-}" != "--source-only" ]]; then
    trap cleanup EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM
fi

# ── Colour output ────────────────────────────────────────────────────────────
if [[ -t 1 ]] && command -v tput &>/dev/null; then
    RED=$(tput setaf 1)
    GREEN=$(tput setaf 2)
    YELLOW=$(tput setaf 3)
    # shellcheck disable=SC2034  # BLUE used by phase functions appended by build-installer.sh
    BLUE=$(tput setaf 4)
    BOLD=$(tput bold)
    RESET=$(tput sgr0)
else
    RED="" GREEN="" YELLOW=""
    # shellcheck disable=SC2034
    BLUE="" BOLD="" RESET=""
fi

# ── Logging ──────────────────────────────────────────────────────────────────
log_init() {
    local safe_args="" argument safe_argument quoted_argument
    if [[ -z "$LOG_FILE" ]]; then
        LOG_FILE="$(
            mktemp "${TMPDIR:-/tmp}/llm-api-proxy-install.XXXXXXXX.log"
        )" || {
            echo "Could not allocate a private installer log." >&2
            return 1
        }
    elif [[ -L "$LOG_FILE" || ( -e "$LOG_FILE" && ! -f "$LOG_FILE" ) ]]; then
        echo "Refusing an unsafe installer log path." >&2
        return 1
    elif [[ ! -e "$LOG_FILE" ]]; then
        ( set -o noclobber; : > "$LOG_FILE" ) 2>/dev/null || {
            echo "Could not create the private installer log." >&2
            return 1
        }
    fi
    chmod 0600 "$LOG_FILE" || {
        echo "Could not protect the installer log." >&2
        return 1
    }
    for argument in "$@"; do
        case "$argument" in
            --github-token=*|--cf-dns-api-token=*|--cf-api-key=*|\
--restic-repository=*|--restic-password=*|--aws-access-key-id=*|\
--aws-secret-access-key=*|--postgres-password=*|--kek-hex=*|\
--proxy-key-pepper=*|--jwt-secret=*|--grafana-password=*)
                safe_argument="${argument%%=*}=***REDACTED***"
                quoted_argument="$safe_argument"
                ;;
            *)
                safe_argument="$argument"
                printf -v quoted_argument '%q' "$safe_argument"
                ;;
        esac
        safe_args+="${safe_args:+ }${quoted_argument}"
    done
    {
        echo "=== LLM API Proxy Installer v${INSTALLER_VERSION} ==="
        echo "Date: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
        echo "User: $(whoami)"
        echo "Args: ${safe_args}"
        echo "---"
    } >> "$LOG_FILE"
}

log() {
    [[ -n "${LOG_FILE:-}" ]] || return 0
    echo "[$(date -u +%H:%M:%S)] $*" >> "$LOG_FILE"
}

info()  { echo "${GREEN}  ✓${RESET} $*"; log "INFO: $*"; }
warn()  { echo "${YELLOW}  ⚠${RESET} $*"; log "WARN: $*"; }
fail()  { echo "${RED}  ✗${RESET} $*"; log "FAIL: $*"; }
step()  { echo "${BOLD}$*${RESET}"; log "STEP: $*"; }

die() {
    fail "$1"
    echo ""
    if [[ -n "${LOG_FILE:-}" ]]; then
        echo "Full log: ${LOG_FILE}"
    fi
    exit "${2:-1}"
}

installer_executable_metadata_is_trusted() {
    local platform="$1" managed_uid="$2" owner="$3" group="$4" mode="$5"
    local mode_value
    if [[ "$platform" == "Darwin" ]]; then
        [[ "$owner" == "0" || "$owner" == "$managed_uid" ]] || return 1
    else
        [[ "$platform" == "Linux" && "$owner" == "$managed_uid" ]] || return 1
    fi
    [[ "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
    mode_value=$((8#$mode))
    (( (mode_value & 8#002) == 0 )) || return 1
    if (( (mode_value & 8#020) != 0 )); then
        # Docker Desktop's supported launcher resolves below /Applications,
        # conventionally root:admin 0775. Members of the macOS admin group are
        # already inside the platform privilege boundary; no other
        # group-writable executable namespace is accepted.
        [[ "$platform" == "Darwin" \
            && "$owner" == "0" && "$group" == "admin" ]] || return 1
    fi
}

installer_trusted_executable_parent() {
    local parent="$1" platform="$2" managed_uid="$3"
    local relative component current="/"
    local metadata owner group mode
    relative="${parent#/}"
    while :; do
        [[ -d "$current" && ! -L "$current" ]] || return 1
        case "$platform" in
            Linux)
                metadata="$(/usr/bin/stat -Lc '%u::%a' "$current" 2>/dev/null)" \
                    || return 1
                ;;
            Darwin)
                metadata="$(/usr/bin/stat -L -f '%u:%Sg:%Lp' "$current" 2>/dev/null)" \
                    || return 1
                ;;
        esac
        owner="${metadata%%:*}"
        metadata="${metadata#*:}"
        group="${metadata%%:*}"
        mode="${metadata#*:}"
        installer_executable_metadata_is_trusted \
            "$platform" "$managed_uid" "$owner" "$group" "$mode" || return 1
        [[ -n "$relative" ]] || break
        if [[ "$relative" == */* ]]; then
            component="${relative%%/*}"
            relative="${relative#*/}"
        else
            component="$relative"
            relative=""
        fi
        if [[ "$current" == "/" ]]; then
            current="/${component}"
        else
            current="${current}/${component}"
        fi
    done
}

# Resolve Docker to an absolute executable whose lexical symlink namespace,
# resolved-target namespace, and final inode are not writable outside the
# platform's installer trust boundary. This prevents PATH/functions and a
# replaceable symlink target from intercepting a privileged authority check.
installer_docker_executable() {
    local candidate lexical_candidate lexical_parent target parent
    local platform managed_uid metadata owner group mode hop=0
    (( $# <= 1 )) || return 1
    if (( $# == 1 )); then
        candidate="$1"
    else
        candidate="$(type -P docker 2>/dev/null || true)"
    fi
    database_recovery_install_dir_is_safe "$candidate" || return 1
    lexical_candidate="$candidate"
    platform="$(uname -s 2>/dev/null || true)"
    case "$platform" in
        Linux) managed_uid=0 ;;
        Darwin)
            managed_uid="$(installer_managed_deployment_uid)" || return 1
            ;;
        *) return 1 ;;
    esac
    # Validate the lexical namespace before physical resolution. Otherwise an
    # intermediate symlink (for example /tmp/alias/docker -> /usr/bin/docker)
    # disappears under `cd -P`, yet the unsafe lexical path would be retained
    # and executed after the check.
    lexical_parent="$(dirname -- "$lexical_candidate")" || return 1
    installer_trusted_executable_parent \
        "$lexical_parent" "$platform" "$managed_uid" || return 1
    while :; do
        [[ "$candidate" == /* && "$candidate" != *$'\n'* \
            && "$candidate" != *$'\r'* && "$candidate" != *$'\t'* ]] \
            || return 1
        lexical_parent="$(dirname -- "$candidate")" || return 1
        installer_trusted_executable_parent \
            "$lexical_parent" "$platform" "$managed_uid" || return 1
        parent="$(cd -P "$(dirname -- "$candidate")" 2>/dev/null \
            && pwd -P)" || return 1
        installer_trusted_executable_parent \
            "$parent" "$platform" "$managed_uid" || return 1
        candidate="${parent}/$(basename -- "$candidate")"
        if [[ ! -L "$candidate" ]]; then
            break
        fi
        (( hop < 16 )) || return 1
        hop=$((hop + 1))
        target="$(/usr/bin/readlink "$candidate" 2>/dev/null)" || return 1
        if [[ "$target" == /* ]]; then
            candidate="$target"
        else
            candidate="${parent}/${target}"
        fi
    done
    [[ -x "$candidate" && -f "$candidate" && ! -L "$candidate" ]] || return 1
    case "$platform" in
        Linux)
            metadata="$(/usr/bin/stat -c '%u::%a' "$candidate" 2>/dev/null)" \
                || return 1
            ;;
        Darwin)
            metadata="$(/usr/bin/stat -f '%u:%Sg:%Lp' "$candidate" 2>/dev/null)" \
                || return 1
            ;;
    esac
    owner="${metadata%%:*}"
    metadata="${metadata#*:}"
    group="${metadata%%:*}"
    mode="${metadata#*:}"
    installer_executable_metadata_is_trusted \
        "$platform" "$managed_uid" "$owner" "$group" "$mode" || return 1
    # Persist the stable lexical launcher (for example Homebrew's unversioned
    # symlink), after validating its complete current target chain. Package
    # upgrades may retarget it without stranding boot or journal recovery.
    printf '%s\n' "$lexical_candidate"
}

# The installer mutates local host state and therefore must use one Docker
# daemon consistently. Ambient endpoint/TLS selectors can otherwise make
# preflight authorize containers or mounts on one daemon while recovery uses
# another. Every authoritative Docker call goes through this scrubbed wrapper;
# generated Compose commands carry the same contract.
installer_local_docker_host() {
    local platform="${1:-}" docker_home="${2:-}"
    [[ -n "$platform" ]] || platform="$(uname -s 2>/dev/null || true)"
    case "$platform" in
        Linux)
            printf 'unix:///var/run/docker.sock\n'
            ;;
        Darwin)
            [[ -n "$docker_home" ]] || docker_home="${HOME:-}"
            database_recovery_install_dir_is_safe "$docker_home" || return 1
            # Docker Desktop's user-owned engine socket is local and stable
            # across context changes. Pin it directly so currentContext cannot
            # redirect privileged deployment or recovery to a remote daemon.
            printf 'unix://%s/.docker/run/docker.sock\n' "${docker_home%/}"
            ;;
        *)
            return 1
            ;;
    esac
}

installer_macos_operator_user() {
    local operator
    if [[ "$EUID" -eq 0 ]]; then
        operator="${SUDO_USER:-}"
        [[ "$operator" != "root" ]] || return 1
    else
        operator="$(/usr/bin/id -un)" || return 1
    fi
    [[ "$operator" =~ ^[A-Za-z_][A-Za-z0-9._-]*$ ]] || return 1
    /usr/bin/id -u "$operator" >/dev/null 2>&1 || return 1
    printf '%s\n' "$operator"
}

installer_macos_operator_home() {
    local operator="$1" home
    [[ "$operator" =~ ^[A-Za-z_][A-Za-z0-9._-]*$ ]] || return 1
    if [[ "$EUID" -eq 0 ]]; then
        [[ -x /usr/bin/dscl ]] || return 1
        home="$(
            /usr/bin/dscl . -read "/Users/${operator}" \
                NFSHomeDirectory 2>/dev/null \
                | /usr/bin/awk -F': ' '
                    $1 == "NFSHomeDirectory" {
                        print substr($0, index($0, ": ") + 2)
                        exit
                    }
                '
        )" || return 1
    else
        home="${HOME:-}"
    fi
    database_recovery_install_dir_is_safe "$home" || return 1
    printf '%s\n' "${home%/}"
}

installer_docker() (
    local docker_executable platform docker_home docker_host operator
    local -a clean_environment=()
    docker_executable="$(installer_docker_executable)" || return 1
    platform="$(uname -s 2>/dev/null || true)"
    case "$platform" in
        Linux)
            docker_home="/root"
            docker_host="$(installer_local_docker_host "$platform" "$docker_home")" \
                || return 1
            clean_environment=(
                /usr/bin/env -i
                "PATH=/usr/bin:/bin"
                "HOME=${docker_home}"
                "LC_ALL=C"
                "DOCKER_HOST=${docker_host}"
            )
            ;;
        Darwin)
            operator="$(installer_macos_operator_user)" || return 1
            docker_home="$(installer_macos_operator_home "$operator")" \
                || return 1
            docker_host="$(installer_local_docker_host "$platform" "$docker_home")" \
                || return 1
            clean_environment=(
                /usr/bin/env -i
                "PATH=/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin"
                "HOME=${docker_home}"
                "LC_ALL=C"
                "DOCKER_HOST=${docker_host}"
            )
            ;;
        *) return 1 ;;
    esac
    if [[ "$platform" == "Darwin" ]]; then
        # Docker Desktop's socket and credential-helper configuration belong to
        # the invoking desktop user. Running the CLI through sudo can rewrite
        # ~/.docker/config.json as root during login and strand later launches.
        if [[ "$EUID" -eq 0 ]]; then
            /usr/bin/sudo -u "$operator" \
                "${clean_environment[@]}" "$docker_executable" "$@"
        else
            command "${clean_environment[@]}" "$docker_executable" "$@"
        fi
    elif [[ -n "$SUDO" ]]; then
        $SUDO "${clean_environment[@]}" "$docker_executable" "$@"
    else
        command "${clean_environment[@]}" "$docker_executable" "$@"
    fi
)

installer_compose_runtime_contract() {
    local platform docker_home docker_path docker_host operator
    platform="$(uname -s 2>/dev/null || true)"
    case "$platform" in
        Linux)
            docker_home="/root"
            docker_path="/usr/bin:/bin"
            ;;
        Darwin)
            operator="$(installer_macos_operator_user)" || return 1
            docker_home="$(installer_macos_operator_home "$operator")" \
                || return 1
            docker_path="/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin"
            ;;
        *)
            return 1
            ;;
    esac
    docker_host="$(installer_local_docker_host "$platform" "$docker_home")" \
        || return 1
    printf '%s\n%s\n%s\n' "$docker_path" "$docker_home" "$docker_host"
}

# The installer mutates package state, firewall rules, deploy files, and a
# database recovery journal. Serialize the mutating lifetime after the running
# bytes, published signature, and host privilege boundary are verified but
# before journal recovery, target bootstrap, or host mutation. Linux uses a
# kernel-released flock on a persistent root-owned, operator-group-readable
# inode, so SIGKILL and reboot cannot strand recovery.
# macOS uses its base-system shlock, which detects stale PID locks. Neither lock
# is world-readable, so the trust boundary is root plus the invoking operator's
# primary group rather than every local user. The EXIT trap releases only after
# all recovery cleanup is complete.
acquire_installer_single_flight_lock() {
    local lock_path="$INSTALLER_SINGLE_FLIGHT_LOCK_PATH"
    local expected_gid initial_metadata metadata platform
    local descriptor_identity path_identity
    local -a root_command=()

    [[ "$lock_path" == /* && -n "$lock_path" ]] \
        || die "Installer single-flight lock path is invalid."
    if [[ -n "$SUDO" ]]; then
        root_command=(sudo)
    fi
    if [[ "$EUID" -eq 0 && -n "${SUDO_USER:-}" \
        && "${SUDO_USER}" != "root" ]]; then
        expected_gid="$(id -g "$SUDO_USER")" \
            || die "Installer operator group could not be resolved."
    else
        expected_gid="$(id -g)" \
            || die "Installer operator group could not be resolved."
    fi
    [[ "$expected_gid" =~ ^[0-9]+$ ]] \
        || die "Installer operator group is invalid."

    platform="$(uname -s 2>/dev/null || true)"
    if [[ "$platform" == "Darwin" ]]; then
        [[ -x /usr/bin/shlock ]] \
            || die "Safe installer single-flight locking is unavailable on this macOS host."
        if ! "${root_command[@]}" /usr/bin/shlock -f "$lock_path" -p "$$"; then
            die "Another installer process is already running."
        fi
        INSTALLER_SINGLE_FLIGHT_BACKEND="shlock"
        INSTALLER_SINGLE_FLIGHT_OWNED="true"
        if ! "${root_command[@]}" chmod 0600 "$lock_path"; then
            release_installer_single_flight_lock
            die "Installer single-flight lock could not be secured."
        fi
        return 0
    fi

    [[ "$platform" == "Linux" && -x /usr/bin/flock \
        && -x /usr/bin/stat ]] \
        || die "Safe installer single-flight locking is unavailable on this host."

    # Build a correctly owned inode privately, then hard-link it into the
    # root-only runtime directory. link(2) never replaces an existing lock, so
    # simultaneous first runs converge on one inode without a creation window.
    # shellcheck disable=SC2016  # Positional parameters expand in the inner shell.
    if ! "${root_command[@]}" /bin/sh -ceu '
        lock_path=$1
        expected_uid=$2
        expected_gid=$3
        if [ -e "$lock_path" ] || [ -L "$lock_path" ]; then
            exit 0
        fi
        temporary="${lock_path}.new.$$"
        umask 077
        set -C
        : > "$temporary"
        if [ "$expected_uid" = 0 ]; then
            chown "0:${expected_gid}" "$temporary"
        fi
        chmod 0640 "$temporary"
        ln "$temporary" "$lock_path" 2>/dev/null || true
        rm -f "$temporary"
    ' sh "$lock_path" "$INSTALLER_SINGLE_FLIGHT_EXPECTED_UID" "$expected_gid"; then
        die "Installer single-flight lock could not be created."
    fi
    if "${root_command[@]}" test -L "$lock_path" \
        || ! "${root_command[@]}" test -f "$lock_path"; then
        die "Installer single-flight lock is not a safe regular file."
    fi
    initial_metadata="$(
        "${root_command[@]}" env LC_ALL=C /usr/bin/stat \
            -c '%u:%a:%h' "$lock_path" 2>/dev/null
    )" || die "Installer single-flight lock metadata could not be read."
    [[ "$initial_metadata" == \
        "${INSTALLER_SINGLE_FLIGHT_EXPECTED_UID}:640:1" ]] \
        || die "Installer single-flight lock ownership or mode is unsafe."

    # The persistent inode must not bind all future recovery to the first sudo
    # operator's primary group. An authorized current operator may retarget the
    # same root-owned inode; an existing flock remains attached to that inode,
    # so this never bypasses a concurrent holder.
    if ! "${root_command[@]}" chgrp "$expected_gid" "$lock_path" \
        || ! "${root_command[@]}" chmod 0640 "$lock_path"; then
        die "Installer single-flight lock access could not be authorized."
    fi
    metadata="$(
        "${root_command[@]}" env LC_ALL=C /usr/bin/stat \
            -c '%u:%g:%a:%h' "$lock_path" 2>/dev/null
    )" || die "Installer single-flight lock metadata could not be read."
    [[ "$metadata" == \
        "${INSTALLER_SINGLE_FLIGHT_EXPECTED_UID}:${expected_gid}:640:1" ]] \
        || die "Installer single-flight lock ownership or mode is unsafe."

    exec {INSTALLER_SINGLE_FLIGHT_FD}< "$lock_path" \
        || die "Installer single-flight lock could not be opened."
    path_identity="$(/usr/bin/stat -Lc '%d:%i' "$lock_path" 2>/dev/null)" \
        || die "Installer single-flight lock identity could not be read."
    descriptor_identity="$(
        /usr/bin/stat -Lc '%d:%i' "/dev/fd/${INSTALLER_SINGLE_FLIGHT_FD}" \
            2>/dev/null
    )" || die "Installer single-flight descriptor identity could not be read."
    if [[ "$path_identity" != "$descriptor_identity" ]]; then
        exec {INSTALLER_SINGLE_FLIGHT_FD}<&-
        INSTALLER_SINGLE_FLIGHT_FD=""
        die "Installer single-flight lock changed identity while opening."
    fi
    if ! /usr/bin/flock -n "$INSTALLER_SINGLE_FLIGHT_FD"; then
        exec {INSTALLER_SINGLE_FLIGHT_FD}<&-
        INSTALLER_SINGLE_FLIGHT_FD=""
        die "Another installer process is already running."
    fi
    INSTALLER_SINGLE_FLIGHT_BACKEND="flock"
    INSTALLER_SINGLE_FLIGHT_OWNED="true"
}

release_installer_single_flight_lock() {
    [[ "${INSTALLER_SINGLE_FLIGHT_OWNED:-false}" == "true" ]] || return 0
    local lock_path="$INSTALLER_SINGLE_FLIGHT_LOCK_PATH"
    local holder=""
    local -a root_command=()
    if [[ -n "$SUDO" ]]; then
        root_command=(sudo)
    fi
    case "$INSTALLER_SINGLE_FLIGHT_BACKEND" in
        flock)
            exec {INSTALLER_SINGLE_FLIGHT_FD}<&-
            INSTALLER_SINGLE_FLIGHT_FD=""
            ;;
        shlock)
            holder="$("${root_command[@]}" cat "$lock_path" 2>/dev/null || true)"
            if [[ "$holder" != "$$" ]]; then
                warn "Installer lock ownership changed; refusing unsafe cleanup."
                return 1
            fi
            if ! "${root_command[@]}" rm -f "$lock_path"; then
                warn "Installer lock cleanup did not complete."
                return 1
            fi
            ;;
        *)
            warn "Installer lock backend is unknown; refusing unsafe cleanup."
            return 1
            ;;
    esac
    INSTALLER_SINGLE_FLIGHT_BACKEND=""
    INSTALLER_SINGLE_FLIGHT_OWNED="false"
}

# Mask secrets in log output
mask_secret() {
    local val="$1"
    if [[ ${#val} -le 4 ]]; then
        echo "****"
    else
        echo "${val:0:2}***${val: -2}"
    fi
}

# ── Box drawing ──────────────────────────────────────────────────────────────
draw_box() {
    local title="$1"
    shift
    local width=50
    local top_line bottom_line
    top_line="╔$(printf '═%.0s' $(seq 1 $((width - 2))))╗"
    bottom_line="╚$(printf '═%.0s' $(seq 1 $((width - 2))))╝"
    echo "$top_line"
    printf "║  %-$((width - 4))s║\n" "$title"
    echo "╠$(printf '═%.0s' $(seq 1 $((width - 2))))╣"
    for line in "$@"; do
        printf "║  %-$((width - 4))s║\n" "$line"
    done
    echo "$bottom_line"
}

# ── Dialog / whiptail wrapper ────────────────────────────────────────────────
DIALOG_CMD=""

detect_dialog() {
    if command -v dialog &>/dev/null; then
        DIALOG_CMD="dialog"
    elif command -v whiptail &>/dev/null; then
        DIALOG_CMD="whiptail"
    fi
}

# Returns 0=yes, 1=no. Falls back to read prompt if no dialog.
ask_yesno() {
    local title="$1" text="$2" default="${3:-yes}"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local flags=()
        if [[ "$default" != "yes" ]]; then
            flags+=(--defaultno)
        fi
        "$DIALOG_CMD" "${flags[@]}" --title "$title" --yesno "$text" 12 60
        return $?
    else
        local prompt
        if [[ "$default" == "yes" ]]; then
            prompt="$text [Y/n]: "
        else
            prompt="$text [y/N]: "
        fi
        local answer
        read -r -p "$prompt" answer
        case "${answer,,}" in
            y|yes) return 0 ;;
            n|no)  return 1 ;;
            "")    [[ "$default" == "yes" ]] && return 0 || return 1 ;;
            *)     return 1 ;;
        esac
    fi
}

# Input box. Returns value on stdout. Falls back to read.
ask_input() {
    local title="$1" text="$2" default="${3:-}"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        # On Escape/cancel, fall back to default rather than propagating non-zero exit
        # (which would kill the script under set -e)
        result=$("$DIALOG_CMD" --title "$title" --inputbox "$text" 10 60 "$default" 3>&1 1>&2 2>&3) \
            || { echo "$default"; return 0; }
        echo "$result"
    else
        local answer
        if [[ -n "$default" ]]; then
            read -r -p "$text [$default]: " answer
            echo "${answer:-$default}"
        else
            read -r -p "$text: " answer
            echo "$answer"
        fi
    fi
}

# Password input (hidden). Falls back to read -s.
ask_password() {
    local title="$1" text="$2"
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        # On Escape/cancel, return empty string rather than propagating non-zero exit
        result=$("$DIALOG_CMD" --title "$title" --passwordbox "$text" 10 60 3>&1 1>&2 2>&3) \
            || { echo ""; return 0; }
        echo "$result"
    else
        local answer
        read -r -s -p "$text: " answer
        echo ""  # newline after hidden input
        echo "$answer"
    fi
}

# Checklist. Returns space-separated selected items. Falls back to numbered menu.
ask_checklist() {
    local title="$1" text="$2"
    shift 2
    # Remaining args: tag description on/off triplets
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local result
        local height=$(( ($# / 3) + 8 ))
        result=$("$DIALOG_CMD" --title "$title" --checklist "$text" "$height" 60 $(($# / 3)) "$@" 3>&1 1>&2 2>&3) || return 1
        echo "$result"
    else
        echo "$text"
        local i=0
        local tags=()
        local descs=()
        local states=()
        while [[ $# -gt 0 ]]; do
            tags+=("$1"); descs+=("$2"); states+=("$3")
            shift 3
            i=$((i + 1))
        done
        for ((j=0; j<${#tags[@]}; j++)); do
            local marker=" "
            [[ "${states[$j]}" == "on" ]] && marker="X"
            echo "  [$marker] $((j+1)). ${descs[$j]}"
        done
        local selected
        # shellcheck disable=SC2034  # `selected` read but intentionally discarded; toggle logic is a future enhancement
        read -r -p "Enter numbers to toggle (e.g., 1 3), or press Enter to accept: " selected
        # Return tags that are currently enabled (simplified fallback — toggle logic in future)
        local result=""
        for ((j=0; j<${#tags[@]}; j++)); do
            if [[ "${states[$j]}" == "on" ]]; then
                result+="${tags[$j]} "
            fi
        done
        echo "$result"
    fi
}

# Single-select radiolist. Returns the tag of the selected item. Falls back to numbered menu.
ask_radiolist() {
    local title="$1" text="$2"
    shift 2
    # Remaining args: tag description on|off triplets (exactly one should be "on")
    if [[ -n "$DIALOG_CMD" ]] && [[ -t 0 ]]; then
        local height=$(( ($# / 3) + 8 ))
        local result
        result=$("$DIALOG_CMD" --title "$title" --radiolist "$text" "$height" 60 $(($# / 3)) "$@" 3>&1 1>&2 2>&3) || return 1
        echo "$result"
    else
        echo "$text"
        local tags=() descs=() states=()
        while [[ $# -gt 0 ]]; do
            tags+=("$1"); descs+=("$2"); states+=("$3")
            shift 3
        done
        local default_idx=0
        for ((j=0; j<${#tags[@]}; j++)); do
            local marker=" "
            if [[ "${states[$j]}" == "on" ]]; then
                marker="*"
                default_idx=$((j + 1))
            fi
            echo "  ($marker) $((j+1)). ${descs[$j]}"
        done
        local answer
        # `read` returns 1 on EOF (e.g., non-interactive pipe); `|| true` prevents set -e from aborting
        read -r -p "Enter number [${default_idx}]: " answer || true
        answer="${answer:-$default_idx}"
        # Validate and return tag
        if [[ "$answer" =~ ^[0-9]+$ ]] && (( answer >= 1 && answer <= ${#tags[@]} )); then
            echo "${tags[$((answer - 1))]}"
        else
            # Fall back to the pre-selected default
            echo "${tags[$((default_idx - 1))]}"
        fi
    fi
}

# ── Embedded file extraction ─────────────────────────────────────────────────
deploy_discard_embedded_file_staging() {
    local staging_file="${DEPLOY_EMBEDDED_FILE_STAGING_FILE:-}"
    local staging_parent="${DEPLOY_EMBEDDED_FILE_STAGING_PARENT:-}"
    [[ -n "$staging_file" && -n "$staging_parent" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "$staging_parent" "$staging_file" ".llap-extract-"; then
        warn "Refusing to remove unsafe embedded-file staging."
        DEPLOY_EMBEDDED_FILE_STAGING_FILE=""
        DEPLOY_EMBEDDED_FILE_STAGING_PARENT=""
        return 1
    fi
    if $SUDO test -e "$staging_file" || $SUDO test -L "$staging_file"; then
        if ! installer_private_staging_is_safe \
                "$staging_file" "file" "600:640:644:750" \
            && ! installer_managed_path_is_safe \
                "$staging_file" "file" "600:640:644:750"; then
            warn "Refusing to remove embedded-file staging with unsafe ownership."
            DEPLOY_EMBEDDED_FILE_STAGING_FILE=""
            DEPLOY_EMBEDDED_FILE_STAGING_PARENT=""
            return 1
        fi
        if ! $SUDO rm -f -- "$staging_file"; then
            return 1
        fi
    fi
    DEPLOY_EMBEDDED_FILE_STAGING_FILE=""
    DEPLOY_EMBEDDED_FILE_STAGING_PARENT=""
}

deploy_note_bind_mount_recreation() {
    local service="$1" existing
    [[ "$service" =~ ^[a-z0-9][a-z0-9_-]*$ ]] || return 1
    for existing in "${DEPLOY_BIND_MOUNT_RECREATE_SERVICES[@]}"; do
        [[ "$existing" == "$service" ]] && return 0
    done
    DEPLOY_BIND_MOUNT_RECREATE_SERVICES+=("$service")
}

extract_file() {
    local var_name="$1" dest="$2" mode="${3:-0640}"
    local preserve_bind_inode="${4:-false}" recreate_service="${5:-}"
    local destination_present="false"
    local parent suffix staging_file managed_uid managed_group
    [[ "$preserve_bind_inode" == "true" \
        || "$preserve_bind_inode" == "false" ]] || return 1
    if [[ "$preserve_bind_inode" == "true" \
        && ! "$recreate_service" =~ ^[a-z0-9][a-z0-9_-]*$ ]]; then
        return 1
    fi
    if [[ -z "${!var_name:-}" ]]; then
        warn "Embedded file '${var_name}' not available — skipping ${dest}"
        return 0
    fi
    parent="$(dirname -- "$dest")"
    if ! database_path_is_safe_direct_child "$parent" "$dest" "" \
        || ! installer_managed_path_is_safe \
            "$parent" "directory" "700:750:755"; then
        fail "Embedded file destination is outside a protected directory: ${dest}"
        return 1
    fi
    suffix="$(installer_private_staging_suffix)" \
        || return 1
    DEPLOY_EMBEDDED_FILE_STAGING_PARENT="$parent"
    DEPLOY_EMBEDDED_FILE_STAGING_FILE="${parent}/.llap-extract-${suffix}"
    staging_file="$DEPLOY_EMBEDDED_FILE_STAGING_FILE"
    if ! installer_create_private_staging_file "$staging_file"; then
        deploy_discard_embedded_file_staging || true
        return 1
    fi
    if ! printf '%s' "${!var_name}" \
        | base64 -d \
        | $SUDO /usr/bin/tee "$staging_file" >/dev/null \
        || ! $SUDO chmod "$mode" "$staging_file"; then
        deploy_discard_embedded_file_staging || true
        return 1
    fi
    managed_uid="$(installer_managed_deployment_uid)" || {
        deploy_discard_embedded_file_staging || true
        return 1
    }
    managed_group="$(installer_managed_deployment_group)" || {
        deploy_discard_embedded_file_staging || true
        return 1
    }
    if ! $SUDO chown "${managed_uid}:${managed_group}" "$staging_file"; then
        deploy_discard_embedded_file_staging || true
        return 1
    fi
    if ! installer_managed_path_is_safe \
            "$parent" "directory" "700:750:755" \
        || ! database_path_is_safe_direct_child "$parent" "$dest" ""; then
        deploy_discard_embedded_file_staging || true
        return 1
    fi
    if $SUDO test -e "$dest" || $SUDO test -L "$dest"; then
        destination_present="true"
    fi
    # Recreate every file-bind consumer on every non-fresh run. This makes the
    # authority durable across process loss: if a previous run atomically
    # replaced an unsafe inode and died before recreation, the next verified
    # run still releases the container's unlinked legacy mount.
    if [[ "$preserve_bind_inode" == "true" \
        && "${COMMAND:-}" != "install" ]] \
        && ! deploy_note_bind_mount_recreation "$recreate_service"; then
        deploy_discard_embedded_file_staging || true
        return 1
    fi
    if [[ "$preserve_bind_inode" == "true" ]] \
        && installer_managed_path_is_safe \
            "$dest" "file" "600:640:644:750"; then
        # A previously protected read-only bind source cannot have a writable
        # descriptor held by the legacy service account. Preserve that trusted
        # inode so a running container observes the new bytes immediately.
        if ! $SUDO cat "$staging_file" \
            | $SUDO /usr/bin/tee "$dest" >/dev/null \
            || ! $SUDO chmod "$mode" "$dest" \
            || ! $SUDO rm -f -- "$staging_file"; then
            deploy_discard_embedded_file_staging || true
            return 1
        fi
    else
        # A fresh install with a pre-existing unsafe bind source can still be
        # recovering a partial legacy deployment, so recreate that consumer too.
        if [[ "$preserve_bind_inode" == "true" \
            && "$destination_present" == "true" \
            && "${COMMAND:-}" == "install" ]] \
            && ! deploy_note_bind_mount_recreation "$recreate_service"; then
            deploy_discard_embedded_file_staging || true
            return 1
        fi
        if [[ "$destination_present" == "true" ]]; then
            # Atomic replacement revokes every descriptor to an untrusted
            # legacy-owned inode. A container which still has that old inode
            # bind-mounted must be explicitly recreated before completion.
            # rename(2) atomically replaces every non-directory leaf, including
            # symlinks and hardlinks. Only a real directory type-conflict needs
            # an explicit removal before the staged file can be renamed.
            if $SUDO test -d "$dest" && ! $SUDO test -L "$dest" \
                && ! $SUDO rm -rf -- "$dest"; then
                deploy_discard_embedded_file_staging || true
                return 1
            fi
        fi
        if ! $SUDO mv "$staging_file" "$dest"; then
            deploy_discard_embedded_file_staging || true
            return 1
        fi
    fi
    DEPLOY_EMBEDDED_FILE_STAGING_FILE=""
    DEPLOY_EMBEDDED_FILE_STAGING_PARENT=""
}

