    if $SUDO test -e "$staging_file" || $SUDO test -L "$staging_file"; then
        if ! installer_private_staging_is_safe \
                "$staging_file" "file" "600:640" \
            && ! installer_managed_path_is_safe \
                "$staging_file" "file" "600:640"; then
            warn "Refusing to remove release image-lock staging with unsafe ownership."
            DEPLOY_IMAGE_LOCK_STAGING_FILE=""
            return 1
        fi
        if ! $SUDO rm -f -- "$staging_file"; then
            return 1
        fi
    fi
    DEPLOY_IMAGE_LOCK_STAGING_FILE=""
}

deploy_sweep_stale_image_lock_staging() {
    local docker_root="${INSTALL_DIR}/docker"
    # shellcheck disable=SC2016  # Positional parameters expand in the root shell.
    $SUDO /bin/sh -ceu '
        root=${1%/}
        [ "${root#/}" != "$root" ] && [ "$root" != "/" ]
        [ -d "$root" ] && [ ! -L "$root" ]
        for prefix in .env.image-lock. .env.write.; do
            set -- "$root"/"$prefix"*
            if [ "$1" = "$root/$prefix*" ] \
                && [ ! -e "$1" ] && [ ! -L "$1" ]; then
                continue
            fi
            for path do
                [ "${path%/*}" = "$root" ]
                if [ -d "$path" ] && [ ! -L "$path" ]; then
                    exit 1
                fi
                [ -f "$path" ] || [ -L "$path" ]
                rm -f -- "$path"
            done
        done
    ' sh "$docker_root"
}

deploy_discard_compose_command_staging() {
    local staging_file="${DEPLOY_COMPOSE_COMMAND_STAGING_FILE:-}"
    local install_root="${INSTALL_DIR%/}"
    [[ -n "$staging_file" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "$install_root" "$staging_file" ".compose-command."; then
        warn "Refusing to remove unsafe Compose command staging."
        DEPLOY_COMPOSE_COMMAND_STAGING_FILE=""
        return 1
    fi
    if $SUDO test -e "$staging_file" || $SUDO test -L "$staging_file"; then
        if ! installer_private_staging_is_safe \
                "$staging_file" "file" "600" \
            && ! installer_managed_path_is_safe \
                "$staging_file" "file" "750"; then
            warn "Refusing to remove Compose command staging with unsafe ownership."
            DEPLOY_COMPOSE_COMMAND_STAGING_FILE=""
            return 1
        fi
        if ! $SUDO rm -f -- "$staging_file"; then
            return 1
        fi
    fi
    DEPLOY_COMPOSE_COMMAND_STAGING_FILE=""
}

deploy_sweep_stale_compose_command_staging() {
    local install_root="${INSTALL_DIR%/}"
    # The root has already passed deploy_create_dirs protection. Remove only
    # direct, non-directory staging leaves with the exact installer prefix.
    # shellcheck disable=SC2016  # Positional parameters expand in the root shell.
    $SUDO /bin/sh -ceu '
        root=${1%/}
        [ "${root#/}" != "$root" ] && [ "$root" != "/" ]
        [ -d "$root" ] && [ ! -L "$root" ]
        set -- "$root"/.compose-command.*
        if [ "$1" = "$root/.compose-command.*" ] \
            && [ ! -e "$1" ] && [ ! -L "$1" ]; then
            exit 0
        fi
        for path do
            [ "${path%/*}" = "$root" ]
            [ -f "$path" ] || [ -L "$path" ]
            rm -f -- "$path"
        done
    ' sh "$install_root"
}

deploy_reconcile_release_image_lock() {
    local env_file="${INSTALL_DIR}/docker/.env"
    local tmpfile suffix managed_uid managed_group
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" != "true" ]]; then
        if $SUDO grep -Eq \
            '^PROXY_(SERVER|CLI|BACKUP)_IMAGE=' "$env_file" 2>/dev/null; then
            die "This digest-locked installation requires a signed-receipt-bound upgrade."
        fi
        return 0
    fi
    if ! installer_managed_path_is_safe \
            "${INSTALL_DIR}" "directory" "700:750:755" \
        || ! installer_managed_path_is_safe \
            "${INSTALL_DIR}/docker" "directory" "700:750:755"; then
        die "Installer-managed image-lock directories are not protected."
    fi
    if ! $SUDO test -s "$env_file" \
        || $SUDO test -L "$env_file" \
        || ! installer_path_has_single_link "$env_file"; then
        die "Existing environment file is unsafe for image-lock reconciliation."
    fi
    managed_uid="$(installer_managed_deployment_uid)" \
        || die "Could not resolve the managed deployment owner."
    managed_group="$(installer_managed_deployment_group)" \
        || die "Could not resolve the managed deployment group."
    if ! $SUDO chown "${managed_uid}:${managed_group}" "$env_file" \
        || ! $SUDO chmod 0640 "$env_file"; then
        die "Could not protect the existing environment file."
    fi
    deploy_sweep_stale_image_lock_staging \
        || die "Could not safely clear stale release image-lock staging."
    suffix="$(installer_private_staging_suffix)" \
        || die "Could not generate release image-lock staging identity."
    DEPLOY_IMAGE_LOCK_STAGING_FILE="${INSTALL_DIR}/docker/.env.image-lock.${suffix}"
    tmpfile="$DEPLOY_IMAGE_LOCK_STAGING_FILE"
    if ! database_path_is_safe_direct_child \
        "${INSTALL_DIR}/docker" "$tmpfile" ".env.image-lock." \
        || ! installer_create_private_staging_file "$tmpfile"; then
        deploy_discard_image_lock_staging || true
        DEPLOY_IMAGE_LOCK_STAGING_FILE=""
        die "Could not allocate private release image-lock staging."
    fi
    if ! $SUDO awk '
        !/^PROXY_SERVER_IMAGE=/ &&
        !/^PROXY_CLI_IMAGE=/ &&
        !/^PROXY_BACKUP_IMAGE=/
    ' "$env_file" | $SUDO /usr/bin/tee "$tmpfile" >/dev/null; then
        deploy_discard_image_lock_staging || true
        die "Could not stage the receipt-authorized image lock."
    fi
    if ! {
        printf 'PROXY_SERVER_IMAGE=%s\n' "$RELEASE_SERVER_IMAGE"
        printf 'PROXY_CLI_IMAGE=%s\n' "$RELEASE_CLI_IMAGE"
        printf 'PROXY_BACKUP_IMAGE=%s\n' "$RELEASE_BACKUP_IMAGE"
    } | $SUDO /usr/bin/tee -a "$tmpfile" >/dev/null \
        || ! $SUDO chmod 0640 "$tmpfile"; then
        deploy_discard_image_lock_staging || true
        die "Could not publish the receipt-authorized image lock."
    fi
    if ! $SUDO chown "${managed_uid}:${managed_group}" "$tmpfile"; then
        deploy_discard_image_lock_staging || true
        die "Could not protect the receipt-authorized image lock."
    fi
    if ! $SUDO mv "$tmpfile" "$env_file"; then
        deploy_discard_image_lock_staging || true
        die "Could not publish the receipt-authorized image lock."
    fi
    DEPLOY_IMAGE_LOCK_STAGING_FILE=""
}

deploy_upgrade_env() {
    local env_file="${INSTALL_DIR}/docker/.env"
    local backup managed_uid managed_group
    if ! $SUDO test -e "$env_file" && ! $SUDO test -L "$env_file"; then
        deploy_write_env
        return 0
    fi
    if ! $SUDO test -f "$env_file" || $SUDO test -L "$env_file" \
        || ! installer_path_has_single_link "$env_file"; then
        die "Existing environment is not a safe regular file."
    fi
    managed_uid="$(installer_managed_deployment_uid)" \
        || die "Could not resolve the upgraded environment owner."
    managed_group="$(installer_managed_deployment_group)" \
        || die "Could not resolve the upgraded environment group."

    # Reject an unbound transition before creating a backup or changing even
    # PROXY_VERSION. A digest-locked installation may change image/version only
    # when the installer was invoked with a verified signed receipt.
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" != "true" ]] \
        && $SUDO grep -Eq \
            '^PROXY_(SERVER|CLI|BACKUP)_IMAGE=' "$env_file" 2>/dev/null; then
        die "This digest-locked installation requires a signed-receipt-bound upgrade."
    fi

    backup="${env_file}.backup.$(date +%Y%m%d-%H%M%S)"
    if ! database_path_is_safe_direct_child \
            "${INSTALL_DIR}/docker" "$backup" ".env.backup." \
        || $SUDO test -e "$backup" || $SUDO test -L "$backup" \
        || ! $SUDO cp "$env_file" "$backup" \
        || ! $SUDO chown "${managed_uid}:${managed_group}" "$backup" \
        || ! $SUDO chmod 0640 "$backup" \
        || ! installer_managed_path_is_safe "$backup" "file" "640"; then
        die "Could not preserve the existing environment."
    fi
    info "Backed up .env to ${backup}"

    # Build a reference .env reflecting the fully-resolved settings. run_configure
    # has already applied the CLI > env > existing-.env > default precedence to the
    # OPT_* variables, so the reference encodes the desired final state for every
    # OVERRIDE-CAPABLE key: omitted flags keep the existing value, provided flags
    # carry the override (#1306).
    local ref_file suffix reference_install_dir
    local -a reference_copy_status=()
    ref_file=$(mktemp "/tmp/llap-upgrade-env-reference-output.XXXXXXXX") \
        || die "Could not allocate the upgrade environment reference output."
    CLEANUP_FILES+=("$ref_file")
    local old_env_file="${env_file}"
    deploy_discard_upgrade_env_reference_staging \
        || die "Could not clear prior upgrade environment reference staging."
    suffix="$(installer_private_staging_suffix)" \
        || die "Could not generate upgrade environment reference identity."
    DEPLOY_UPGRADE_ENV_REFERENCE_STAGING_DIR="/tmp/llap-upgrade-env-reference.${suffix}"
    reference_install_dir="$DEPLOY_UPGRADE_ENV_REFERENCE_STAGING_DIR"
    if ! installer_create_private_staging_directory "$reference_install_dir"; then
        deploy_discard_upgrade_env_reference_staging || true
        die "Could not allocate protected upgrade environment reference staging."
    fi
    managed_uid="$(installer_managed_deployment_uid)" \
        || {
            deploy_discard_upgrade_env_reference_staging || true
            die "Could not resolve the upgrade environment reference owner."
        }
    managed_group="$(installer_managed_deployment_group)" \
        || {
            deploy_discard_upgrade_env_reference_staging || true
            die "Could not resolve the upgrade environment reference group."
        }
    if ! $SUDO install -d -m 0750 \
        -o "$managed_uid" -g "$managed_group" \
        "${reference_install_dir}/docker"; then
        deploy_discard_upgrade_env_reference_staging || true
        die "Could not protect upgrade environment reference staging."
    fi
    deploy_write_env "$reference_install_dir"
    {
        $SUDO cat "${reference_install_dir}/docker/.env" \
            | /usr/bin/tee "$ref_file" >/dev/null
        reference_copy_status=("${PIPESTATUS[@]}")
    } || true
    if [[ "${reference_copy_status[0]:-1}" != 0 \
        || "${reference_copy_status[1]:-1}" != 0 ]] \
        || ! chmod 0600 "$ref_file"; then
        deploy_discard_upgrade_env_reference_staging || true
        die "Could not copy the protected upgrade environment reference."
    fi
    deploy_discard_upgrade_env_reference_staging \
        || die "Could not remove upgrade environment reference staging."

    # Vetted set of OVERRIDE-CAPABLE keys: the only managed keys the reconcile
    # may overwrite in place. Every one is resolved CLI > env > existing-.env >
    # default (via resolve_setting / existing_env_value / an explicit existing
    # .env read in the configure_* functions), so the reference value already
    # equals the existing value UNLESS the operator supplied an override — making
    # an in-place overwrite a no-op when flags are omitted and a true override
    # when they are not. Any key NOT in this list (hardcoded constants like
    # RUST_LOG / LOG_FORMAT / PROXY_LISTEN_ADDR, and operator hand-edits) is
    # preserved verbatim, so an upgrade never reverts a value the operator did
    # not explicitly change (#1306). Version, receipt-authorized image
    # selectors, and resolved debug state are included so the complete final
    # environment can be published once as an already-protected inode.
    #
    # Keep this list in sync with the resolve_setting / existing-.env reads in
    # configure_core, configure_tls, configure_backup, and configure_monitoring.
    # The ports below are resolved from the existing .env (preserve-on-omit) yet
    # honour an explicit --*-port flag / PROXY_INSTALL_*_PORT env via their *_SET
    # markers, so they belong in the override set.
    local override_keys
    override_keys=$(cat <<'OVERRIDE_KEYS'
PROXY_VERSION
PROXY_SERVER_IMAGE
PROXY_CLI_IMAGE
PROXY_BACKUP_IMAGE
POSTGRES_PASSWORD
PROXY_KEK_VALUE
PROXY_PROXY_KEY_PEPPER
PROXY_JWT_SECRET
PROXY_LISTEN_PORT
PROXY_FORWARD_PROXY__PORT
PROXY_DATABASE__CONTROL_POOL_SIZE
PROXY_DATABASE__DATA_POOL_SIZE
TIMESCALEDB_MEMORY_LIMIT
TIMESCALEDB_SHARED_BUFFERS
TIMESCALEDB_EFFECTIVE_CACHE_SIZE
TIMESCALEDB_WORK_MEM
PROXY_TLS__ENABLED
PROXY_TLS__DOMAIN
PROXY_TLS__ACME_EMAIL
CF_DNS_API_TOKEN
CF_API_KEY
CF_API_EMAIL
RESTIC_REPOSITORY
RESTIC_PASSWORD
AWS_ACCESS_KEY_ID
AWS_SECRET_ACCESS_KEY
BACKUP_SCHEDULE
GRAFANA_PASSWORD
GRAFANA_PORT
PROMETHEUS_PORT
PROXY_DEBUG
PROXY_DEBUG_PROFILE
OVERRIDE_KEYS
)

    # One-time key migration. A pre-#1632 install may contain the legacy
    # single-underscore spelling, which Figment loaded into a dead top-level
    # field instead of the listener configuration. The reference contains only
    # the canonical nested spelling; drop the legacy line when that replacement
    # is present so the upgraded .env has one unambiguous authority.
    local legacy_key_replacements
    legacy_key_replacements=$(cat <<'LEGACY_KEY_REPLACEMENTS'
PROXY_FORWARD_PROXY_PORT=PROXY_FORWARD_PROXY__PORT
LEGACY_KEY_REPLACEMENTS
)

    # Mutually-exclusive Cloudflare DNS-01 auth keys. The lego provider uses
    # CF_DNS_API_TOKEN when present and otherwise the CF_API_EMAIL/CF_API_KEY
    # pair; setting both is unsupported (see docker/docker-compose.tls.yml). The
    # reference .env selects exactly ONE mode, so when the operator switches modes
    # the previous mode's keys must be PRUNED rather than preserved — otherwise a
    # stale CF_DNS_API_TOKEN would silently win over an explicit global-key
    # override. Pruning only kicks in when the reference actually selects a CF
    # mode, so toggling TLS off still preserves the keys verbatim (#1306).
    local cf_auth_keys
    cf_auth_keys=$(cat <<'CF_AUTH_KEYS'
CF_DNS_API_TOKEN
CF_API_KEY
CF_API_EMAIL
CF_AUTH_KEYS
)

    # Reconcile the existing .env to a protected same-directory staging inode:
    #   1. Update OVERRIDE-CAPABLE keys whose resolved value changed (flag
    #      overrides); for omitted flags the reference equals the existing value
    #      so this is a no-op write.
    #   2. Preserve every other existing live value verbatim — including
    #      non-override-capable managed keys (ports, RUST_LOG, …) and any
    #      custom/unmanaged keys the operator added by hand.
    #   3. Drop a live Cloudflare auth key when the operator switched CF auth
    #      modes (it is absent from the reference and the reference selects a CF
    #      mode), so the explicit override actually takes effect.
    #   4. Append reference keys genuinely introduced by the new version.
    # awk is used (not sed) so arbitrary secret characters can't break escaping.
    local reconciled
    deploy_discard_env_staging \
        || die "Could not clear prior upgraded environment staging."
    suffix="$(installer_private_staging_suffix)" \
        || {
            rm -f -- "$ref_file"
            die "Could not generate upgraded environment staging identity."
        }
    DEPLOY_ENV_STAGING_PARENT="${INSTALL_DIR}/docker"
    DEPLOY_ENV_STAGING_FILE="${INSTALL_DIR}/docker/.env.write.${suffix}"
    reconciled="$DEPLOY_ENV_STAGING_FILE"
    if ! database_path_is_safe_direct_child \
            "$DEPLOY_ENV_STAGING_PARENT" "$reconciled" ".env.write." \
        || ! installer_create_private_staging_file "$reconciled"; then
        rm -f -- "$ref_file"
        deploy_discard_env_staging || true
        die "Could not allocate protected upgraded environment staging."
    fi
    # shellcheck disable=SC2016  # the awk program is intentionally single-quoted; $ refs are awk fields/vars, not shell expansions
    if ! $SUDO awk \
        -v upgrade_marker="# Added by upgrade to v${OPT_VERSION} on $(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        -v override_keys="$override_keys" \
        -v legacy_key_replacements="$legacy_key_replacements" \
        -v cf_auth_keys="$cf_auth_keys" '
        BEGIN {
            n = split(override_keys, _ok, "\n")
            for (i = 1; i <= n; i++) {
                if (_ok[i] != "") is_override[_ok[i]] = 1
            }
            legacy_count = split(legacy_key_replacements, _legacy, "\n")
            for (i = 1; i <= legacy_count; i++) {
                separator = index(_legacy[i], "=")
                if (separator > 1) {
                    legacy_key = substr(_legacy[i], 1, separator - 1)
                    legacy_replacement[legacy_key] = substr(_legacy[i], separator + 1)
                }
            }
            m = split(cf_auth_keys, _cf, "\n")
            for (i = 1; i <= m; i++) {
                if (_cf[i] != "") is_cf_auth[_cf[i]] = 1
            }
        }
        # First pass: load reference key=value pairs. Note whether the reference
        # selects a Cloudflare auth mode (any CF auth key present).
        FNR == NR {
            if ($0 ~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
                eq = index($0, "=")
                key = substr($0, 1, eq - 1)
                ref_val[key] = substr($0, eq + 1)
                ref_seen[key] = 1
                ref_order[++ref_count] = key
                if (key in is_cf_auth) ref_has_cf_auth = 1
            }
            next
        }
        # Second pass: rewrite the live .env. Track which reference keys exist in
        # the live file so genuinely-new ones can be appended; only override the
        # value for vetted override-capable keys; prune stale CF auth keys.
        {
            if ($0 ~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
                eq = index($0, "=")
                key = substr($0, 1, eq - 1)
                if (key in ref_seen) live_has[key] = 1
                # Replace a legacy key only when its canonical successor exists
                # in this version reference file.
                if ((key in legacy_replacement) && (legacy_replacement[key] in ref_seen)) {
                    next
                }
                # Drop a CF auth key the operator switched away from.
                if ((key in is_cf_auth) && !(key in ref_seen) && ref_has_cf_auth) {
                    next
                }
                if ((key in is_override) && (key in ref_seen)) {
                    if (override_emitted[key]++) {
                        next
                    }
                    print key "=" ref_val[key]
                    next
                }
            }
            print
        }
        # After live lines: append reference keys not present in the live .env.
        END {
            appended = 0
            for (i = 1; i <= ref_count; i++) {
                key = ref_order[i]
                if (!(key in live_has)) {
                    if (!appended) { print ""; print upgrade_marker; appended = 1 }
                    print key "=" ref_val[key]
                }
            }
        }
    ' "$ref_file" "$old_env_file" \
        | $SUDO /usr/bin/tee "$reconciled" >/dev/null; then
        rm -f -- "$ref_file"
        deploy_discard_env_staging || true
        die "Could not reconcile the upgraded environment."
    fi
    rm -f -- "$ref_file"

    if ! $SUDO chown "${managed_uid}:${managed_group}" "$reconciled" \
        || ! $SUDO chmod 0640 "$reconciled" \
        || ! installer_managed_path_is_safe \
            "$reconciled" "file" "640"; then
        deploy_discard_env_staging || true
        die "Could not protect the reconciled environment."
    fi
    if ! $SUDO mv "$reconciled" "$old_env_file"; then
        deploy_discard_env_staging || true
        die "Could not publish the reconciled environment."
    fi
    DEPLOY_ENV_STAGING_FILE=""
    DEPLOY_ENV_STAGING_PARENT=""
    installer_managed_path_is_safe "$old_env_file" "file" "640" \
        || die "Could not validate the published upgraded environment."
}

# Load debug state persisted from a previous install/upgrade.
# Called after detect_os() (which resolves INSTALL_DIR) and before the warning gate.
# Respects CLI flags and env vars — does NOT override them.
load_debug_state_from_env() {
    local env_file="${INSTALL_DIR}/docker/.env"
    [[ -f "$env_file" ]] || return 0

    # Read persisted values (|| true prevents set -e exit when key is absent)
    local persisted_debug persisted_profile
    persisted_debug=$(grep -E '^PROXY_DEBUG=' "$env_file" 2>/dev/null | tail -1 | cut -d= -f2- || true)
    persisted_profile=$(grep -E '^PROXY_DEBUG_PROFILE=' "$env_file" 2>/dev/null | tail -1 | cut -d= -f2- || true)

    # Apply persisted debug flag only if not overridden by CLI or env var
    if [[ "$OPT_DEBUG" == "false" && "$OPT_NO_DEBUG" == "false" && -n "$persisted_debug" ]]; then
        OPT_DEBUG="$persisted_debug"
    fi

    # Apply persisted profile only if not already set explicitly AND debug is on.
    # When PROXY_DEBUG=false the profile is irrelevant — loading it would trip the
    # deferred validation below ("--debug-profile requires --debug") on upgrade.
    if [[ "$OPT_DEBUG_PROFILE_SET" == "false" && "$OPT_DEBUG" == "true" && -n "$persisted_profile" ]]; then
        # Validate profile value (handle malformed .env)
        case "$persisted_profile" in
            minimal|moderate|full)
                OPT_DEBUG_PROFILE="$persisted_profile"
                OPT_DEBUG_PROFILE_SET="true"  # treat as explicit to skip the dialog
                ;;
            *)
                warn "Invalid PROXY_DEBUG_PROFILE in .env: '${persisted_profile}' — defaulting to moderate"
                OPT_DEBUG_PROFILE="moderate"
                ;;
        esac
    fi

    # Deferred validation: --debug-profile= without effective debug mode
    if [[ "$OPT_DEBUG_PROFILE_SET" == "true" && "$OPT_DEBUG" == "false" && "$OPT_NO_DEBUG" == "false" ]]; then
        die "--debug-profile requires --debug (or PROXY_DEBUG=true in .env)"
    fi
}

# Display INTERNAL USE ONLY warning and confirmation when debug mode is active.
# Called after load_debug_state_from_env() and before run_preflight().
# Skips confirmation gate in non-interactive mode, but always shows the warning.
warn_debug_mode() {
    [[ "$OPT_DEBUG" == "true" ]] || return 0

    draw_box "DEBUG CONTAINERS — INTERNAL USE ONLY" \
        "You are about to install using private debug container" \
        "images from GHCR. These images are intended for internal" \
        "development and testing only. They are NOT suitable for" \
        "production use and are NOT publicly available." \
        "" \
        "Debug profile: ${OPT_DEBUG_PROFILE}" \
        "" \
        "Ensure you have a valid GitHub PAT with package:read" \
        "access to the llm-api-proxy organisation."

    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    if ! ask_yesno "Debug Containers" "Continue with debug containers?" "no"; then
        die "Aborted."
    fi
}

# Update PROXY_DEBUG and PROXY_DEBUG_PROFILE in an existing .env file.
# Uses sed for in-place updates (intentionally different from deploy_upgrade_env()
# which only appends missing keys — we need to UPDATE and REMOVE too).
deploy_upgrade_debug_state() {
    local env_file="${INSTALL_DIR}/docker/.env"
    [[ -f "$env_file" ]] || return 0

    if grep -qE '^PROXY_DEBUG=' "$env_file"; then
        # Update existing key
        $SUDO sed -i "s|^PROXY_DEBUG=.*|PROXY_DEBUG=${OPT_DEBUG}|" "$env_file"
    else
        # Append new key (upgrading from production to debug for first time)
        echo "PROXY_DEBUG=${OPT_DEBUG}" | $SUDO tee -a "$env_file" > /dev/null
    fi

    if [[ "$OPT_DEBUG" == "true" ]]; then
        if grep -qE '^PROXY_DEBUG_PROFILE=' "$env_file"; then
            $SUDO sed -i "s|^PROXY_DEBUG_PROFILE=.*|PROXY_DEBUG_PROFILE=${OPT_DEBUG_PROFILE}|" "$env_file"
        else
            echo "PROXY_DEBUG_PROFILE=${OPT_DEBUG_PROFILE}" | $SUDO tee -a "$env_file" > /dev/null
        fi
    else
        # Clear profile when disabling debug (prevent stale state)
        if grep -qE '^PROXY_DEBUG_PROFILE=' "$env_file"; then
            $SUDO sed -i "s|^PROXY_DEBUG_PROFILE=.*|PROXY_DEBUG_PROFILE=|" "$env_file"
        else
            # Append empty profile key so future loads have a consistent key present
            echo "PROXY_DEBUG_PROFILE=" | $SUDO tee -a "$env_file" > /dev/null
        fi
    fi
}

# ── Deploy phase: compose command, stack start, Consul ACL ───────────────────

# Return success when an address is a syntactically valid, container-routable
# DNS server literal. Loopback and link-local addresses are deliberately
# rejected: they can work in the host network namespace but are not reachable
# from bridge-networked services such as the backup agent.
container_dns_server_is_usable() {
    local address="${1,,}"

    if [[ "$address" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
        local first second third fourth extra octet
        IFS=. read -r first second third fourth extra <<< "$address"
        [[ -z "${extra:-}" ]] || return 1
        for octet in "$first" "$second" "$third" "$fourth"; do
            (( 10#$octet <= 255 )) || return 1
        done
        (( 10#$first != 0 && 10#$first != 127 && 10#$first < 224 )) || return 1
        (( 10#$first != 169 || 10#$second != 254 )) || return 1
        return 0
    fi

    [[ "$address" == *:* ]] || return 1
    [[ "$address" =~ ^[0-9a-f:]+$ ]] || return 1
    if [[ "$address" == :* && "$address" != ::* ]]; then
        return 1
    fi
    if [[ "$address" == *: && "$address" != *:: ]]; then
        return 1
    fi
    [[ "$address" != *:::* ]] || return 1
    if [[ "$address" == *::* ]]; then
        [[ "${address#*::}" != *::* ]] || return 1
        local left="${address%%::*}" right="${address#*::}"
        local -a left_parts=() right_parts=()
        [[ -z "$left" ]] || IFS=: read -r -a left_parts <<< "$left"
        [[ -z "$right" ]] || IFS=: read -r -a right_parts <<< "$right"
        (( ${#left_parts[@]} + ${#right_parts[@]} < 8 )) || return 1
        local part
        for part in "${left_parts[@]}" "${right_parts[@]}"; do
            [[ "$part" =~ ^[0-9a-f]{1,4}$ ]] || return 1
        done
    else
        local -a parts=()
        IFS=: read -r -a parts <<< "$address"
        (( ${#parts[@]} == 8 )) || return 1
        local part
        for part in "${parts[@]}"; do
            [[ "$part" =~ ^[0-9a-f]{1,4}$ ]] || return 1
        done
    fi

    local hex_digits="${address//:/}"
    local nonzero_digits="${hex_digits//0/}"
    [[ -n "$nonzero_digits" ]] || return 1
    local last_hextet="${address##*:}"
    if [[ "$nonzero_digits" == "1" && "$last_hextet" =~ ^0*1$ ]]; then
        return 1
    fi
    [[ ! "$address" =~ ^fe[89ab] ]] || return 1
    [[ ! "$address" =~ ^ff ]] || return 1
    return 0
}

# Print the unique interfaces carrying a default IPv6 or IPv4 route. Resolver
# discovery is intentionally scoped to these links so a stale global
# systemd-resolved DNS list cannot override the working uplink configuration.
container_dns_default_route_interfaces() {
    {
        ip -o -6 route show default 2>/dev/null || true
        ip -o -4 route show default 2>/dev/null || true
    } | awk '
        {
            for (i = 1; i < NF; i++) {
                if ($i == "dev" && !seen[$(i + 1)]++) {
                    print $(i + 1)
                    break
                }
            }
        }
    '
}

container_systemd_resolved_is_active() {
    command -v resolvectl >/dev/null 2>&1 || return 1
    if command -v systemctl >/dev/null 2>&1 \
        && systemctl is-active --quiet systemd-resolved 2>/dev/null; then
        return 0
    fi
    local resolved_socket="${CONTAINER_DNS_RESOLVED_SOCKET_PATH:-/run/systemd/resolve/io.systemd.Resolve}"
    [[ -S "$resolved_socket" ]]
}

# Emit at most three validated upstream literals, one per line. Three matches
# libc's portable MAXNS limit. systemd-resolved hosts use DNS from the active
# default-route links; other hosts fall back to their resolver file.
discover_container_dns_servers() {
    local -a candidates=()
    local candidate interface line

    if container_systemd_resolved_is_active; then
        while IFS= read -r interface; do
            [[ -n "$interface" ]] || continue
            while IFS= read -r line; do
                line="${line#*:}"
                for candidate in $line; do
                    candidates+=("$candidate")
                done
            done < <(resolvectl dns "$interface" 2>/dev/null || true)
        done < <(container_dns_default_route_interfaces)
    else
        local resolv_conf="${CONTAINER_DNS_RESOLV_CONF_PATH:-/etc/resolv.conf}"
        if [[ -r "$resolv_conf" ]]; then
            while read -r _ candidate _; do
                candidates+=("$candidate")
            done < <(awk '$1 == "nameserver" && NF >= 2 { print $1, $2 }' "$resolv_conf")
        fi
    fi

    local emitted=0
    local seen=$'\n'
    for candidate in "${candidates[@]}"; do
        container_dns_server_is_usable "$candidate" || continue
        [[ "$seen" != *$'\n'"$candidate"$'\n'* ]] || continue
        printf '%s\n' "$candidate"
        seen+="$candidate"$'\n'
        emitted=$((emitted + 1))
        (( emitted < 3 )) || break
    done

    (( emitted > 0 ))
}

# Generate a Linux-only Compose override that gives outbound services direct,
# container-reachable DNS upstreams. The file is replaced atomically on every
# install/upgrade and is included before any Compose mutation occurs.
deploy_write_container_dns_overlay() {
    local overlay_file="${INSTALL_DIR}/docker/docker-compose.dns.yml"

    if { $SUDO test -e "$overlay_file" \
            || $SUDO test -L "$overlay_file"; } \
        && { ! $SUDO test -f "$overlay_file" \
            || $SUDO test -L "$overlay_file" \
            || ! installer_path_has_single_link "$overlay_file"; }; then
        die "Container DNS overlay target is not a safe regular file."
    fi
    if [[ "$IS_MACOS" == "true" ]]; then
        $SUDO rm -f "$overlay_file"
        return 0
    fi

    step "  Discovering container DNS upstreams..."
    local discovered
    if ! discovered=$(discover_container_dns_servers); then
        die "Container DNS preflight failed: no container-reachable DNS upstreams were discovered"
    fi

    local -a servers=()
    mapfile -t servers <<< "$discovered"
    (( ${#servers[@]} > 0 )) \
        || die "Container DNS preflight failed: no container-reachable DNS upstreams were discovered"

    local tmpfile
    tmpfile=$($SUDO mktemp "${INSTALL_DIR}/docker/.docker-compose.dns.yml.XXXXXX")
    CLEANUP_FILES+=("$tmpfile")
    {
        echo "# docker-compose.dns.yml — generated by install.sh"
        echo "# DO NOT EDIT — regenerated on each install/upgrade"
        echo "services:"
        echo "  proxy:"
        echo "    dns:"
        local server
        for server in "${servers[@]}"; do
            printf '      - "%s"\n' "$server"
        done
        if [[ "$OPT_BACKUP" == "true" ]]; then
            echo "  backup:"
            echo "    dns:"
            for server in "${servers[@]}"; do
                printf '      - "%s"\n' "$server"
            done
        fi
    } | $SUDO tee "$tmpfile" > /dev/null

    $SUDO chmod 0640 "$tmpfile"
    if [[ "$IS_MACOS" != "true" ]]; then
        $SUDO chown "root:${SERVICE_USER}" "$tmpfile" 2>/dev/null || true
    fi
    $SUDO mv "$tmpfile" "$overlay_file"
    installer_managed_path_is_safe "$overlay_file" "file" "640" \
        || die "Container DNS overlay publication was not safe."
    info "Container DNS overlay written with ${#servers[@]} upstream(s)"
}

deploy_write_compose_command() {
    step "  Generating compose-command.sh..."
    local cmd_file="${INSTALL_DIR}/compose-command.sh"
    local managed_uid managed_group tmpfile suffix docker_executable
    local runtime_output runtime_value
    local -a runtime_contract=()

    local -a overlays=("docker-compose.yml" "docker-compose.hardened.yml")
    [[ "$OPT_WAF" == "true" ]] && overlays+=("docker-compose.waf.yml")
    [[ "$OPT_TLS" == "true" ]] && overlays+=("docker-compose.tls.yml")
    [[ "$OPT_MONITORING" == "true" ]] && overlays+=("docker-compose.monitoring.yml")
    [[ "$OPT_BACKUP" == "true" ]] && overlays+=("docker-compose.backup.yml")
    $SUDO test -f "${INSTALL_DIR}/docker/docker-compose.dns.yml" \
        && overlays+=("docker-compose.dns.yml")
    if [[ "$IS_MACOS" == "true" ]] && [[ "$MACOS_HOST_NETWORKING" == "true" ]]; then
        # Host networking available — no bridge overlay needed.
        # mDNS disabled via PROXY_MDNS__ENABLED=false in .env
        :
    elif [[ "$IS_MACOS" == "true" ]] || [[ "$OPT_MDNS" != "true" ]]; then
        overlays+=("docker-compose.no-mdns.yml")
    fi
    # Debug overlay must be last — overrides hardened overlay settings
    [[ "$OPT_DEBUG" == "true" ]] && overlays+=("docker-compose.debug.yml")
    docker_executable="$(installer_docker_executable)" \
        || die "Could not resolve a trusted Docker executable."
    runtime_output="$(installer_compose_runtime_contract)" \
        || die "Could not resolve the local Docker runtime contract."
    while IFS= read -r runtime_value; do
        runtime_contract+=("$runtime_value")
    done <<< "$runtime_output"
    (( ${#runtime_contract[@]} == 3 )) \
        || die "Could not resolve the local Docker runtime contract."

    deploy_discard_compose_command_staging \
        || die "Could not clear prior Compose command staging."
    suffix="$(installer_private_staging_suffix)" \
        || die "Could not generate Compose command staging identity."
    DEPLOY_COMPOSE_COMMAND_STAGING_FILE="${INSTALL_DIR}/.compose-command.${suffix}"
    tmpfile="$DEPLOY_COMPOSE_COMMAND_STAGING_FILE"
    if ! database_path_is_safe_direct_child \
            "${INSTALL_DIR%/}" "$tmpfile" ".compose-command." \
        || ! installer_create_private_staging_file "$tmpfile"; then
        deploy_discard_compose_command_staging || true
        die "Could not allocate private Compose command staging."
    fi
    if ! {
        echo '#!/bin/bash'
        echo "# compose-command.sh — single source of truth for running the stack."
        echo "# Generated by install.sh v${INSTALLER_VERSION}"
        echo 'set -euo pipefail'
        echo 'unset PROXY_VERSION PROXY_SERVER_IMAGE PROXY_CLI_IMAGE PROXY_BACKUP_IMAGE'
        echo 'unset TIMESCALEDB_DATA_PATH COMPOSE_FILE COMPOSE_PROJECT_NAME COMPOSE_PROFILES COMPOSE_ENV_FILES COMPOSE_PATH_SEPARATOR COMPOSE_DISABLE_ENV_FILE COMPOSE_CONVERT_WINDOWS_PATHS COMPOSE_IGNORE_ORPHANS COMPOSE_REMOVE_ORPHANS'
        echo 'unset DOCKER_HOST DOCKER_CONTEXT DOCKER_TLS_VERIFY DOCKER_CERT_PATH DOCKER_CONFIG'
        echo "cd \"${INSTALL_DIR}/docker\""
        printf 'exec /usr/bin/env -i \\\n'
        printf '  %q \\\n' "PATH=${runtime_contract[0]}"
        printf '  %q \\\n' "HOME=${runtime_contract[1]}"
        printf '  %q \\\n' "LC_ALL=C"
        printf '  %q \\\n' "DOCKER_HOST=${runtime_contract[2]}"
        printf '  %q compose --project-name docker' "$docker_executable"
        for overlay in "${overlays[@]}"; do
            echo " \\"
            echo -n "  -f ${overlay}"
        done
        echo " \\"
        # shellcheck disable=SC1003  # Backslash is a line continuation in the generated script
        echo '  --env-file .env \'
        echo '  "$@"'
    } | $SUDO /usr/bin/tee "$tmpfile" >/dev/null; then
        deploy_discard_compose_command_staging || true
        die "Could not write private Compose command staging."
    fi
    managed_uid="$(installer_managed_deployment_uid)" \
        || {
            deploy_discard_compose_command_staging || true
            die "Could not resolve the managed deployment owner."
        }
    managed_group="$(installer_managed_deployment_group)" \
        || {
            deploy_discard_compose_command_staging || true
            die "Could not resolve the managed deployment group."
        }
    # Publish only an already executable, managed inode. A process loss before
    # the same-directory rename leaves the prior command live; a process loss
    # after it leaves a complete command that recovery can execute.
    if ! $SUDO chown "${managed_uid}:${managed_group}" "$tmpfile" \
        || ! $SUDO chmod 0750 "$tmpfile" \
        || ! installer_managed_path_is_safe \
            "$tmpfile" "file" "750"; then
        deploy_discard_compose_command_staging || true
        die "Could not protect Compose command staging."
    fi
    if ! $SUDO mv "$tmpfile" "$cmd_file"; then
        deploy_discard_compose_command_staging || true
        die "Could not publish the Compose command."
    fi
    DEPLOY_COMPOSE_COMMAND_STAGING_FILE=""
    installer_managed_path_is_safe "$cmd_file" "file" "750" \
        || die "Could not validate the published Compose command."
    if ! $SUDO rm -f "${INSTALL_DIR}/compose-command.source.sh" \
        "${INSTALL_DIR}/docker/docker-compose.receipt-recovery.yml" \
        "${INSTALL_DIR}/docker/docker-compose.source-recovery-images.yml"; then
        die "Could not retire the source-only receipt recovery command."
    fi
    info "compose-command.sh generated with overlays: ${overlays[*]}"
}

installer_run_live_compose() {
    local command_path="${INSTALL_DIR}/compose-command.sh" operator
    if [[ "$IS_MACOS" == "true" ]]; then
        operator="$(installer_macos_operator_user)" || return 1
        if [[ "$EUID" -eq 0 ]]; then
            /usr/bin/sudo -u "$operator" "$command_path" "$@"
        else
            command "$command_path" "$@"
        fi
    elif [[ -n "$SUDO" ]]; then
        $SUDO "$command_path" "$@"
    else
        command "$command_path" "$@"
    fi
}

deploy_backup_compose_files() {
    if [[ ! -d "${INSTALL_DIR}/docker" ]]; then
        return 0
    fi
    local backup_dir
    backup_dir="${INSTALL_DIR}/compose-backup-$(date +%Y%m%d-%H%M%S)"
    $SUDO mkdir -p "$backup_dir"
    $SUDO cp "${INSTALL_DIR}"/docker/docker-compose*.yml "$backup_dir/" 2>/dev/null || true
    $SUDO cp "${INSTALL_DIR}/compose-command.sh" "$backup_dir/" 2>/dev/null || true
    info "Compose files backed up to ${backup_dir}"
}

deploy_pull_images() {
    step "  Pulling Docker images..."
    installer_run_live_compose pull >> "$LOG_FILE" 2>&1 || {
        if [[ "$OPT_DEBUG" == "true" ]]; then
            local version_tag="${OPT_VERSION:-edge}-debug"
            local images="ghcr.io/llm-api-proxy/server-debug:${version_tag}"
            [[ "$OPT_BACKUP" == "true" ]] && images+=", ghcr.io/llm-api-proxy/backup-debug:${version_tag}"
            draw_box "FAILED: Pull debug Docker images" \
                "" \
                "Error pulling one or more private debug images:" \
                "  ${images}" \
                "" \
                "This usually means:" \
                "  • Your GitHub PAT lacks package:read access" \
                "  • The version tag '${version_tag}' doesn't exist" \
                "  • GHCR is temporarily unavailable" \
                "" \
                "Try:" \
                "  1. Verify your token: export CR_PAT=ghp_xxx" \
                "  2. Check available tags at: ghcr.io/llm-api-proxy/server-debug" \
                "  3. Re-run with: install.sh install --debug --github-token=ghp_xxx" \
                "" \
                "Full log: ${LOG_FILE}"
        else
            draw_box "FAILED: Pull Docker images" \
                "" \
                "Error pulling one or more images." \
                "" \
                "This usually means:" \
                "  • The version tag doesn't exist" \
                "  • GHCR is temporarily unavailable" \
                "  • Network/proxy is blocking the request" \
                "" \
                "Try:" \
                "  1. Check: ghcr.io/llm-api-proxy/server" \
                "  2. Run: docker pull <image> manually" \
                "  3. Re-run install.sh to retry" \
                "" \
                "Full log: ${LOG_FILE}"
        fi
        exit 1
    }
    info "Docker images pulled"
}

deploy_verify_locked_images() {
    [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" ]] || return 0
    local rendered_images image_name image_ref source_sha version
    local repo_digests architecture operating_system
    rendered_images="$(
        installer_run_live_compose config --images \
            2>> "$LOG_FILE"
    )" || die "Could not render the receipt-authorized Compose image set."
    for image_name in server backup; do
        case "$image_name" in
            server) image_ref="$RELEASE_SERVER_IMAGE" ;;
            backup)
                [[ "$OPT_BACKUP" == "true" ]] || continue
                image_ref="$RELEASE_BACKUP_IMAGE"
                ;;
        esac
        [[ "$(grep -Ec \
                "^ghcr\\.io/llm-api-proxy/${image_name}([@:])" \
                <<< "$rendered_images")" -eq 1 \
            && "$(grep -Fxc "$image_ref" <<< "$rendered_images")" -eq 1 ]] \
            || die "Compose did not render the exact receipt-authorized ${image_name} image."
        installer_docker image inspect "$image_ref" >/dev/null 2>&1 \
            || die "Receipt-authorized ${image_name} image was not pulled."
        repo_digests="$(
            installer_docker image inspect --format '{{json .RepoDigests}}' \
                "$image_ref" 2>/dev/null
        )"
        architecture="$(
            installer_docker image inspect --format '{{.Architecture}}' \
                "$image_ref" 2>/dev/null
        )"
        operating_system="$(
            installer_docker image inspect --format '{{.Os}}' \
                "$image_ref" 2>/dev/null
        )"
        jq -e --arg image_ref "$image_ref" \
            'type == "array" and index($image_ref) != null' \
            <<< "$repo_digests" >/dev/null 2>&1 \
            || die "Pulled ${image_name} image does not retain the receipt-authorized digest."
        [[ "$architecture" == "$ARCH" ]] \
            || die "Pulled ${image_name} image architecture does not match this host."
        [[ "$operating_system" == "linux" ]] \
            || die "Pulled ${image_name} image operating system is not Linux."
        source_sha="$(
            installer_docker image inspect --format \
                '{{ index .Config.Labels "org.opencontainers.image.revision" }}' \
                "$image_ref" 2>/dev/null
        )"
        version="$(
            installer_docker image inspect --format \
                '{{ index .Config.Labels "org.opencontainers.image.version" }}' \
                "$image_ref" 2>/dev/null
        )"
        if [[ "$RELEASE_IMAGE_LOCK_FROM_EXISTING" == "true" \
            && -z "$RELEASE_IMAGE_LOCK_SOURCE_SHA" ]]; then
            [[ "$image_name" == "server" \
                && "$source_sha" =~ ^[0-9a-f]{40}$ \
                && "$version" == "$RELEASE_IMAGE_LOCK_VERSION" ]] \
                || die "Persisted receipt-authorized image provenance is invalid."
            RELEASE_IMAGE_LOCK_SOURCE_SHA="$source_sha"
        else
            [[ "$source_sha" == "$RELEASE_IMAGE_LOCK_SOURCE_SHA" \
                && "$version" == "$RELEASE_IMAGE_LOCK_VERSION" ]] \
                || die "Pulled ${image_name} image provenance does not match the signed receipt."
        fi
    done
    info "Receipt-authorized immutable images verified before database transition"
}

database_recovery_journal_path() {
    printf '%s/database-rollback/recovery-journal.json\n' "$METADATA_DIR"
}

database_recovery_identifier_is_safe() {
    [[ "$1" =~ ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]]
}

database_recovery_install_dir_is_safe() {
    local path="${1%/}" relative component
    [[ "$path" == /* && "$path" != "/" \
        && "$path" != *$'\n'* && "$path" != *$'\r'* \
        && "$path" != *$'\t'* && "$path" != *\\* ]] || return 1
    relative="${path#/}"
    while [[ -n "$relative" ]]; do
        if [[ "$relative" == */* ]]; then
            component="${relative%%/*}"
            relative="${relative#*/}"
        else
            component="$relative"
            relative=""
        fi
        [[ -n "$component" && "$component" != "." \
            && "$component" != ".." ]] || return 1
    done
}

database_manage_stale_failed_deploy_staging() {
    local action="$1"
    local install_root="${INSTALL_DIR%/}"
    local expected_uid
    [[ "$action" == "validate" || "$action" == "remove" ]] || return 1
    database_recovery_install_dir_is_safe "$install_root" || return 1
    if [[ "$IS_MACOS" == "true" ]]; then
        expected_uid="$(installer_managed_deployment_uid)" || return 1
    else
        expected_uid="$($SUDO /usr/bin/id -u)" || return 1
    fi
    [[ "$expected_uid" =~ ^[0-9]+$ ]] || return 1
    # The durable source snapshot is authoritative. A SIGKILL may leave the
    # failed target tree in a platform-private direct child after the source
    # tree has been published. The install-root namespace is protected by the
    # caller before this privileged enumeration, so validated entries cannot
    # be exchanged after inspection.
    # shellcheck disable=SC2016  # Positional parameters expand in the root shell.
    $SUDO /bin/sh -ceu '
        action=$1
        expected_uid=$2
        shift 2
        root=${1%/}
        [ "${root#/}" != "$root" ] && [ "$root" != "/" ]
        [ -d "$root" ] && [ ! -L "$root" ]
        set -- "$root"/.rollback-failed-deploy-*
        if [ "$1" = "$root/.rollback-failed-deploy-*" ] \
            && [ ! -e "$1" ] && [ ! -L "$1" ]; then
            exit 0
        fi
        for path do
            [ "${path%/*}" = "$root" ]
            name=${path##*/}
            suffix=${name#.rollback-failed-deploy-}
            [ -n "$suffix" ] && [ "$suffix" != "$name" ]
            case "$suffix" in
                *[!0-9]*)
                    [ "${#suffix}" -eq 24 ]
                    case "$suffix" in *[!0-9a-f]*) exit 1 ;; esac
                    ;;
                *) ;;
            esac
            [ -d "$path" ] && [ ! -L "$path" ]
            case "$(uname -s 2>/dev/null || true)" in
                Linux) metadata=$(/usr/bin/stat -Lc "%u:%a" "$path") ;;
                Darwin) metadata=$(/usr/bin/stat -L -f "%u:%Lp" "$path") ;;
                *) exit 1 ;;
            esac
            [ "$metadata" = "$expected_uid:700" ]
            if [ "$action" = "remove" ]; then
                rm -rf -- "$path"
            fi
        done
    ' sh "$action" "$expected_uid" "$install_root"
}

database_validate_stale_failed_deploy_staging() {
    database_manage_stale_failed_deploy_staging validate
}

database_sweep_stale_failed_deploy_staging() {
    database_manage_stale_failed_deploy_staging remove
}

# Persist every identity needed to reverse a non-transactional database-name
# swap after SIGKILL or host restart. The journal is replaced atomically and is
# private to root; it remains until either source recovery or target health is
# complete.
database_discard_journal_staging() {
    local staging_file="${DATABASE_ROLLBACK_JOURNAL_STAGING_FILE:-}"
    local rollback_root="${METADATA_DIR}/database-rollback"
    [[ -n "$staging_file" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_file" ".recovery-journal-"; then
        warn "Refusing to remove an unsafe recovery journal staging path."
        DATABASE_ROLLBACK_JOURNAL_STAGING_FILE=""
        return 1
    fi
    if $SUDO test -e "$staging_file" || $SUDO test -L "$staging_file"; then
        if ! installer_private_staging_is_safe \
            "$staging_file" "file" "600"; then
            warn "Refusing to remove recovery journal staging with unsafe ownership."
            DATABASE_ROLLBACK_JOURNAL_STAGING_FILE=""
            return 1
        fi
        if ! $SUDO rm -f -- "$staging_file"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_JOURNAL_STAGING_FILE=""
}

database_write_recovery_journal() {
    local phase="$1"
    local rollback_root journal journal_staging suffix
    case "$phase" in
        deploy-files-mutating|deploy-mutating|deploy-stack-stopped|staging|swap-active|target-migrating-in-place|forward-target-healthy|target-healthy) ;;
        *) return 1 ;;
    esac
    is_stable_semver "$DATABASE_ROLLBACK_SOURCE_VERSION" || return 1
    if [[ -z "$DATABASE_ROLLBACK_INSTALL_DIR" ]]; then
        DATABASE_ROLLBACK_INSTALL_DIR="${INSTALL_DIR%/}"
    fi
    database_recovery_install_dir_is_safe \
        "$DATABASE_ROLLBACK_INSTALL_DIR" || return 1
    [[ "${INSTALL_DIR%/}" == "$DATABASE_ROLLBACK_INSTALL_DIR" ]] || return 1
    database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_ACTIVE_DATABASE" || return 1
    if [[ "$phase" == "staging" || "$phase" == "swap-active" ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    elif [[ "$phase" == "deploy-stack-stopped" \
        && ( -n "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
            || -n "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" ) ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    elif [[ "$phase" == "target-migrating-in-place" ]]; then
        # Nothing is copied or swapped, so naming either database here would be
        # a lie the recovery path could act on.
        [[ -z "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
            && -z "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" ]] || return 1
    elif [[ "$phase" == "forward-target-healthy" \
        && ( -n "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
            || -n "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" ) ]]; then
        # A journal written by <= 0.0.135 names the frozen clone pair here.
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    elif [[ "$phase" == "target-healthy" \
        && ( -n "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
            || -n "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" ) ]]; then
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE" || return 1
        database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" || return 1
    fi
    rollback_root="${METADATA_DIR}/database-rollback"
    [[ "$(dirname -- "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT")" == "$rollback_root" ]] || return 1
    [[ "$(basename -- "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT")" == .source-deploy-* ]] || return 1
    [[ "$(dirname -- "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH")" == "$METADATA_DIR" ]] || return 1
    [[ "$(basename -- "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH")" == "install.json" ]] || return 1
    if [[ -n "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE" \
        || -n "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_IDENTITY" ]]; then
        database_recovery_install_dir_is_safe \
            "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE" || return 1
        [[ "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_IDENTITY" \
            =~ ^[A-Za-z0-9._-]+:[0-9]+$ ]] || return 1
    fi

    journal=$(database_recovery_journal_path)
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || { $SUDO test -e "$journal" \
            && { ! $SUDO test -f "$journal" \
                || $SUDO test -L "$journal"; }; }; then
        return 1
    fi
    suffix="$(installer_private_staging_suffix)" || return 1
    DATABASE_ROLLBACK_JOURNAL_STAGING_FILE="${rollback_root}/.recovery-journal-${suffix}"
    journal_staging="$DATABASE_ROLLBACK_JOURNAL_STAGING_FILE"
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$journal_staging" ".recovery-journal-" \
        || ! installer_create_private_staging_file "$journal_staging"; then
        database_discard_journal_staging || true
        return 1
    fi
    if ! jq -n \
        --arg phase "$phase" \
        --arg source_version "$DATABASE_ROLLBACK_SOURCE_VERSION" \
        --arg install_dir "$DATABASE_ROLLBACK_INSTALL_DIR" \
        --arg metadata_path "$DATABASE_ROLLBACK_SOURCE_METADATA_PATH" \
        --arg snapshot_path "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT" \
        --arg timescaledb_bind_source \
            "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE" \
        --arg timescaledb_bind_identity \
            "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_IDENTITY" \
        --arg active_database "$DATABASE_ROLLBACK_ACTIVE_DATABASE" \
        --arg safety_database "$DATABASE_ROLLBACK_SAFETY_DATABASE" \
        --arg replacement_database "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" \
        --arg source_migration "$DATABASE_ROLLBACK_SOURCE_MIGRATION" \
        --arg recovery_snapshot_id "$DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID" \
        --arg recovery_snapshot_time "$DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME" \
        --arg replacement_is_adopted \
            "$DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT" \
        '{format_version: 4, phase: $phase, source_version: $source_version,
          install_dir: $install_dir, metadata_path: $metadata_path,
          snapshot_path: $snapshot_path,
          timescaledb_bind_source: $timescaledb_bind_source,
          timescaledb_bind_identity: $timescaledb_bind_identity,
          active_database: $active_database,
          safety_database: $safety_database,
          replacement_database: $replacement_database,
          source_migration: $source_migration,
          recovery_snapshot_id: $recovery_snapshot_id,
          recovery_snapshot_time: $recovery_snapshot_time,
          replacement_is_adopted_artifact: ($replacement_is_adopted == "true")}' \
        | $SUDO /usr/bin/tee "$journal_staging" >/dev/null \
        || ! $SUDO chmod 0600 "$journal_staging" \
        || ! installer_durable_sync_path "$journal_staging" \
        || ! $SUDO mv "$journal_staging" "$journal" \
        || ! installer_durable_sync_path "$journal" \
        || ! installer_durable_sync_path "$rollback_root"; then
        database_discard_journal_staging || true
        return 1
    fi
    DATABASE_ROLLBACK_JOURNAL_STAGING_FILE=""
    DATABASE_ROLLBACK_RECOVERY_PHASE="$phase"
    DATABASE_ROLLBACK_JOURNAL_FORMAT_VERSION="4"
}

database_legacy_recovery_install_dir() {
    local snapshot_path="$1"
    local metadata_archive="${snapshot_path}/source-metadata.tar"
    local checksums_file="${snapshot_path}/SHA256SUMS"
    local expected actual listing install_dir
    if ! $SUDO test -s "$metadata_archive" \
        || $SUDO test -L "$metadata_archive" \
        || ! $SUDO test -s "$checksums_file" \
        || $SUDO test -L "$checksums_file"; then
        return 1
    fi
    # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
    expected="$(
        $SUDO awk '$2 == "source-metadata.tar" {print $1}' "$checksums_file"
    )" || return 1
    [[ "$expected" =~ ^[0-9a-f]{64}$ ]] || return 1
    actual="$($SUDO cat "$metadata_archive" | sha256_stdin)" || return 1
    [[ "$actual" == "$expected" ]] || return 1
    listing="$($SUDO tar -tf "$metadata_archive")" || return 1
    [[ "$listing" == "install.json" ]] || return 1
    install_dir="$(
        set -o pipefail
        $SUDO tar -xOf "$metadata_archive" install.json \
            | jq -er '
                .install_dir
                | select(type == "string" and startswith("/") and . != "/")
            '
    )" || return 1
    install_dir="${install_dir%/}"
    database_recovery_install_dir_is_safe "$install_dir" || return 1
    printf '%s\n' "$install_dir"
}

database_load_recovery_journal() {
    local rollback_root journal journal_fields format_version phase
    local source_version install_dir
    local metadata_path snapshot_path
    local timescaledb_bind_source timescaledb_bind_identity
    local active_database safety_database replacement_database
    local source_migration replacement_is_adopted
    local recovery_snapshot_id recovery_snapshot_time
    rollback_root="${METADATA_DIR}/database-rollback"
    journal=$(database_recovery_journal_path)
    if ! $SUDO test -f "$journal" || $SUDO test -L "$journal"; then
        return 1
    fi
    if ! journal_fields=$(
        $SUDO cat "$journal" | jq -er '
          if (
            (.format_version == 1 or .format_version == 2 or
             .format_version == 3 or .format_version == 4) and
            (.phase == "deploy-files-mutating" or
             .phase == "deploy-mutating" or
             .phase == "deploy-stack-stopped" or .phase == "staging" or
             .phase == "swap-active" or
             .phase == "target-migrating-in-place" or
             .phase == "forward-target-healthy" or
             .phase == "target-healthy") and
            (.source_version | type == "string" and test("^[0-9]+[.][0-9]+[.][0-9]+$")) and
            (if (.format_version >= 2) then
                (.install_dir | type == "string" and startswith("/") and
                  . != "/" and (contains("\\") | not) and
                  (contains("\t") | not) and (contains("\r") | not) and
                  (contains("\n") | not))
             else true end) and
            (if (.format_version >= 4) then
                (.source_migration | type == "string" and test("^[0-9]*$")) and
                (.recovery_snapshot_id | type == "string" and
                    test("^([0-9a-f]{8,64})?$")) and
                (.recovery_snapshot_time | type == "string") and
                (.replacement_is_adopted_artifact | type == "boolean")
             else true end) and
            (if (.format_version >= 3) then
                (.timescaledb_bind_source | type == "string") and
                (.timescaledb_bind_identity | type == "string") and
                ((.timescaledb_bind_source == "" and
                  .timescaledb_bind_identity == "") or
                 ((.timescaledb_bind_source | startswith("/") and . != "/" and
                   (contains("\\") | not) and
                   (contains("\t") | not) and
                  (contains("\r") | not) and
                  (contains("\n") | not)) and
                  (.timescaledb_bind_identity |
                   test("^[A-Za-z0-9._-]+:[0-9]+$"))))
             else true end) and
            (.metadata_path | type == "string") and
            (.snapshot_path | type == "string") and
            (.active_database | type == "string" and test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
            (.safety_database | type == "string") and
            (.replacement_database | type == "string") and
            (if (.phase == "deploy-files-mutating" or
                 .phase == "deploy-mutating") then
                .safety_database == "" and .replacement_database == ""
             elif .phase == "deploy-stack-stopped" then
                ((.safety_database == "" and .replacement_database == "") or
                 ((.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                  (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))))
             elif .phase == "target-migrating-in-place" then
                .safety_database == "" and .replacement_database == ""
             elif .phase == "forward-target-healthy" then
                ((.safety_database == "" and .replacement_database == "") or
                 ((.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                  (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))))
             elif .phase == "target-healthy" then
                ((.safety_database == "" and .replacement_database == "") or
                 ((.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                  (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))))
             else
                (.safety_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                (.replacement_database | test("^[A-Za-z_][A-Za-z0-9_]{0,62}$"))
             end))
          then [
            (.format_version | tostring), .phase, .source_version,
            (if (.format_version >= 2) then .install_dir
             else "__LEGACY_V1__" end),
            .metadata_path, .snapshot_path,
            (if (.format_version >= 3) and
                .timescaledb_bind_source != ""
             then .timescaledb_bind_source else "__NO_BIND__" end),
            (if (.format_version >= 3) and
                .timescaledb_bind_identity != ""
             then .timescaledb_bind_identity else "__NO_BIND__" end),
            .active_database,
            (if .safety_database == "" then "-" else .safety_database end),
            (if .replacement_database == "" then "-"
             else .replacement_database end),
            (if (.format_version >= 4) and .source_migration != ""
             then .source_migration else "-" end),
            (if (.format_version >= 4) and .recovery_snapshot_id != ""
             then .recovery_snapshot_id else "-" end),
            (if (.format_version >= 4) and .recovery_snapshot_time != ""
             then .recovery_snapshot_time else "-" end),
            (if (.format_version >= 4) and .replacement_is_adopted_artifact
             then "true" else "false" end)
          ] | @tsv
          else error("invalid recovery journal")
          end'
    ); then
        fail "Pending database recovery journal is malformed; refusing deployment."
        return 1
    fi
    # Every projected field above is non-empty by construction, and that is
    # load-bearing: TAB is an IFS *whitespace* character, so `read` collapses a
    # run of consecutive empty fields into one and silently shifts every value
    # after it into the wrong variable. The "-" sentinels below cannot be
    # smuggled in through the journal — the schema rejects "-" for each field
    # that uses one — so they are unambiguous on the way back out.
    IFS=$'\t' read -r format_version phase source_version install_dir \
        metadata_path snapshot_path \
        timescaledb_bind_source timescaledb_bind_identity \
        active_database safety_database replacement_database \
        source_migration recovery_snapshot_id recovery_snapshot_time \
        replacement_is_adopted <<< "$journal_fields"
    [[ "$safety_database" != "-" ]] || safety_database=""
    [[ "$replacement_database" != "-" ]] || replacement_database=""
    [[ "$source_migration" != "-" ]] || source_migration=""
    [[ "$recovery_snapshot_id" != "-" ]] || recovery_snapshot_id=""
    [[ "$recovery_snapshot_time" != "-" ]] || recovery_snapshot_time=""
    if [[ "$(dirname -- "$snapshot_path")" != "$rollback_root" ]] \
        || [[ "$(basename -- "$snapshot_path")" != .source-deploy-* ]]; then
        fail "Pending database recovery journal references an unsafe source snapshot."
        return 1
    fi
    if [[ "$(dirname -- "$metadata_path")" != "$METADATA_DIR" ]] \
        || [[ "$(basename -- "$metadata_path")" != "install.json" ]]; then
        fail "Pending database recovery journal references unsafe install metadata."
        return 1
    fi
    if [[ "$format_version" == "1" ]]; then
        if ! install_dir="$(
            database_legacy_recovery_install_dir "$snapshot_path"
        )"; then
            fail "Pending legacy recovery journal has no verifiable install root."
            return 1
        fi
    else
        install_dir="${install_dir%/}"
    fi
    if ! database_recovery_install_dir_is_safe "$install_dir"; then
        fail "Pending database recovery journal references an unsafe install root."
        return 1
    fi
    if [[ "$timescaledb_bind_source" == "__NO_BIND__" \
        && "$timescaledb_bind_identity" == "__NO_BIND__" ]]; then
        timescaledb_bind_source=""
        timescaledb_bind_identity=""
    elif ! database_recovery_install_dir_is_safe \
            "$timescaledb_bind_source" \
        || [[ ! "$timescaledb_bind_identity" \
            =~ ^[A-Za-z0-9._-]+:[0-9]+$ ]]; then
        fail "Pending database recovery journal has unsafe database bind authority."
        return 1
    fi
    if [[ -n "${OPT_INSTALL_DIR:-}" \
        && "${OPT_INSTALL_DIR%/}" != "$install_dir" ]]; then
        fail "Pending database recovery journal conflicts with the requested install root."
        return 1
    fi

    DATABASE_ROLLBACK_RECOVERY_PHASE="$phase"
    DATABASE_ROLLBACK_JOURNAL_FORMAT_VERSION="$format_version"
    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    DATABASE_ROLLBACK_INSTALL_DIR="$install_dir"
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH="$metadata_path"
    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT="$snapshot_path"
    DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE="$timescaledb_bind_source"
    DATABASE_ROLLBACK_TIMESCALEDB_BIND_IDENTITY="$timescaledb_bind_identity"
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="true"
    DATABASE_ROLLBACK_ACTIVE_DATABASE="$active_database"
    DATABASE_ROLLBACK_SAFETY_DATABASE="$safety_database"
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE="$replacement_database"
    # Absent in format 1/2/3, which is how a journal written by an older
    # release resumes: an unknown source migration is re-read from the frozen
    # artifact, and an unrecorded adoption flag means "not adopted", which is
    # correct because no older release could have adopted anything.
    if [[ "$source_migration" =~ ^[0-9]+$ ]]; then
        DATABASE_ROLLBACK_SOURCE_MIGRATION="$source_migration"
    else
        DATABASE_ROLLBACK_SOURCE_MIGRATION=""
    fi
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID="$recovery_snapshot_id"
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME="$recovery_snapshot_time"
    if [[ "$replacement_is_adopted" == "true" ]]; then
        DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="true"
    else
        DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="false"
    fi
    if [[ "$phase" == "swap-active" ]]; then
        DATABASE_ROLLBACK_SWAP_ACTIVE="true"
    else
        DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    fi
    DATABASE_FORWARD_UPGRADE_ACTIVE="false"
    # The journal is the durable authority when live install metadata may
    # already have been renamed aside. Assign it before any deploy-tree check.
    INSTALL_DIR="$install_dir"
}

database_clear_recovery_journal() {
    local journal rollback_root
    journal=$(database_recovery_journal_path)
    rollback_root="$(dirname "$journal")"
    if ! $SUDO rm -f "$journal"; then
        return 1
    fi
    installer_durable_sync_path "$rollback_root" || return 1
    DATABASE_ROLLBACK_RECOVERY_PHASE=""
    DATABASE_ROLLBACK_JOURNAL_FORMAT_VERSION=""
}

database_discard_image_lock_staging() {
    local staging_dir="${DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR:-}"
    [[ -n "$staging_dir" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "/tmp" "$staging_dir" "llap-image-lock-recovery."; then
        warn "Refusing to remove an unsafe immutable recovery staging path."
        DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR=""
        return 1
    fi
    if $SUDO test -e "$staging_dir" || $SUDO test -L "$staging_dir"; then
        if ! installer_private_staging_is_safe \
            "$staging_dir" "directory" "700"; then
            warn "Refusing to remove immutable recovery staging with unsafe ownership."
            DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR=""
            return 1
        fi
        if ! $SUDO rm -rf -- "$staging_dir"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR=""
}

# Render only the captured private source tree. The canonical overlay parser
# authenticates every selected Compose file before this function is called, and
# the rendered bind-source validator below maps relative sources back into this
# private root. Recovery never needs to expose staged bytes at the live path.
database_run_staged_source_compose_model() {
    local root="${1%/}" source_version="$2" include_receipt="$3"
    local include_image_lock="$4"
    shift 4
    local source_command="${root}/compose-command.sh" overlay overlays_output
    local compose_root="$root"
    local found_image_lock="false"
    local -a overlays=() docker_args=()
    [[ "$include_receipt" == "true" \
        || "$include_receipt" == "false" ]] || return 1
    [[ "$include_image_lock" == "true" \
        || "$include_image_lock" == "false" ]] || return 1
    if $SUDO test -f "${root}/compose-command.source.sh"; then
        source_command="${root}/compose-command.source.sh"
    fi
    overlays_output="$(
        installer_collect_canonical_compose_overlays \
            "$root" "$source_command" "$source_version"
    )" || return 1
    while IFS= read -r overlay; do
        [[ -n "$overlay" ]] && overlays+=("$overlay")
    done <<< "$overlays_output"
    (( ${#overlays[@]} >= 2 )) || return 1
    docker_args=(
        compose
        --project-name docker
        --project-directory "${compose_root}/docker"
    )
    for overlay in "${overlays[@]}"; do
        if [[ "$overlay" == \
            "docker-compose.source-recovery-images.yml" ]]; then
            found_image_lock="true"
            [[ "$include_image_lock" == "true" ]] || continue
        fi
        docker_args+=(-f "${compose_root}/docker/${overlay}")
    done
    if [[ "$include_image_lock" == "false" \
        && "$found_image_lock" != "true" ]]; then
        return 1
    fi
    if [[ "$include_receipt" == "true" ]]; then
        if ! $SUDO test -f \
                "${root}/docker/docker-compose.receipt-recovery.yml" \
            || $SUDO test -L \
                "${root}/docker/docker-compose.receipt-recovery.yml" \
            || ! installer_path_has_single_link \
                "${root}/docker/docker-compose.receipt-recovery.yml"; then
            return 1
        fi
        docker_args+=(
            -f "${compose_root}/docker/docker-compose.receipt-recovery.yml"
        )
    fi
    docker_args+=(--env-file "${compose_root}/docker/.env" "$@")
    installer_docker "${docker_args[@]}"
}

database_run_staged_source_compose() {
    local root="$1" source_version="$2" include_receipt="$3"
    shift 3
    database_run_staged_source_compose_model \
        "$root" "$source_version" "$include_receipt" true "$@"
}

database_validate_staged_compose_bind_sources() {
    local root="${1%/}" config_json="$2"
    local service source target read_only relative staged_path
    local expected_type bind_rows source_prefix
    bind_rows="$(
        jq -r '
          .services | to_entries[] |
          .key as $service |
          .value.volumes[]? |
          select(.type == "bind") |
          [$service, .source, .target, (.read_only // false)] | @tsv
        ' <<< "$config_json"
    )" || return 1
    while IFS=$'\t' read -r service source target read_only; do
        [[ -n "$service" ]] || continue
        [[ -n "$service" && -n "$source" && -n "$target" \
            && ( "$read_only" == "true" \
                || "$read_only" == "false" ) ]] || return 1
        if [[ "$source" == "/var/run/docker.sock" ]]; then
            [[ "$target" == "/var/run/docker.sock" \
                && "$read_only" == "true" ]] || return 1
            continue
        fi
        if [[ -n "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE" \
            && "$source" == \
                "$DATABASE_ROLLBACK_TIMESCALEDB_BIND_SOURCE" ]]; then
            [[ "$target" == "/var/lib/postgresql/18/docker" \
                && "$read_only" == "false" ]] || return 1
            database_validate_recovered_timescaledb_bind_authority "$root" \
                || return 1
            continue
        fi
        case "$source" in
            "${INSTALL_DIR%/}/docker/"*)
                source_prefix="${INSTALL_DIR%/}/docker"
                database_path_is_strict_child \
                    "$source_prefix" "$source" || return 1
                ;;
            "${root}/docker/"*)
                source_prefix="${root}/docker"
                database_path_is_strict_child \
                    "$source_prefix" "$source" || return 1
                ;;
            *)
                return 1
                ;;
        esac
        relative="${source#"${source_prefix}/"}"
        staged_path="${root}/docker/${relative}"
        expected_type="$(bind_mount_expected_type "$relative")" \
            || return 1
        case "$expected_type" in
            file)
                $SUDO test -f "$staged_path" \
                    && ! $SUDO test -L "$staged_path" \
                    && installer_path_has_single_link "$staged_path" \
                    || return 1
                ;;
            dir)
                $SUDO test -d "$staged_path" \
                    && ! $SUDO test -L "$staged_path" || return 1
                ;;
            *) return 1 ;;
        esac
    done <<< "$bind_rows"
}

installer_existing_receipt_recovery_files_are_authorized() {
    local root="${1%/}" backup_enabled="$2"
    local wrapper="${root}/compose-command.sh"
    local overlay="${root}/docker/docker-compose.receipt-recovery.yml"
    local actual expected
    [[ "$backup_enabled" == "true" \
        || "$backup_enabled" == "false" ]] || return 1
    [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" ]] || return 1
    if ! $SUDO test -f "$wrapper" || $SUDO test -L "$wrapper" \
        || ! $SUDO test -x "$wrapper" \
        || ! installer_path_has_single_link "$wrapper" \
        || ! $SUDO test -f "$overlay" || $SUDO test -L "$overlay" \
        || ! installer_path_has_single_link "$overlay"; then
        return 1
    fi
    actual="$($SUDO cat "$wrapper")" || return 1
    expected="$(
        printf '#!/bin/bash\n'
        printf 'set -euo pipefail\n'
        printf 'unset PROXY_VERSION PROXY_SERVER_IMAGE PROXY_CLI_IMAGE PROXY_BACKUP_IMAGE\n'
        printf 'exec "%s/compose-command.source.sh" \\\n' "$INSTALL_DIR"
        printf '  -f docker-compose.receipt-recovery.yml "$@"\n'
    )"
    [[ "$actual" == "$expected" ]] || return 1
    actual="$($SUDO cat "$overlay")" || return 1
    expected="$(
        printf '# docker-compose.receipt-recovery.yml — signed receipt recovery only\n'
        printf 'services:\n'
        printf '  proxy:\n'
        printf '    image: %s\n' "$RELEASE_RECOVERY_SERVER_IMAGE"
        if [[ "$backup_enabled" == "true" ]]; then
            printf '  backup:\n'
            printf '    image: %s\n' "$RELEASE_RECOVERY_BACKUP_IMAGE"
        fi
    )"
    [[ "$actual" == "$expected" ]]
}

database_capture_running_source_image_lock() {
    local config_json="$1" expected_config_files="$2" destination="$3"
    local expected_services candidate_ids candidate_id container_json row
    local service working_dir project config_files image_ref image_id
    local rendered_image inspected_id
    local seen="|" running_entries="" running_services=""
    [[ -n "$expected_config_files" && -n "$destination" ]] || return 1
    if $SUDO test -e "$destination" || $SUDO test -L "$destination"; then
        return 1
    fi
    expected_services="$(
        jq -er '
            .services |
            to_entries |
            map(select(((.value.profiles // []) | length) == 0)) |
            map(.key) |
            sort |
            select(length > 0) |
            .[]
        ' <<< "$config_json" 2>/dev/null
    )" || return 1
    candidate_ids="$(
        installer_docker ps -a --no-trunc \
            --filter "label=com.docker.compose.project=docker" \
            --format '{{.ID}}' 2>> "$LOG_FILE"
    )" || return 1
    while IFS= read -r candidate_id; do
        [[ -n "$candidate_id" ]] || continue
        [[ "$candidate_id" =~ ^[0-9a-f]{12,64}$ ]] || return 1
        container_json="$(
            installer_docker container inspect "$candidate_id" 2>/dev/null
        )" || return 1
        row="$(
            jq -er '
                select(type == "array" and length == 1) |
                .[0] |
                .Config.Labels as $labels |
                [
                  $labels["com.docker.compose.service"],
                  $labels["com.docker.compose.project.working_dir"],
                  $labels["com.docker.compose.project"],
                  $labels["com.docker.compose.project.config_files"],
                  .Config.Image,
                  .Image
                ] |
                select(all(.[]; type == "string")) |
                @tsv
            ' <<< "$container_json" 2>/dev/null
        )" || return 1
        IFS=$'\t' read -r \
            service working_dir project config_files image_ref image_id \
            <<< "$row"
        if [[ "$working_dir" != "${INSTALL_DIR%/}/docker" ]]; then
            continue
        fi
        [[ "$service" =~ ^[a-z0-9][a-z0-9_.-]*$ \
            && "$project" == "docker" \
            && "$config_files" == "$expected_config_files" \
            && "$image_id" =~ ^sha256:[0-9a-f]{64}$ \
            && "$seen" != *"|${service}|"* ]] || return 1
        [[ $'\n'"$expected_services"$'\n' == *$'\n'"$service"$'\n'* ]] \
            || return 1
        rendered_image="$(
            jq -er --arg service "$service" '
                .services[$service].image |
                select(type == "string" and length > 0)
            ' <<< "$config_json" 2>/dev/null
        )" || return 1
        [[ "$image_ref" == "$rendered_image" ]] || return 1
        inspected_id="$(
            installer_docker image inspect "$image_id" 2>/dev/null \
                | jq -er '
                    select(type == "array" and length == 1) |
                    .[0].Id |
                    select(type == "string" and
                      test("^sha256:[0-9a-f]{64}$"))
                '
        )" || return 1
        [[ "$inspected_id" == "$image_id" ]] || return 1
        seen+="${service}|"
        running_entries+="${service}"$'\t'"${image_id}"$'\n'
    done <<< "$candidate_ids"
    running_entries="$(
        printf '%s' "$running_entries" | LC_ALL=C /usr/bin/sort
    )" || return 1
    running_services="$(
        /usr/bin/awk -F '\t' '{print $1}' <<< "$running_entries"
    )" || return 1
    [[ "$running_services" == "$expected_services" ]] || return 1
    if ! {
        printf '# docker-compose.source-recovery-images.yml — immutable captured source images\n'
        printf 'services:\n'
        while IFS=$'\t' read -r service image_id; do
            [[ -n "$service" && -n "$image_id" ]] || continue
            printf '  %s:\n' "$service"
            printf '    image: %s\n' "$image_id"
        done <<< "$running_entries"
    } | $SUDO /usr/bin/tee "$destination" >/dev/null; then
        return 1
    fi
    installer_source_recovery_image_lock_entries "$destination" >/dev/null
}

database_validate_rendered_service_against_running_stack() {
    local config_json="$1" expected_config_files="$2"
    local expected_service="$3" compare_dns="$4"
    local candidate_ids candidate_id container_json labels
    local service working_dir project config_files
    local selected_container_json="" selected_container_image_id="" image_json
    [[ "$expected_service" =~ ^[a-z0-9][a-z0-9_.-]*$ ]] || return 1
    [[ "$compare_dns" == "true" || "$compare_dns" == "false" ]] || return 1
    candidate_ids="$(
        installer_docker ps -a --no-trunc \
            --filter "label=com.docker.compose.service=${expected_service}" \
            --format '{{.ID}}' 2>> "$LOG_FILE"
    )" || return 1
    while IFS= read -r candidate_id; do
        [[ -n "$candidate_id" ]] || continue
        [[ "$candidate_id" =~ ^[0-9a-f]{12,64}$ ]] || return 1
        container_json="$(
            installer_docker container inspect "$candidate_id" 2>/dev/null
        )" || return 1
        labels="$(
            jq -er '
                select(type == "array" and length == 1) |
                .[0].Config.Labels as $labels |
                [
                  $labels["com.docker.compose.service"],
                  $labels["com.docker.compose.project.working_dir"],
                  $labels["com.docker.compose.project"],
                  $labels["com.docker.compose.project.config_files"]
                ] |
                select(all(.[]; type == "string")) |
                @tsv
            ' <<< "$container_json" 2>/dev/null
        )" || return 1
        IFS=$'\t' read -r service working_dir project config_files <<< "$labels"
        if [[ "$working_dir" != "${INSTALL_DIR%/}/docker" ]]; then
            continue
        fi
        [[ "$service" == "$expected_service" \
            && "$project" == "docker" \
            && "$config_files" == "$expected_config_files" \
            && -z "$selected_container_json" ]] || return 1
        selected_container_json="$container_json"
    done <<< "$candidate_ids"
    [[ -n "$selected_container_json" ]] || return 1
    selected_container_image_id="$(
        jq -er '
            .[0] |
            select(.Config.Image | type == "string" and length > 0) |
            select(.Image | type == "string" and
              test("^sha256:[0-9a-f]{64}$")) |
            .Image
        ' <<< "$selected_container_json" 2>/dev/null
    )" || return 1
    image_json="$(
        installer_docker image inspect \
            "$selected_container_image_id" 2>/dev/null
    )" || return 1
    # JSON, including secrets, travels only on this pipe and is never written to
    # the installer log or process argv.
    {
        printf '%s\n' "$config_json"
        printf '%s\n' "$selected_container_json"
        printf '%s\n' "$image_json"
    } | jq -se \
        --arg service "$expected_service" \
        --argjson compare_dns "$compare_dns" '
        def env_map:
          reduce .[] as $entry (
            {valid: true, seen: {}, values: {}};
            if ($entry | type) != "string" or
               ($entry | contains("=") | not) then
              .valid = false
            else
              ($entry | index("=")) as $separator |
              ($entry[0:$separator]) as $key |
              ($entry[$separator + 1:]) as $value |
              if ($key | test("^[A-Za-z_][A-Za-z0-9_]*$") | not) or
                 .seen[$key] then
                .valid = false
              else
                .seen[$key] = true |
                .values[$key] = $value
              end
            end
          ) |
          select(.valid) |
          .values;
        .[0] as $compose |
        .[1][0] as $container |
        .[2][0] as $image |
        ($image.Config.Env // [] | env_map) as $image_env |
        ($container.Config.Env // [] | env_map) as $running_env |
        ($compose.services[$service].environment) as $service_env |
        ($container.Config.Image == $compose.services[$service].image) and
        ($container.Image == $image.Id) and
        (($image_env + $service_env) == $running_env) and
        (($compare_dns | not) or
          (($compose.services[$service].dns // []) ==
           ($container.HostConfig.Dns // [])))
    ' >/dev/null 2>&1
}

database_validate_staged_compose_against_running_stack() {
    local root="${1%/}" source_version="$2"
    local image_lock_destination="${3:-}"
    local config_json env_json expected_config_files="" overlays_output
    local overlay include_receipt="false" backup_enabled="false"
    local source_command="${root}/compose-command.sh"
    local -a overlays=()
    if $SUDO test -f "${root}/compose-command.source.sh"; then
        source_command="${root}/compose-command.source.sh"
    fi
    overlays_output="$(
        installer_collect_canonical_compose_overlays \
            "$root" "$source_command" "$source_version"
    )" || return 1
    while IFS= read -r overlay; do
        [[ -n "$overlay" ]] && overlays+=("$overlay")
    done <<< "$overlays_output"
    for overlay in "${overlays[@]}"; do
        [[ "$overlay" != "docker-compose.backup.yml" ]] \
            || backup_enabled="true"
        if [[ -n "$expected_config_files" ]]; then
            expected_config_files+=","
        fi
        expected_config_files+="${INSTALL_DIR%/}/docker/${overlay}"
    done
    if $SUDO test -f "${root}/compose-command.source.sh"; then
        include_receipt="true"
        installer_existing_receipt_recovery_files_are_authorized \
            "$root" "$backup_enabled" || return 1
        expected_config_files+=",${INSTALL_DIR%/}/docker/docker-compose.receipt-recovery.yml"
    fi
    database_run_staged_source_compose \
        "$root" "$source_version" "$include_receipt" config --quiet \
        >> "$LOG_FILE" 2>&1 || return 1
    config_json="$(
        database_run_staged_source_compose \
            "$root" "$source_version" "$include_receipt" config --format json \
            2>> "$LOG_FILE"
    )" || return 1
    jq -e '
        .services | type == "object" and
        (.proxy | type == "object") and
        (.proxy.image | type == "string" and length > 0) and
        (.proxy.environment | type == "object" and
          all(.[]; type == "string")) and
        ((.proxy.dns // []) | type == "array" and
          all(.[]; type == "string" and length > 0)) and
        (.traefik | type == "object") and
        (.traefik.image | type == "string" and length > 0) and
        (.traefik.environment | type == "object" and
          all(.[]; type == "string"))
    ' \
        <<< "$config_json" >/dev/null 2>&1 || return 1
    database_validate_staged_compose_bind_sources \
        "$root" "$config_json" || return 1
    env_json="$(
        $SUDO cat "${root}/docker/.env" \
            | jq -Rsc '
                reduce (
                  split("\n")[] |
                  select(length > 0 and (startswith("#") | not))
                ) as $line ({};
                  ($line | index("=")) as $separator |
                  if $separator == null or $separator == 0 then
                    error("invalid environment")
                  else
                    .[$line[0:$separator]] = $line[$separator + 1:]
                  end
                )
            '
    )" || return 1
    # The static legacy Traefik service consumes the complete .env without the
    # proxy service's renamed-key override (notably CONSUL_HTTP_TOKEN versus
    # PROXY_CONSUL_TOKEN). Require every raw key/value to survive rendering
    # unchanged, then bind both services' complete effective environments to
    # immutable Engine state. This authenticates every interpolation input
    # without Compose's version-dependent private config hash.
    {
        printf '%s\n' "$config_json"
        printf '%s\n' "$env_json"
    } | jq -se '
        .[0] as $compose |
        .[1] as $raw_env |
        ($raw_env | to_entries |
          all(.[];
            . as $entry |
            $compose.services.traefik.environment[$entry.key] ==
              $entry.value))
    ' >/dev/null 2>&1 || return 1
    database_validate_rendered_service_against_running_stack \
        "$config_json" "$expected_config_files" proxy true \
        && database_validate_rendered_service_against_running_stack \
            "$config_json" "$expected_config_files" traefik false \
        && {
            [[ -z "$image_lock_destination" ]] \
                || database_capture_running_source_image_lock \
                    "$config_json" "$expected_config_files" \
                    "$image_lock_destination"
        }
}

database_validate_source_image_lock_against_base_config() {
    local root="${1%/}" base_config_json="$2" include_receipt="$3"
    local lock_file="${root}/docker/docker-compose.source-recovery-images.yml"
    local entries expected_services locked_services
    local service image_id receipt_image inspected_id
    [[ "$include_receipt" == "true" \
        || "$include_receipt" == "false" ]] || return 1
    entries="$(
        installer_source_recovery_image_lock_entries "$lock_file"
    )" || return 1
    expected_services="$(
        jq -er '
            .services |
            to_entries |
            map(select(((.value.profiles // []) | length) == 0)) |
            map(.key) |
            sort |
            select(length > 0) |
            .[]
        ' <<< "$base_config_json" 2>/dev/null
    )" || return 1
    locked_services="$(
        /usr/bin/awk -F '\t' '{print $1}' <<< "$entries" \
            | LC_ALL=C /usr/bin/sort
    )" || return 1
    [[ "$locked_services" == "$expected_services" ]] || return 1
    while IFS=$'\t' read -r service image_id; do
        [[ -n "$service" && -n "$image_id" ]] || return 1
        inspected_id="$(
            installer_docker image inspect "$image_id" 2>/dev/null \
                | jq -er '
                    select(type == "array" and length == 1) |
                    .[0].Id |
                    select(type == "string" and
                      test("^sha256:[0-9a-f]{64}$"))
                '
        )" || return 1
        [[ "$inspected_id" == "$image_id" ]] || return 1
        receipt_image=""
        if [[ "$include_receipt" == "true" ]]; then
            case "$service" in
                proxy)
                    receipt_image="$RELEASE_RECOVERY_SERVER_IMAGE"
                    ;;
                backup)
                    receipt_image="$RELEASE_RECOVERY_BACKUP_IMAGE"
                    ;;
            esac
        fi
        if [[ -n "$receipt_image" ]]; then
            inspected_id="$(
                installer_docker image inspect "$receipt_image" 2>/dev/null \
                    | jq -er '
                        select(type == "array" and length == 1) |
                        .[0].Id |
                        select(type == "string" and
                          test("^sha256:[0-9a-f]{64}$"))
                    '
            )" || return 1
            [[ "$inspected_id" == "$image_id" ]] || return 1
        fi
    done <<< "$entries"
}

database_validate_rendered_source_image_lock() {
    local root="${1%/}" config_json="$2" include_receipt="$3"
    local lock_file="${root}/docker/docker-compose.source-recovery-images.yml"
    local entries service image_id rendered_image expected_image
    [[ "$include_receipt" == "true" \
        || "$include_receipt" == "false" ]] || return 1
    entries="$(
        installer_source_recovery_image_lock_entries "$lock_file"
    )" || return 1
    while IFS=$'\t' read -r service image_id; do
        [[ -n "$service" && -n "$image_id" ]] || return 1
        expected_image="$image_id"
        if [[ "$include_receipt" == "true" ]]; then
            case "$service" in
                proxy)
                    expected_image="$RELEASE_RECOVERY_SERVER_IMAGE"
                    ;;
                backup)
                    expected_image="$RELEASE_RECOVERY_BACKUP_IMAGE"
                    ;;
            esac
        fi
        rendered_image="$(
            jq -er --arg service "$service" '
                .services[$service].image |
                select(type == "string" and length > 0)
            ' <<< "$config_json" 2>/dev/null
        )" || return 1
        [[ "$rendered_image" == "$expected_image" ]] || return 1
    done <<< "$entries"
}

database_validate_staged_recovery_compose() {
    local root="${1%/}" source_version="$2" include_receipt="false"
    local base_config_json config_json
    if $SUDO test -f "${root}/compose-command.source.sh"; then
        include_receipt="true"
    fi
    database_run_staged_source_compose_model \
        "$root" "$source_version" "$include_receipt" false config --quiet \
        >> "$LOG_FILE" 2>&1 || return 1
    base_config_json="$(
        database_run_staged_source_compose_model \
            "$root" "$source_version" "$include_receipt" false \
            config --format json 2>> "$LOG_FILE"
    )" || return 1
    database_validate_source_image_lock_against_base_config \
        "$root" "$base_config_json" "$include_receipt" || return 1
    database_run_staged_source_compose \
        "$root" "$source_version" "$include_receipt" config --quiet \
        >> "$LOG_FILE" 2>&1 || return 1
    config_json="$(
        database_run_staged_source_compose \
            "$root" "$source_version" "$include_receipt" \
            config --format json 2>> "$LOG_FILE"
    )" || return 1
    database_validate_staged_compose_bind_sources "$root" "$config_json" \
        && database_validate_rendered_source_image_lock \
            "$root" "$config_json" "$include_receipt"
}

database_bind_recovery_image_lock_to_archive() {
    local archive="$1"
    local source_version="$2"
    local staging suffix status=0
    local -a snapshot_entries=(
        "docker"
        "compose-command.sh"
    )
    [[ "$RELEASE_IMAGE_LOCK_ACTIVE" != "true" \
        || "$source_version" == "$RELEASE_RECOVERY_IMAGE_LOCK_VERSION" ]] \
        || {
            fail "Installed source version is not the receipt-authorized recovery version."
            return 1
        }
    suffix="$(installer_private_staging_suffix)" || return 1
    DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR="/tmp/llap-image-lock-recovery.${suffix}"
    staging="$DATABASE_ROLLBACK_IMAGE_LOCK_STAGING_DIR"
    if ! database_path_is_safe_direct_child \
        "/tmp" "$staging" "llap-image-lock-recovery." \
        || ! installer_create_private_staging_directory "$staging"; then
        database_discard_image_lock_staging || true
        return 1
    fi
    if ! (
        local env_file env_staging version_count version_value
        local source_command source_command_authority
        local recovery_command recovery_overlay
        local source_image_overlay source_image_staging
        local command_staging overlay_staging backup_enabled="false"
        local overlay source_overlays_output
        local managed_uid managed_group
        local -a source_overlays=()
        managed_uid="$(installer_managed_deployment_uid)" || exit 1
        managed_group="$(installer_managed_deployment_group)" || exit 1
        if ! $SUDO tar -xpf "$archive" -C "$staging"; then
            fail "Could not stage the source deploy snapshot for immutable recovery."
            exit 1
        fi
        if ! $SUDO test -d "${staging}/docker" \
            || $SUDO test -L "${staging}/docker"; then
            fail "Source deploy snapshot docker directory is unsafe."
            exit 1
        fi
        env_file="${staging}/docker/.env"
        if ! $SUDO test -f "$env_file" || $SUDO test -L "$env_file" \
            || ! installer_path_has_single_link "$env_file"; then
            fail "Source deploy snapshot environment is missing or unsafe."
            exit 1
        fi
        version_count="$($SUDO grep -c '^PROXY_VERSION=' "$env_file" || true)"
        # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
        version_value="$(
            $SUDO awk -F= '$1 == "PROXY_VERSION" {print substr($0, 15)}' \
                "$env_file"
        )"
        [[ "$version_count" == "1" && "$version_value" == "$source_version" ]] \
            || {
                fail "Source deploy snapshot version is ambiguous or unexpected."
                exit 1
            }
        source_image_overlay="${staging}/docker/docker-compose.source-recovery-images.yml"
        source_image_staging="${staging}/docker/.source-recovery-images-new.yml"
        source_command_authority="${staging}/compose-command.sh"
        if $SUDO test -f "${staging}/compose-command.source.sh"; then
            source_command_authority="${staging}/compose-command.source.sh"
        fi
        if { $SUDO test -e "$source_image_overlay" \
                && { ! $SUDO test -f "$source_image_overlay" \
                    || $SUDO test -L "$source_image_overlay" \
                    || ! installer_path_has_single_link \
                        "$source_image_overlay"; }; } \
            || $SUDO test -L "$source_image_overlay" \
            || $SUDO test -e "$source_image_staging" \
            || $SUDO test -L "$source_image_staging"; then
            fail "Source deploy snapshot contains an untrusted image lock."
            exit 1
        fi
        if ! installer_recovery_fixed_files_are_authorized \
                "$staging" "$source_version" \
            || ! installer_recovery_env_is_authorized \
                "$staging" "$source_version" true true \
            || ! database_validate_staged_compose_against_running_stack \
                "$staging" "$source_version" "$source_image_staging"; then
            fail "Captured source Compose model does not match the running stack."
            exit 1
        fi
        if ! $SUDO chmod 0640 "$source_image_staging" \
            || ! $SUDO chown "${managed_uid}:${managed_group}" \
                "$source_image_staging" \
            || ! $SUDO mv "$source_image_staging" "$source_image_overlay" \
            || ! installer_managed_path_is_safe \
                "$source_image_overlay" "file" "640"; then
            fail "Could not publish the immutable source image lock."
            exit 1
        fi
        source_overlays_output="$(
            installer_collect_canonical_compose_overlays \
                "$staging" "$source_command_authority" "$source_version"
        )" || {
            fail "Could not recover the captured source overlay list."
            exit 1
        }
        while IFS= read -r overlay; do
            [[ -n "$overlay" ]] && source_overlays+=("$overlay")
        done <<< "$source_overlays_output"
        if (( ${#source_overlays[@]} < 2 )); then
            fail "Could not recover the captured source overlay list."
            exit 1
        fi
        if [[ "${source_overlays[${#source_overlays[@]} - 1]}" != \
            "docker-compose.source-recovery-images.yml" ]]; then
            source_overlays+=("docker-compose.source-recovery-images.yml")
        fi
        if ! installer_write_canonical_compose_command \
                "$source_command_authority" "$INSTALL_DIR" \
                "$source_version" "${source_overlays[@]}"; then
            fail "Could not bind the source command to immutable image identities."
            exit 1
        fi
        if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" ]]; then
        env_staging="${staging}/docker/.env.recovery-new"
        if $SUDO test -e "$env_staging" || $SUDO test -L "$env_staging"; then
            fail "Source deploy snapshot contains unsafe environment staging."
            exit 1
        fi
        if ! $SUDO awk '
                !/^PROXY_SERVER_IMAGE=/ &&
                !/^PROXY_CLI_IMAGE=/ &&
                !/^PROXY_BACKUP_IMAGE=/
            ' "$env_file" \
            | $SUDO /usr/bin/tee "$env_staging" >/dev/null; then
            exit 1
        fi
        if ! {
            printf 'PROXY_SERVER_IMAGE=%s\n' "$RELEASE_RECOVERY_SERVER_IMAGE"
            printf 'PROXY_CLI_IMAGE=%s\n' "$RELEASE_RECOVERY_CLI_IMAGE"
            printf 'PROXY_BACKUP_IMAGE=%s\n' "$RELEASE_RECOVERY_BACKUP_IMAGE"
        } | $SUDO /usr/bin/tee -a "$env_staging" >/dev/null; then
            exit 1
        fi
        if ! $SUDO chmod 0640 "$env_staging" \
            || ! $SUDO chown "${managed_uid}:${managed_group}" "$env_staging" \
            || ! $SUDO mv "$env_staging" "$env_file"; then
            fail "Could not bind immutable recovery images into the source snapshot."
            exit 1
        fi
        source_command="${staging}/compose-command.source.sh"
        recovery_command="${staging}/compose-command.sh"
        recovery_overlay="${staging}/docker/docker-compose.receipt-recovery.yml"
        if ! $SUDO test -f "$recovery_command" \
            || $SUDO test -L "$recovery_command" \
            || ! $SUDO test -x "$recovery_command" \
            || ! installer_path_has_single_link "$recovery_command"; then
            fail "Source deploy snapshot Compose command is unsafe."
            exit 1
        fi
        if $SUDO test -e "$source_command"; then
            if ! $SUDO test -f "$source_command" \
                || $SUDO test -L "$source_command" \
                || ! $SUDO test -x "$source_command" \
                || ! installer_path_has_single_link "$source_command"; then
                fail "Existing source recovery command is unsafe."
                exit 1
            fi
        elif ! $SUDO mv "$recovery_command" "$source_command"; then
            fail "Could not preserve the source Compose command for recovery."
            exit 1
        fi
        if $SUDO grep -Fq -- '-f docker-compose.backup.yml' "$source_command"; then
            backup_enabled="true"
        fi
        command_staging="${staging}/compose-command.recovery-new"
        overlay_staging="${staging}/docker/docker-compose.receipt-recovery-new.yml"
        if $SUDO test -e "$command_staging" \
            || $SUDO test -L "$command_staging" \
            || $SUDO test -e "$overlay_staging" \
            || $SUDO test -L "$overlay_staging"; then
            fail "Source deploy snapshot contains unsafe recovery staging."
            exit 1
        fi
        if $SUDO test -e "$recovery_overlay" \
            && { ! $SUDO test -f "$recovery_overlay" \
                || $SUDO test -L "$recovery_overlay" \
                || ! installer_path_has_single_link "$recovery_overlay"; }; then
            fail "Existing source recovery overlay is unsafe."
            exit 1
        fi
        if ! {
            printf '# docker-compose.receipt-recovery.yml — signed receipt recovery only\n'
            printf 'services:\n'
            printf '  proxy:\n'
            printf '    image: %s\n' "$RELEASE_RECOVERY_SERVER_IMAGE"
            if [[ "$backup_enabled" == "true" ]]; then
                printf '  backup:\n'
                printf '    image: %s\n' "$RELEASE_RECOVERY_BACKUP_IMAGE"
            fi
        } | $SUDO /usr/bin/tee "$overlay_staging" >/dev/null; then
            exit 1
        fi
        if ! {
            printf '#!/bin/bash\n'
            printf 'set -euo pipefail\n'
            printf 'unset PROXY_VERSION PROXY_SERVER_IMAGE PROXY_CLI_IMAGE PROXY_BACKUP_IMAGE\n'
            printf 'exec "%s/compose-command.source.sh" \\\n' "$INSTALL_DIR"
            printf '  -f docker-compose.receipt-recovery.yml "$@"\n'
        } | $SUDO /usr/bin/tee "$command_staging" >/dev/null; then
            exit 1
        fi
        if ! $SUDO chmod 0640 "$overlay_staging" \
            || ! $SUDO chmod 0750 "$command_staging" \
            || ! $SUDO mv "$overlay_staging" "$recovery_overlay" \
            || ! $SUDO mv "$command_staging" "$recovery_command"; then
            fail "Could not write the receipt-bound source recovery override."
            exit 1
        fi
        if ! $SUDO chown "${managed_uid}:${managed_group}" \
            "$recovery_overlay" "$recovery_command" "$source_command"; then
            fail "Could not protect receipt-bound recovery commands."
            exit 1
        fi
        fi
        if ! installer_recovery_env_is_authorized \
                "$staging" "$source_version" true \
            || ! database_prepare_trusted_recovered_compose \
                "$staging" "$source_version" \
            || ! database_validate_staged_recovery_compose \
                "$staging" "$source_version"; then
            fail "Source recovery archive contains unauthorized Compose authority."
            exit 1
        fi
        if $SUDO test -f "${staging}/compose-command.source.sh"; then
            snapshot_entries+=("compose-command.source.sh")
        fi
        $SUDO test -f "${staging}/.version" && snapshot_entries+=(".version")
        if ! $SUDO tar -C "$staging" -cpf "$archive" "${snapshot_entries[@]}"; then
            fail "Could not repack the receipt-bound source deploy snapshot."
            exit 1
        fi
    ); then
        status=1
    fi
    if ! database_discard_image_lock_staging; then
        status=1
    fi
    return "$status"
}

# Preserve the exact source deploy tree before a rollback rewrites embedded
# Compose/configuration files. The root-only archive is kept until the recovered
# target proves healthy, so every earlier failure can restore reboot-safe state.
database_discard_source_snapshot_staging() {
    local staging_dir="${DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR:-}"
    local rollback_root="${METADATA_DIR}/database-rollback"
    [[ -n "$staging_dir" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-source-deploy-"; then
        warn "Refusing to remove an unsafe source snapshot staging path."
        DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR=""
        return 1
    fi
    if $SUDO test -e "$staging_dir" || $SUDO test -L "$staging_dir"; then
        if ! installer_private_staging_is_safe \
            "$staging_dir" "directory" "700"; then
            warn "Refusing to remove source snapshot staging with unsafe ownership."
            DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR=""
            return 1
        fi
        if ! $SUDO rm -rf -- "$staging_dir"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR=""
}

database_orphaned_source_snapshot_is_safe() {
    local snapshot_dir="${1%/}"
    local rollback_root="${METADATA_DIR%/}/database-rollback"
    local basename candidate expected actual archive_checksum metadata_checksum
    database_path_is_safe_direct_child \
        "$rollback_root" "$snapshot_dir" ".source-deploy-" || return 1
    basename="$(basename -- "$snapshot_dir")"
    [[ "$basename" =~ \
^\.source-deploy-[0-9]{8}T[0-9]{6}Z-[0-9]+$ ]] || return 1
    installer_private_staging_is_safe \
        "$snapshot_dir" "directory" "700" || return 1
    for basename in source-deploy.tar source-metadata.tar SHA256SUMS; do
        candidate="${snapshot_dir}/${basename}"
        if ! $SUDO test -f "$candidate" || $SUDO test -L "$candidate" \
            || ! installer_path_has_single_link "$candidate" \
            || ! installer_private_staging_is_safe \
                "$candidate" "file" "600"; then
            return 1
        fi
    done
    candidate="$(
        $SUDO /usr/bin/find -P "$snapshot_dir" \
            ! -path "$snapshot_dir" \
            ! -path "${snapshot_dir}/source-deploy.tar" \
            ! -path "${snapshot_dir}/source-metadata.tar" \
            ! -path "${snapshot_dir}/SHA256SUMS" \
            -print -quit
    )" || return 1
    [[ -z "$candidate" ]] || return 1
    archive_checksum="$(
        database_root_file_sha256 "${snapshot_dir}/source-deploy.tar"
    )" || return 1
    metadata_checksum="$(
        database_root_file_sha256 "${snapshot_dir}/source-metadata.tar"
    )" || return 1
    expected="$(
        printf '%s  source-deploy.tar\n%s  source-metadata.tar\n' \
            "$archive_checksum" "$metadata_checksum"
    )"
    actual="$($SUDO cat "${snapshot_dir}/SHA256SUMS")" || return 1
    [[ "$actual" == "$expected" ]]
}

database_sweep_orphaned_source_snapshots() {
    local rollback_root="${METADATA_DIR%/}/database-rollback"
    local journal candidate candidate_output
    local -a candidates=()
    $SUDO test -d "$rollback_root" || return 0
    journal="$(database_recovery_journal_path)"
    if $SUDO test -e "$journal" || $SUDO test -L "$journal"; then
        return 1
    fi
    candidate_output="$(
        $SUDO /usr/bin/find -P "$rollback_root" \
            ! -path "$rollback_root" -prune \
            -name '.source-deploy-*' -print
    )" || return 1
    while IFS= read -r candidate; do
        [[ -n "$candidate" ]] && candidates+=("$candidate")
    done <<< "$candidate_output"
    for candidate in "${candidates[@]}"; do
        if ! database_orphaned_source_snapshot_is_safe "$candidate"; then
            warn "Refusing to remove an unauthenticated orphaned source snapshot."
            return 1
        fi
    done
    for candidate in "${candidates[@]}"; do
        if ! $SUDO rm -rf -- "$candidate"; then
            warn "Could not remove an orphaned pre-journal source snapshot."
            return 1
        fi
    done
}

# Sweep `.partial-<backup_id>-<pid>` rollback-artifact staging left by a
# SIGKILLed installer.
#
# The in-process EXIT path covers the ordinary case, but a SIGKILL leaks the
# directory — and until the pg_dump left the critical path each leak was a
# partial multi-GB dump on the very volume this change exists to protect.
# Sweepers exist for `.source-deploy-*`, `.rollback-failed-deploy-*`, image-lock
# and compose-command staging; nothing swept this one.
#
# Like the source-snapshot sweeper this runs only on a fresh run (no recovery
# journal, no staging directory owned by this process), so it can never remove
# an in-flight allocation. `.partial-source-deploy-*` belongs to the snapshot
# path and is skipped here.
database_sweep_orphaned_backup_staging() {
    local rollback_root="${METADATA_DIR%/}/database-rollback"
    local journal candidate candidate_output name
    local -a candidates=()
    $SUDO test -d "$rollback_root" || return 0
    [[ -z "${DATABASE_ROLLBACK_BACKUP_STAGING_DIR:-}" ]] || return 0
    journal="$(database_recovery_journal_path)"
    if $SUDO test -e "$journal" || $SUDO test -L "$journal"; then
        return 1
    fi
    candidate_output="$(
        $SUDO /usr/bin/find -P "$rollback_root" \
            ! -path "$rollback_root" -prune \
            -name '.partial-*' -print
    )" || return 1
    while IFS= read -r candidate; do
        [[ -n "$candidate" ]] || continue
        name="$(basename -- "$candidate")"
        [[ "$name" != .partial-source-deploy-* ]] || continue
        database_path_is_safe_direct_child \
            "$rollback_root" "$candidate" ".partial-" || return 1
        candidates+=("$candidate")
    done <<< "$candidate_output"
    for candidate in "${candidates[@]}"; do
        if ! installer_private_staging_is_safe \
            "$candidate" "directory" "700"; then
            warn "Refusing to remove orphaned rollback artifact staging with unsafe ownership."
            return 1
        fi
    done
    for candidate in "${candidates[@]}"; do
        if ! $SUDO rm -rf -- "$candidate"; then
            warn "Could not remove orphaned rollback artifact staging."
            return 1
        fi
        info "Removed orphaned rollback artifact staging: $(basename -- "$candidate")"
    done
}

database_snapshot_source_deploy_state() {
    [[ "$DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED" != "true" ]] || return 0
    local rollback_root snapshot_dir staging_dir archive checksum
    local source_version active_database metadata_path metadata_archive
    local unsafe_source_entry source_command_authority
    local metadata_checksum checksums_file managed_uid managed_group
    local -a entries=("docker")

    if ! $SUDO test -d "${INSTALL_DIR}/docker" \
        || $SUDO test -L "${INSTALL_DIR}/docker"; then
        fail "Cannot snapshot source deploy state: docker directory is missing."
        return 1
    fi
    # Revoke legacy service-user namespace mutation before the entry-type scan
    # and archive. Recovery deliberately re-hardens directory metadata, so this
    # protection changes no source byte that the snapshot contract preserves.
    if ! deploy_protect_existing_managed_tree; then
        fail "Cannot snapshot source deploy state: deployment namespace is unsafe."
        return 1
    fi
    if ! unsafe_source_entry="$(
        $SUDO /usr/bin/find -P "${INSTALL_DIR}/docker" \
            \( -type l -o -type f -links +1 \
                -o \( ! -type d ! -type f \) \) \
            -print -quit
    )" || [[ -n "$unsafe_source_entry" ]]; then
        fail "Cannot snapshot source deploy state: docker tree contains an unsafe entry."
        return 1
    fi
    if ! $SUDO test -f "${INSTALL_DIR}/compose-command.sh" \
        || $SUDO test -L "${INSTALL_DIR}/compose-command.sh" \
        || ! $SUDO test -x "${INSTALL_DIR}/compose-command.sh" \
        || ! installer_path_has_single_link \
            "${INSTALL_DIR}/compose-command.sh"; then
        fail "Cannot snapshot source deploy state: compose command is missing or unsafe."
        return 1
    fi
    entries+=("compose-command.sh")
    source_command_authority="${INSTALL_DIR}/compose-command.sh"
    if $SUDO test -e "${INSTALL_DIR}/compose-command.source.sh" \
        || $SUDO test -L "${INSTALL_DIR}/compose-command.source.sh"; then
        if ! $SUDO test -f "${INSTALL_DIR}/compose-command.source.sh" \
            || $SUDO test -L "${INSTALL_DIR}/compose-command.source.sh" \
            || ! $SUDO test -x "${INSTALL_DIR}/compose-command.source.sh" \
            || ! installer_path_has_single_link \
                "${INSTALL_DIR}/compose-command.source.sh"; then
            fail "Cannot snapshot source deploy state: source recovery command is unsafe."
            return 1
        fi
        entries+=("compose-command.source.sh")
        source_command_authority="${INSTALL_DIR}/compose-command.source.sh"
    fi
    if $SUDO test -e "${INSTALL_DIR}/.version" \
        || $SUDO test -L "${INSTALL_DIR}/.version"; then
        if ! $SUDO test -f "${INSTALL_DIR}/.version" \
            || $SUDO test -L "${INSTALL_DIR}/.version" \
            || ! installer_path_has_single_link "${INSTALL_DIR}/.version"; then
            fail "Cannot snapshot source deploy state: version marker is unsafe."
            return 1
        fi
        entries+=(".version")
    fi
    source_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$source_version" || {
        fail "Cannot snapshot source deploy state: installed source version is invalid."
        return 1
    }
    if ! database_capture_source_timescaledb_bind_authority "$INSTALL_DIR"; then
        fail "Cannot snapshot source deploy state: database bind authority is unsafe or stale."
        return 1
    fi
    if ! installer_collect_canonical_compose_overlays \
        "$INSTALL_DIR" "$source_command_authority" \
        "$source_version" >/dev/null; then
        fail "Cannot snapshot source deploy state: compose command is not canonical."
        return 1
    fi
    metadata_path="${EXISTING_INSTALL:-${METADATA_DIR}/install.json}"
    if ! $SUDO test -f "$metadata_path" \
        || $SUDO test -L "$metadata_path" \
        || [[ "$(dirname -- "$metadata_path")" != "$METADATA_DIR" ]] \
        || [[ "$(basename -- "$metadata_path")" != "install.json" ]]; then
        fail "Cannot snapshot source deploy state: install metadata is missing or unsafe."
        return 1
    fi
    active_database=$(database_install_identifier) || return 1

    rollback_root="${METADATA_DIR}/database-rollback"
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || ! installer_private_staging_is_safe \
            "$rollback_root" "directory" "700" \
        || ! database_sweep_orphaned_source_snapshots \
        || ! database_sweep_orphaned_backup_staging; then
        fail "Could not authenticate and sweep orphaned source snapshots."
        return 1
    fi
    snapshot_dir="${rollback_root}/.source-deploy-$(date -u +%Y%m%dT%H%M%SZ)-$$"
    staging_dir="${rollback_root}/.partial-source-deploy-$$"
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-source-deploy-"; then
        fail "Source deploy snapshot staging path is unsafe."
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR="$staging_dir"
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || $SUDO test -e "$snapshot_dir" \
        || $SUDO test -e "$staging_dir" \
        || ! installer_install_private_directories "$staging_dir"; then
        fail "Could not allocate private source deploy snapshot staging."
        database_discard_source_snapshot_staging || true
        return 1
    fi
    archive="${staging_dir}/source-deploy.tar"
    metadata_archive="${staging_dir}/source-metadata.tar"
    checksums_file="${staging_dir}/SHA256SUMS"

    # The legacy live tree may still be service-owned at this point because the
    # snapshot must preserve exact source metadata. Exclude abandoned
    # secret-bearing writer staging without deleting through that mutable tree;
    # run_deploy locks the namespace and sweeps it immediately afterwards.
    if ! $SUDO tar \
        --exclude='docker/.env.image-lock.*' \
        --exclude='docker/.env.write.*' \
        -C "$INSTALL_DIR" -cpf "$archive" "${entries[@]}" \
        || ! $SUDO tar -C "$METADATA_DIR" -cpf "$metadata_archive" "install.json"; then
        fail "Could not archive the source deploy state before rollback."
        database_discard_source_snapshot_staging || true
        return 1
    fi
    if ! database_bind_recovery_image_lock_to_archive \
        "$archive" "$source_version"; then
        database_discard_source_snapshot_staging || true
        return 1
    fi
    if ! checksum=$(database_root_file_sha256 "$archive") \
        || ! metadata_checksum=$(database_root_file_sha256 "$metadata_archive") \
        || ! printf '%s  source-deploy.tar\n%s  source-metadata.tar\n' \
            "$checksum" "$metadata_checksum" \
            | $SUDO /usr/bin/tee "$checksums_file" >/dev/null \
        || ! $SUDO chmod 0600 \
            "$archive" "$metadata_archive" "$checksums_file"; then
        fail "Could not checksum the source deploy snapshot."
        database_discard_source_snapshot_staging || true
        return 1
    fi
    if [[ "$IS_MACOS" == "true" ]]; then
        if ! managed_uid="$(installer_managed_deployment_uid)" \
            || ! managed_group="$(installer_managed_deployment_group)" \
            || ! $SUDO chown "${managed_uid}:${managed_group}" \
                "$archive" "$metadata_archive" "$checksums_file"; then
            fail "Could not assign source deploy snapshot authority."
            database_discard_source_snapshot_staging || true
            return 1
        fi
    fi
    if ! $SUDO mv "$staging_dir" "$snapshot_dir"; then
        fail "Could not publish the private source deploy snapshot."
        database_discard_source_snapshot_staging || true
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_SNAPSHOT_STAGING_DIR=""

    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT="$snapshot_dir"
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="true"
    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    DATABASE_ROLLBACK_INSTALL_DIR="${INSTALL_DIR%/}"
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH="$metadata_path"
    DATABASE_ROLLBACK_ACTIVE_DATABASE="$active_database"
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    if ! database_write_recovery_journal "deploy-files-mutating"; then
        fail "Could not persist the rollback recovery journal before deploy mutation."
        $SUDO rm -rf "$snapshot_dir"
        DATABASE_ROLLBACK_DEPLOY_SNAPSHOT=""
        DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="false"
        return 1
    fi
    info "Source deploy state snapshotted for rollback failure recovery"
}

database_restore_failed_deploy_staging() {
    local failed_dir="$1"
    local metadata_path="${DATABASE_ROLLBACK_SOURCE_METADATA_PATH:-}"
    if $SUDO test -d "${failed_dir}/docker"; then
        $SUDO rm -rf "${INSTALL_DIR}/docker"
        $SUDO mv "${failed_dir}/docker" "${INSTALL_DIR}/docker"
    fi
    if $SUDO test -f "${failed_dir}/compose-command.sh"; then
        $SUDO rm -f "${INSTALL_DIR}/compose-command.sh"
        $SUDO mv "${failed_dir}/compose-command.sh" "${INSTALL_DIR}/compose-command.sh"
    fi
    $SUDO rm -f "${INSTALL_DIR}/compose-command.source.sh"
    if $SUDO test -f "${failed_dir}/compose-command.source.sh"; then
        $SUDO mv "${failed_dir}/compose-command.source.sh" \
            "${INSTALL_DIR}/compose-command.source.sh"
    fi
    if $SUDO test -f "${failed_dir}/.version"; then
        $SUDO rm -f "${INSTALL_DIR}/.version"
        $SUDO mv "${failed_dir}/.version" "${INSTALL_DIR}/.version"
    fi
    if [[ -n "$metadata_path" ]] && $SUDO test -f "${failed_dir}/install.json"; then
        $SUDO rm -f "$metadata_path"
        $SUDO mv "${failed_dir}/install.json" "$metadata_path"
    fi
    if ! $SUDO rm -rf "$failed_dir"; then
        warn "Exact source files were restored, but rollback staging could not be removed."
        return 1
    fi
}

database_path_is_strict_child() {
    local root="${1%/}"
    local path="$2"
    local relative component
    [[ "$root" == /* && "$root" != "/" ]] || return 1
    case "$path" in
        "${root}/"*) relative="${path#"${root}/"}" ;;
        *) return 1 ;;
    esac
    [[ -n "$relative" && "$relative" != /* ]] || return 1
    while [[ -n "$relative" ]]; do
        if [[ "$relative" == */* ]]; then
            component="${relative%%/*}"
            relative="${relative#*/}"
        else
            component="$relative"
            relative=""
        fi
        [[ -n "$component" && "$component" != "." \
            && "$component" != ".." ]] || return 1
    done
}

database_path_is_safe_direct_child() {
    local root="${1%/}"
    local path="$2"
    local prefix="$3"
    local relative
    database_path_is_strict_child "$root" "$path" || return 1
    relative="${path#"${root}/"}"
    [[ "$relative" != */* && "$relative" == "$prefix"* \
        && "${#relative}" -gt "${#prefix}" ]]
}

installer_path_has_single_link() {
    local path="$1"
    local link_count
    case "$(uname -s 2>/dev/null || true)" in
        Linux)
            link_count="$($SUDO /usr/bin/stat -Lc '%h' "$path" 2>/dev/null)" \
                || return 1
            ;;
        Darwin)
            link_count="$($SUDO /usr/bin/stat -L -f '%l' "$path" 2>/dev/null)" \
                || return 1
            ;;
        *)
            return 1
            ;;
    esac
    [[ "$link_count" == "1" ]]
}

database_discard_enumeration_staging() {
    local staging_dir="${DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR:-}"
    [[ -n "$staging_dir" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "/tmp" "$staging_dir" "llap-deploy-enumeration."; then
        warn "Refusing to remove an unsafe deploy enumeration staging path."
        DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR=""
        return 1
    fi
    if $SUDO test -e "$staging_dir" || $SUDO test -L "$staging_dir"; then
        if ! installer_private_staging_is_safe \
            "$staging_dir" "directory" "700:750"; then
            warn "Refusing to remove deploy enumeration staging with unsafe ownership."
            DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR=""
            return 1
        fi
        if ! $SUDO rm -rf -- "$staging_dir"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR=""
}

database_prepare_in_place_docker_restore() {
    local source_root="${1%/}"
    local target_root="${2%/}"
    local enumeration_dir suffix source_links target_links
    local source_hardlinks target_hardlinks target_entries status=0
    local expected_uid expected_gid expected_mode expected_metadata
    local expected_directory_mode
    local source_links_fd="" target_links_fd=""
    local source_hardlinks_fd="" target_hardlinks_fd=""
    local target_entries_validate_fd="" target_entries_delete_fd=""
    local capture_error=""
    if [[ "$target_root" == "${INSTALL_DIR%/}/docker" ]] \
        && ! deploy_protect_existing_managed_tree; then
        warn "Refusing in-place recovery into an unprotected deployment tree."
        return 1
    fi
    if ! $SUDO test -d "$source_root" \
        || $SUDO test -L "$source_root" \
        || ! $SUDO test -d "$target_root" \
        || $SUDO test -L "$target_root"; then
        return 1
    fi
    database_path_is_strict_child "$(dirname -- "$source_root")" "$source_root" \
        || return 1
    database_path_is_strict_child "$(dirname -- "$target_root")" "$target_root" \
        || return 1
    suffix="$(installer_private_staging_suffix)" || return 1
    DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR="/tmp/llap-deploy-enumeration.${suffix}"
    enumeration_dir="$DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR"
    if ! database_path_is_safe_direct_child \
        "/tmp" "$enumeration_dir" "llap-deploy-enumeration." \
        || ! installer_create_private_staging_directory "$enumeration_dir"; then
        database_discard_enumeration_staging || true
        return 1
    fi
    source_links="${enumeration_dir}/source-links"
    target_links="${enumeration_dir}/target-links"
    source_hardlinks="${enumeration_dir}/source-hardlinks"
    target_hardlinks="${enumeration_dir}/target-hardlinks"
    target_entries="${enumeration_dir}/target-entries"
    local enumeration_failed="false"
    local -a enumeration_status=()
    {
        $SUDO find -P "$source_root" -type l -print0 \
            | $SUDO /usr/bin/tee "$source_links" >/dev/null
        enumeration_status=("${PIPESTATUS[@]}")
    } || true
    [[ "${enumeration_status[0]}" == 0 \
        && "${enumeration_status[1]}" == 0 ]] || enumeration_failed="true"
    {
        $SUDO find -P "$target_root" -type l -print0 \
            | $SUDO /usr/bin/tee "$target_links" >/dev/null
        enumeration_status=("${PIPESTATUS[@]}")
    } || true
    [[ "${enumeration_status[0]}" == 0 \
        && "${enumeration_status[1]}" == 0 ]] || enumeration_failed="true"
    {
        $SUDO find -P "$source_root" -type f -links +1 -print0 \
            | $SUDO /usr/bin/tee "$source_hardlinks" >/dev/null
        enumeration_status=("${PIPESTATUS[@]}")
    } || true
    [[ "${enumeration_status[0]}" == 0 \
        && "${enumeration_status[1]}" == 0 ]] || enumeration_failed="true"
    {
        $SUDO find -P "$target_root" -type f -links +1 -print0 \
            | $SUDO /usr/bin/tee "$target_hardlinks" >/dev/null
        enumeration_status=("${PIPESTATUS[@]}")
    } || true
    [[ "${enumeration_status[0]}" == 0 \
        && "${enumeration_status[1]}" == 0 ]] || enumeration_failed="true"
    {
        $SUDO find -P "$target_root" -depth -mindepth 1 -print0 \
            | $SUDO /usr/bin/tee "$target_entries" >/dev/null
        enumeration_status=("${PIPESTATUS[@]}")
    } || true
    [[ "${enumeration_status[0]}" == 0 \
        && "${enumeration_status[1]}" == 0 ]] || enumeration_failed="true"
    if [[ "$enumeration_failed" == "true" ]] \
        || ! $SUDO test -f "$source_links" \
        || ! $SUDO test -f "$target_links" \
        || ! $SUDO test -f "$source_hardlinks" \
        || ! $SUDO test -f "$target_hardlinks" \
        || ! $SUDO test -f "$target_entries" \
        || $SUDO test -L "$source_links" \
        || $SUDO test -L "$target_links" \
        || $SUDO test -L "$source_hardlinks" \
        || $SUDO test -L "$target_hardlinks" \
        || $SUDO test -L "$target_entries"; then
        warn "Could not enumerate deploy trees for safe in-place recovery."
        database_discard_enumeration_staging || true
        return 1
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        expected_uid="$(installer_managed_deployment_uid)" \
            || capture_error="Deploy enumeration owner could not be resolved."
        expected_gid="$(installer_managed_deployment_group)" \
            || capture_error="Deploy enumeration operator group could not be resolved."
        expected_directory_mode=700
        expected_mode=400
    elif [[ -n "$SUDO" || "$EUID" -eq 0 ]]; then
        expected_uid=0
        expected_directory_mode=750
        expected_mode=440
    else
        expected_uid="$(id -u)" \
            || capture_error="Deploy enumeration owner could not be resolved."
        expected_directory_mode=700
        expected_mode=400
    fi
    if [[ "$IS_MACOS" != "true" ]]; then
        if [[ "$EUID" -eq 0 && -n "${SUDO_USER:-}" \
            && "${SUDO_USER}" != "root" ]]; then
            expected_gid="$(id -g "$SUDO_USER")" \
                || capture_error="Deploy enumeration operator group could not be resolved."
        else
            expected_gid="$(id -g)" \
                || capture_error="Deploy enumeration operator group could not be resolved."
        fi
    fi
    if [[ -z "$capture_error" ]] \
        && { [[ ! "$expected_uid" =~ ^[0-9]+$ ]] \
            || [[ ! "$expected_gid" =~ ^[0-9]+$ ]]; }; then
        capture_error="Deploy enumeration ownership is invalid."
    fi
    if [[ -z "$capture_error" ]] \
        && { ! $SUDO chown "${expected_uid}:${expected_gid}" \
                "$enumeration_dir" "$source_links" "$target_links" \
                "$source_hardlinks" "$target_hardlinks" "$target_entries" \
            || ! $SUDO chmod "0${expected_directory_mode}" "$enumeration_dir" \
            || ! $SUDO chmod "0${expected_mode}" \
                "$source_links" "$target_links" \
                "$source_hardlinks" "$target_hardlinks" "$target_entries"; }; then
        capture_error="Deploy enumeration staging could not be protected."
    fi
    expected_metadata="${expected_uid}:${expected_gid}:${expected_mode}:1"
    if [[ -z "$capture_error" ]] \
        && { [[ "$(database_snapshot_file_metadata "$source_links")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_metadata "$target_links")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_metadata "$source_hardlinks")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_metadata "$target_hardlinks")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_metadata "$target_entries")" \
                != "$expected_metadata" ]]; }; then
        capture_error="Deploy enumeration staging ownership or type is unsafe."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {source_links_fd}< "$source_links"; then
        capture_error="Source symlink enumeration could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {target_links_fd}< "$target_links"; then
        capture_error="Target symlink enumeration could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {source_hardlinks_fd}< "$source_hardlinks"; then
        capture_error="Source hardlink enumeration could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {target_hardlinks_fd}< "$target_hardlinks"; then
        capture_error="Target hardlink enumeration could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {target_entries_validate_fd}< "$target_entries"; then
        capture_error="Target entry validation view could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && ! exec {target_entries_delete_fd}< "$target_entries"; then
        capture_error="Target entry deletion view could not be opened."
    fi
    if [[ -z "$capture_error" ]] \
        && { [[ ! "$source_links" -ef "/dev/fd/${source_links_fd}" ]] \
            || [[ ! "$target_links" -ef "/dev/fd/${target_links_fd}" ]] \
            || [[ ! "$source_hardlinks" -ef \
                "/dev/fd/${source_hardlinks_fd}" ]] \
            || [[ ! "$target_hardlinks" -ef \
                "/dev/fd/${target_hardlinks_fd}" ]] \
            || [[ ! "$target_entries" -ef \
                "/dev/fd/${target_entries_validate_fd}" ]] \
            || [[ ! "$target_entries" -ef \
                "/dev/fd/${target_entries_delete_fd}" ]]; }; then
        capture_error="Deploy enumeration changed identity while opening."
    fi
    if [[ -z "$capture_error" ]] \
        && { ! $SUDO chmod 0000 \
                "$source_links" "$target_links" \
                "$source_hardlinks" "$target_hardlinks" "$target_entries" \
            || ! $SUDO rm -f -- \
                "$source_links" "$target_links" \
                "$source_hardlinks" "$target_hardlinks" "$target_entries" \
            || ! $SUDO rmdir -- "$enumeration_dir"; }; then
        capture_error="Deploy enumeration names could not be removed safely."
    fi
    if [[ -n "$capture_error" ]]; then
        [[ -z "$source_links_fd" ]] \
            || exec {source_links_fd}<&- 2>/dev/null || true
        [[ -z "$target_links_fd" ]] \
            || exec {target_links_fd}<&- 2>/dev/null || true
        [[ -z "$source_hardlinks_fd" ]] \
            || exec {source_hardlinks_fd}<&- 2>/dev/null || true
        [[ -z "$target_hardlinks_fd" ]] \
            || exec {target_hardlinks_fd}<&- 2>/dev/null || true
        [[ -z "$target_entries_validate_fd" ]] \
            || exec {target_entries_validate_fd}<&- 2>/dev/null || true
        [[ -z "$target_entries_delete_fd" ]] \
            || exec {target_entries_delete_fd}<&- 2>/dev/null || true
        database_discard_enumeration_staging || true
        warn "$capture_error"
        return 1
    fi
    DATABASE_ROLLBACK_ENUMERATION_STAGING_DIR=""

    if ! (
        local path relative source_path
        # A directory symlink could redirect archive extraction outside the
        # installer-owned tree. Non-directory symlinks are safe leaves because
        # type conflicts are removed below and archive copy does not follow
        # source symlinks.
        while IFS= read -r -d '' path; do
            database_path_is_strict_child "$source_root" "$path" || {
                warn "Source deploy enumeration escaped its trusted root."
                exit 1
            }
            if $SUDO test -d "$path"; then
                warn "Source deploy snapshot contains a directory symlink."
                exit 1
            fi
        done <&"$source_links_fd"
        while IFS= read -r -d '' path; do
            database_path_is_strict_child "$target_root" "$path" || {
                warn "Target deploy enumeration escaped its trusted root."
                exit 1
            }
            if $SUDO test -d "$path"; then
                warn "Target deploy tree contains a directory symlink."
                exit 1
            fi
        done <&"$target_links_fd"
        if [[ -s "/dev/fd/${source_hardlinks_fd}" ]]; then
            warn "Source deploy snapshot contains hardlinked regular files."
            exit 1
        fi
        if [[ -s "/dev/fd/${target_hardlinks_fd}" ]]; then
            warn "Target deploy tree contains hardlinked regular files."
            exit 1
        fi

        # Validate the complete immutable deletion view before the first target
        # mutation. The independent deletion descriptor starts at offset zero.
        while IFS= read -r -d '' path; do
            database_path_is_strict_child "$target_root" "$path" || {
                warn "Refusing an out-of-tree deploy recovery deletion."
                exit 1
            }
        done <&"$target_entries_validate_fd"

        # Remove target-only leaves and type conflicts bottom-up. Directories
        # also present in the source are retained so live Docker bind mounts
        # keep the same inode throughout pre-runtime recovery.
        while IFS= read -r -d '' path; do
            database_path_is_strict_child "$target_root" "$path" || {
                warn "Refusing an out-of-tree deploy recovery deletion."
                exit 1
            }
            relative="${path#"${target_root}/"}"
            source_path="${source_root}/${relative}"
            if $SUDO test -d "$path" && ! $SUDO test -L "$path"; then
                if $SUDO test -d "$source_path" \
                    && ! $SUDO test -L "$source_path"; then
                    continue
                fi
                $SUDO rmdir -- "$path" || exit 1
                continue
            fi
            if $SUDO test -f "$path" && ! $SUDO test -L "$path" \
                && $SUDO test -f "$source_path" \
                && ! $SUDO test -L "$source_path"; then
                continue
            fi
            if $SUDO test -L "$path" && $SUDO test -L "$source_path"; then
                continue
            fi
            $SUDO rm -f -- "$path" || exit 1
        done <&"$target_entries_delete_fd"
    ); then
        status=1
    fi
    exec {source_links_fd}<&- 2>/dev/null || status=1
    exec {target_links_fd}<&- 2>/dev/null || status=1
    exec {source_hardlinks_fd}<&- 2>/dev/null || status=1
    exec {target_hardlinks_fd}<&- 2>/dev/null || status=1
    exec {target_entries_validate_fd}<&- 2>/dev/null || status=1
    exec {target_entries_delete_fd}<&- 2>/dev/null || status=1
    return "$status"
}

database_discard_restore_staging() {
    local staging_root="${DATABASE_ROLLBACK_RESTORE_STAGING_ROOT:-}"
    [[ -n "$staging_root" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "/tmp" "$staging_root" "llap-deploy-restore."; then
        warn "Refusing to remove an unsafe deploy restore staging path."
        DATABASE_ROLLBACK_RESTORE_STAGING_ROOT=""
        return 1
    fi
    if $SUDO test -e "$staging_root" || $SUDO test -L "$staging_root"; then
        if ! installer_private_staging_is_safe \
            "$staging_root" "directory" "700"; then
            warn "Refusing to remove deploy restore staging with unsafe ownership."
            DATABASE_ROLLBACK_RESTORE_STAGING_ROOT=""
            return 1
        fi
        if ! $SUDO rm -rf -- "$staging_root"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_RESTORE_STAGING_ROOT=""
}

database_restore_source_deploy_state() {
    [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]] || return 0
    local preserve_running_proxy="${1:-false}"
    local snapshot_dir archive metadata_archive expected metadata_expected actual metadata_actual
    local restore_staging_root suffix temp_dir metadata_temp_dir failed_dir metadata_path
    local receipt_recovery_present="false"
    database_discard_restore_staging || return 1
    snapshot_dir="$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT"
    archive="${snapshot_dir}/source-deploy.tar"
    metadata_archive="${snapshot_dir}/source-metadata.tar"
    metadata_path="$DATABASE_ROLLBACK_SOURCE_METADATA_PATH"

    if ! $SUDO test -d "$snapshot_dir" || ! $SUDO test -s "$archive" \
        || ! $SUDO test -s "$metadata_archive" \
        || ! $SUDO test -s "${snapshot_dir}/SHA256SUMS" \
        || $SUDO test -L "$snapshot_dir" || $SUDO test -L "$archive" \
        || $SUDO test -L "$metadata_archive"; then
        warn "Source deploy snapshot is absent or unsafe; refusing partial file recovery."
        return 1
    fi
    # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
    expected=$($SUDO awk '$2 == "source-deploy.tar" {print $1}' \
        "${snapshot_dir}/SHA256SUMS")
    # shellcheck disable=SC2016  # Awk fields are intentionally single-quoted.
    metadata_expected=$($SUDO awk '$2 == "source-metadata.tar" {print $1}' \
        "${snapshot_dir}/SHA256SUMS")
    [[ "$expected" =~ ^[0-9a-f]{64}$ \
        && "$metadata_expected" =~ ^[0-9a-f]{64}$ ]] || return 1
    if ! actual=$(database_root_file_sha256 "$archive") \
        || ! metadata_actual=$(database_root_file_sha256 "$metadata_archive"); then
        warn "Source deploy snapshot could not be read and checksummed."
        return 1
    fi
    if [[ "$actual" != "$expected" || "$metadata_actual" != "$metadata_expected" ]]; then
        warn "Source deploy snapshot checksum mismatch; refusing partial file recovery."
        return 1
    fi

    suffix="$(installer_private_staging_suffix)" || return 1
    DATABASE_ROLLBACK_RESTORE_STAGING_ROOT="/tmp/llap-deploy-restore.${suffix}"
    restore_staging_root="$DATABASE_ROLLBACK_RESTORE_STAGING_ROOT"
    if ! database_path_is_safe_direct_child \
        "/tmp" "$restore_staging_root" "llap-deploy-restore." \
        || ! installer_create_private_staging_directory \
            "$restore_staging_root"; then
        database_discard_restore_staging || true
        return 1
    fi
    temp_dir="${restore_staging_root}/deploy"
    metadata_temp_dir="${restore_staging_root}/metadata"
    if ! installer_install_private_directories "$temp_dir" "$metadata_temp_dir" \
        || ! $SUDO tar -xpf "$archive" -C "$temp_dir" \
        || ! $SUDO tar -xpf "$metadata_archive" -C "$metadata_temp_dir" \
        || ! $SUDO test -d "${temp_dir}/docker" \
        || $SUDO test -L "${temp_dir}/docker" \
        || ! $SUDO test -f "${temp_dir}/compose-command.sh" \
        || $SUDO test -L "${temp_dir}/compose-command.sh" \
        || ! $SUDO test -x "${temp_dir}/compose-command.sh" \
        || ! $SUDO test -f "${metadata_temp_dir}/install.json" \
        || $SUDO test -L "${metadata_temp_dir}/install.json"; then
        warn "Source deploy snapshot extraction failed."
        return 1
    fi
    if $SUDO test -e "${temp_dir}/compose-command.source.sh" \
        || $SUDO test -e \
            "${temp_dir}/docker/docker-compose.receipt-recovery.yml"; then
        receipt_recovery_present="true"
    fi
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" \
        || "$receipt_recovery_present" == "true" ]]; then
        if ! $SUDO test -f "${temp_dir}/compose-command.source.sh" \
            || $SUDO test -L "${temp_dir}/compose-command.source.sh" \
            || ! $SUDO test -x "${temp_dir}/compose-command.source.sh" \
            || ! $SUDO test -f \
                "${temp_dir}/docker/docker-compose.receipt-recovery.yml" \
            || $SUDO test -L \
                "${temp_dir}/docker/docker-compose.receipt-recovery.yml"; then
            warn "Receipt-bound source recovery files are absent or unsafe."
            return 1
        fi
    fi
    if ! deploy_harden_recovered_tree "$temp_dir"; then
        warn "Source deploy snapshot contains unsafe entries or ownership."
        return 1
    fi
    if ! database_prepare_trusted_recovered_compose \
            "$temp_dir" "$DATABASE_ROLLBACK_SOURCE_VERSION" \
        || ! database_validate_staged_recovery_compose \
            "$temp_dir" "$DATABASE_ROLLBACK_SOURCE_VERSION"; then
        warn "Source deploy snapshot Compose authority is not canonical."
        return 1
    fi
    # Only now is the checksummed replacement fully extracted and hardened.
    # Retain any crash-staged target until this point so a corrupt source
    # archive never destroys the last operator-recoverable tree.
    if ! database_sweep_stale_failed_deploy_staging; then
        warn "Validated source recovery could not remove stale failed-target staging."
        return 1
    fi

    [[ "$preserve_running_proxy" == "true" \
        || "$preserve_running_proxy" == "false" ]] || return 1
    # Recovery always removes the complete target stack before replacing the
    # deploy tree. Even before runtime mutation, an in-place cp would retain a
    # writable descriptor opened against a legacy service-owned boot hook. The
    # extracted source is recursively link-checked and hardened above; a stopped
    # full-tree replacement is the only publication that revokes every target
    # inode before the recovered root command executes.
    if [[ "$preserve_running_proxy" == "true" ]]; then
        info "Protected source recovery requires a complete stack restart"
    fi

    if $SUDO test -d "${INSTALL_DIR}/docker" \
        && ! $SUDO test -L "${INSTALL_DIR}/docker"; then
        # Reconstruct the invocation from the strictly validated source command
        # and use only extracted source configuration. No legacy script bytes
        # are ever executed as root.
        if ! database_run_trusted_recovered_compose \
            "$temp_dir" "$DATABASE_ROLLBACK_SOURCE_VERSION" \
            down --remove-orphans \
            >> "$LOG_FILE" 2>&1; then
            warn "Could not remove the complete target stack before deploy-tree replacement."
            return 1
        fi
    elif [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != \
        "deploy-stack-stopped" ]]; then
        warn "Target Compose command is absent or unsafe; refusing deploy-tree replacement."
        return 1
    fi
    # Once this phase is durable, a fresh installer may resume from the source
    # snapshot even if SIGKILL lands while the target command/tree is renamed.
    # If a usable command still exists on re-entry, the idempotent down above
    # runs again to remove any partial or manually restarted stack first.
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != \
        "deploy-stack-stopped" ]] \
        && ! database_write_recovery_journal "deploy-stack-stopped"; then
        warn "Complete target stack was removed, but its durable recovery phase could not be recorded."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="true"
    suffix="$(installer_private_staging_suffix)" || return 1
    failed_dir="${INSTALL_DIR}/.rollback-failed-deploy-${suffix}"
    if $SUDO test -e "$failed_dir"; then
        warn "Rollback deploy recovery staging path already exists."
        return 1
    fi
    if ! installer_install_private_directories "$failed_dir"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "${INSTALL_DIR}/docker" \
        && ! $SUDO mv "${INSTALL_DIR}/docker" "${failed_dir}/docker"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "${INSTALL_DIR}/compose-command.sh" \
        && ! $SUDO mv "${INSTALL_DIR}/compose-command.sh" \
            "${failed_dir}/compose-command.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "${INSTALL_DIR}/compose-command.source.sh" \
        && ! $SUDO mv "${INSTALL_DIR}/compose-command.source.sh" \
            "${failed_dir}/compose-command.source.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -f "${INSTALL_DIR}/.version" \
        && ! $SUDO mv "${INSTALL_DIR}/.version" "${failed_dir}/.version"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -e "$metadata_path" \
        && ! $SUDO mv "$metadata_path" "${failed_dir}/install.json"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! $SUDO mv "${temp_dir}/docker" "${INSTALL_DIR}/docker" \
        || ! $SUDO mv "${temp_dir}/compose-command.sh" \
            "${INSTALL_DIR}/compose-command.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -f "${temp_dir}/compose-command.source.sh" \
        && ! $SUDO mv "${temp_dir}/compose-command.source.sh" \
            "${INSTALL_DIR}/compose-command.source.sh"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if $SUDO test -f "${temp_dir}/.version"; then
        if ! $SUDO mv "${temp_dir}/.version" "${INSTALL_DIR}/.version"; then
            database_restore_failed_deploy_staging "$failed_dir" || true
            return 1
        fi
    else
        if ! $SUDO rm -f "${INSTALL_DIR}/.version"; then
            database_restore_failed_deploy_staging "$failed_dir" || true
            return 1
        fi
    fi
    if ! $SUDO mv "${metadata_temp_dir}/install.json" "$metadata_path"; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! deploy_harden_recovered_tree "$INSTALL_DIR"; then
        warn "Published source deploy tree failed its final protection check."
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! database_discard_restore_staging; then
        database_restore_failed_deploy_staging "$failed_dir" || true
        return 1
    fi
    if ! $SUDO rm -rf "$failed_dir"; then
        warn "Exact source files were restored, but rollback staging could not be removed."
        return 1
    fi

    if ! database_run_trusted_recovered_compose \
        "$INSTALL_DIR" "$DATABASE_ROLLBACK_SOURCE_VERSION" \
        up -d >> "$LOG_FILE" 2>&1; then
        warn "Exact source deploy state was restored, but its full stack did not restart."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
    if ! database_wait_for_source_stack_healthy; then
        warn "Exact source deploy stack restarted but did not become healthy; durable recovery state is retained."
        return 1
    fi
    if ! database_discard_source_deploy_snapshot; then
        warn "Exact source recovery completed, but its durable snapshot cleanup did not finish."
        return 1
    fi
    info "Exact source deploy state restored after rollback failure"
}

database_discard_source_deploy_snapshot() {
    [[ -n "${DATABASE_ROLLBACK_DEPLOY_SNAPSHOT:-}" ]] || return 0
    # Persist the no-reversal boundary before deleting the only source
    # snapshot. A process loss after this phase can finish cleanup
    # idempotently; it must never interpret an absent snapshot as a reason to
    # reverse an already healthy target.
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != "target-healthy" ]]; then
        # INSTALL_DIR may be a separate filesystem from METADATA_DIR. Flush the
        # proven-healthy target bytes before the durable journal tells recovery
        # to keep them and permits deletion of the only source snapshot.
        if ! installer_durable_sync_path "$INSTALL_DIR" \
            || ! database_write_recovery_journal "target-healthy"; then
            return 1
        fi
    fi
    if $SUDO test -e "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT" \
        && ! $SUDO rm -rf "$DATABASE_ROLLBACK_DEPLOY_SNAPSHOT"; then
        return 1
    fi
    if ! database_clear_recovery_journal; then
        return 1
    fi
    DATABASE_ROLLBACK_DEPLOY_SNAPSHOT=""
    DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED="false"
    DATABASE_ROLLBACK_INSTALL_DIR=""
    DATABASE_ROLLBACK_SOURCE_METADATA_PATH=""
    DATABASE_FORWARD_UPGRADE_ACTIVE="false"
}

# Read and validate the database identifier from the installer-managed .env.
# Identifiers are deliberately restricted before they can reach psql variables.
database_install_identifier() {
    local value
    value=$(existing_env_value "POSTGRES_DB")
    value="${value:-llm_proxy}"
    [[ "$value" =~ ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]] \
        || die "POSTGRES_DB is not a safe PostgreSQL identifier for installer-managed recovery."
    printf '%s\n' "$value"
}

database_query_migration_version() {
    local database="$1"
    local version
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    version=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname="$1" --no-align --tuples-only --set=ON_ERROR_STOP=1 --command="SELECT COALESCE(MAX(version), 0) FROM _sqlx_migrations"' \
        sh "$database" 2>> "$LOG_FILE") || return 1
    version=$(printf '%s' "$version" | tr -d '[:space:]')
    [[ "$version" =~ ^[0-9]+$ ]] || return 1
    printf '%s\n' "$version"
}

database_quiesce_proxy() {
    [[ "$DATABASE_ROLLBACK_PROXY_STOPPED" != "true" ]] || return 0
    if ! installer_run_live_compose stop proxy >> "$LOG_FILE" 2>&1; then
        fail "Could not stop the proxy before the database recovery snapshot."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="true"
    info "Proxy quiesced for a consistent database recovery point"
}

database_resume_proxy() {
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        warn "Refusing to start a target deploy while exact source-state recovery is incomplete."
        return 1
    fi
    [[ "${DATABASE_ROLLBACK_PROXY_STOPPED:-false}" == "true" ]] || return 0
    if ! installer_run_live_compose start proxy >> "$LOG_FILE" 2>&1; then
        warn "Could not resume the quiesced proxy; rerun the verified installer."
        return 1
    fi
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
    info "Prior proxy resumed"
}

database_remove_quiesced_proxy_container() {
    [[ "${DATABASE_ROLLBACK_PROXY_STOPPED:-false}" == "true" ]] || return 1
    if ! installer_run_live_compose rm -f -s proxy \
        >> "$LOG_FILE" 2>&1; then
        fail "Could not remove the quiesced source proxy before database rollback."
        return 1
    fi
    info "Quiesced source proxy container removed before database swap"
}

database_discard_backup_staging() {
    local staging_dir="${DATABASE_ROLLBACK_BACKUP_STAGING_DIR:-}"
    local rollback_root="${METADATA_DIR}/database-rollback"
    [[ -n "$staging_dir" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-"; then
        warn "Refusing to remove an unsafe database backup staging path."
        DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""
        return 1
    fi
    if $SUDO test -e "$staging_dir" \
        && ! $SUDO rm -rf -- "$staging_dir"; then
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""
}

# Raise the ALREADY-RUNNING database container's memory cgroup before the
# pre-upgrade dump (#1737).
#
# Writing TIMESCALEDB_MEMORY_LIMIT to .env is not enough on the upgrade path.
# The recovery dump runs via `compose exec` against the container that is
# ALREADY UP, and Compose configuration does not retroactively change a running
# container's cgroup — the new limit only takes effect when the stack is
# recreated, which happens AFTER the dump. Without this the dump keeps OOMing at
# the old limit and the upgrade can never proceed.
#
# `docker update` adjusts the cgroup live, with no restart and no dropped
# connections. Best-effort: a failure here must not abort the upgrade, because
# the dump may still succeed at the existing limit.
database_raise_runtime_memory_limit() {
    local desired container_id current
    desired="${OPT_TIMESCALEDB_MEMORY_LIMIT:-}"
    [[ -z "$desired" ]] && return 0

    container_id=$(installer_run_live_compose ps -q timescaledb 2>/dev/null || true)
    [[ -z "$container_id" ]] && return 0

    current=$(installer_docker inspect --format='{{.HostConfig.Memory}}' "$container_id" 2>/dev/null || echo "")
    local desired_bytes
    desired_bytes=$(timescaledb_size_to_bytes "$desired") || return 0
    # Only ever RAISE. Lowering the limit under a live database risks an OOM
    # kill of the very server we are about to dump.
    if [[ -n "$current" ]] && [[ "$current" =~ ^[0-9]+$ ]] && (( current != 0 )) \
        && (( desired_bytes <= current )); then
        return 0
    fi

    # memory-swap MUST be raised in the same call, and it must be a concrete
    # value >= the new memory limit.
    #
    # Docker materialises HostConfig.MemorySwap = 2 x Memory at create time when
    # only `memory:` is set, which is exactly what the compose file does — the
    # production container is Memory=2g / MemorySwap=4g. Against that shape both
    # obvious forms are REJECTED by runc, verified against docker on a container
    # created with `--memory=2g`:
    #
    #   --memory=8g --memory-swap=-1  ->  "memory+swap limit should be >= memory limit"
    #   --memory=8g                   ->  "Memory limit should be smaller than already
    #                                      set memoryswap limit, update the memoryswap
    #                                      at the same time"
    #
    # Both leave the cgroup untouched. Since this call is best-effort, the fix
    # would have silently no-opped and the dump would have OOMed exactly as
    # before. Mirror docker's own 2x default so the live shape matches what
    # `deploy_start_stack` will recreate the container as.
    local swap_bytes
    swap_bytes=$(( desired_bytes * 2 ))

    step "  Raising database container memory limit to ${desired} for the recovery dump..."
    if installer_docker update --memory="$desired_bytes" \
        --memory-swap="$swap_bytes" "$container_id" >/dev/null 2>&1; then
        info "  ✓ Database container memory limit raised to ${desired}"
    else
        # Non-fatal by design — a small database may still dump at the existing
        # limit — but say plainly what will happen next, because the OOM arrives
        # minutes later inside pg_dump and reads as an unrelated failure.
        DATABASE_MEMORY_RAISE_FAILED="true"
        warn "  Could not raise the database container memory limit to ${desired}."
        warn "  The recovery dump will run at the existing limit and may be OOM-killed."
    fi
    return 0
}

# Convert a docker size string (8g, 512m, 1.5G, 6gb) to bytes. Echoes the value;
# returns non-zero when the input is not parseable.
timescaledb_size_to_bytes() {
    local v="${1:-}" num unit mult
    [[ "$v" =~ ^([0-9]+([.][0-9]+)?)([bkmgtBKMGT])[bB]?$ ]] || return 1
    num="${BASH_REMATCH[1]}"
    unit=$(printf '%s' "${BASH_REMATCH[3]}" | tr '[:upper:]' '[:lower:]')
    case "$unit" in
        b) mult=1 ;;
        k) mult=1024 ;;
        m) mult=$((1024 * 1024)) ;;
        g) mult=$((1024 * 1024 * 1024)) ;;
        t) mult=$((1024 * 1024 * 1024 * 1024)) ;;
        *) return 1 ;;
    esac
    awk -v n="$num" -v m="$mult" 'BEGIN { printf "%d", n * m }'
    return 0
}

# Status of the process FEEDING an archive into pg_restore.
#
# `pg_restore --list` reads only the archive's table of contents and exits,
# so on any dump larger than the pipe buffer the feeder is still writing and
# the kernel kills it with SIGPIPE (128 + 13 = 141). That is the reader
# working exactly as designed, not a damaged archive. A production 0.0.130 ->
# 0.0.133 upgrade aborted on precisely this: the complete 4,679-line table of
# contents had already printed to the installer log when the step was reported
# as "failed archive validation" (#1757). It never fired on small dumps
# because the Compose daemon drained the whole channel first.
#
# Only the WRITER is forgiven, and only for SIGPIPE. The reader's status is
# still required to be exactly 0 by every caller, so a truncated or corrupt
# archive — which makes pg_restore itself exit non-zero — still fails closed.
database_archive_feed_status_is_ok() {
    local status="${1:-1}"
    [[ "$status" == 0 || "$status" == 141 ]]
}

# Run an archive READER on stdin, then swallow whatever the reader did not read.
#
# What the feeder's exit status means once the pipe is broken depends on a
# signal disposition the installer does not own, because SIG_IGN survives both
# fork and exec:
#
#   SIGPIPE default   the feeder is killed outright   -> status 141
#   SIGPIPE ignored   write() returns EPIPE instead   -> GNU cat prints
#                     "cat: write error: Broken pipe" -> status 1
#
# Any parent that ignores SIGPIPE process-wide imposes the second form on every
# descendant. The GitHub Actions runner does exactly that, which is why this
# validation failed only in CI; an operator driving the installer from a .NET,
# JVM or Node supervisor would have hit the identical fabricated abort in
# production. Status 1 is indistinguishable from "could not read the dump", so
# it cannot be forgiven without also forgiving a genuine read failure.
#
# The fix is to stop breaking the pipe. This function holds the read end open
# and discards the remainder ON THE HOST — the drained bytes never reach the
# database container — so the feeder always terminates normally and its status
# stays trustworthy. The reader's status, which is what actually validates the
# archive, is returned unchanged, so a corrupt archive still fails closed.
database_read_archive_then_drain() {
    local reader_status=0
    "$@" || reader_status=$?
    cat > /dev/null 2>> "$LOG_FILE" || true
    return "$reader_status"
}

# Create the durable, checksummed rollback dump.
#
# `source_database` (optional 4th positional) selects WHERE the bytes come from.
# Empty — the rollback path — dumps the LIVE installer-managed database and
# quiesces the proxy first, so the dump is a consistent recovery point.
# Non-empty — the deferred forward-upgrade dump (#1757) — dumps a named frozen
# database that nothing is writing to, so there is nothing to quiesce and the
# proxy must keep serving.
database_create_version_backup() {
    local source_version="$1"
    local target_version="$2"
    local purpose="$3"
    local source_database="${4:-}"
    local database timestamp backup_id rollback_root final_dir staging_dir
    local dump_file manifest_file migration_version checksum
    local -a archive_status=()
    local -a dump_command=()

    if ! is_stable_semver "$source_version" \
        || ! is_stable_semver "$target_version" \
        || [[ "$purpose" != "pre-upgrade" && "$purpose" != "pre-rollback" ]]; then
        database_abort_rollback || true
        return 1
    fi

    if ! database=$(database_install_identifier); then
        database_abort_rollback || true
        return 1
    fi
    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    backup_id="${purpose}-${source_version}-to-${target_version}-${timestamp}"
    database_backup_id_is_safe "$backup_id" || return 1
    rollback_root="${METADATA_DIR}/database-rollback"
    final_dir="${rollback_root}/${backup_id}"
    staging_dir="${rollback_root}/.partial-${backup_id}-$$"
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-"; then
        database_abort_rollback || true
        return 1
    fi

    if [[ -n "$source_database" ]]; then
        if ! database_recovery_identifier_is_safe "$source_database"; then
            fail "Refusing to dump an unsafe source database identifier."
            database_abort_rollback || true
            return 1
        fi
    elif ! database_quiesce_proxy; then
        database_abort_rollback || true
        return 1
    fi
    if ! migration_version=$(database_query_migration_version \
        "${source_database:-$database}"); then
        fail "Could not read the current migration version before database backup."
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR="$staging_dir"
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || $SUDO test -e "$final_dir" \
        || $SUDO test -e "$staging_dir"; then
        fail "Database recovery backup staging could not be allocated safely."
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi
    if ! installer_install_private_directories "$staging_dir"; then
        fail "Database recovery backup staging could not be created."
        database_abort_rollback || true
        return 1
    fi
    dump_file="${staging_dir}/database.dump"
    manifest_file="${staging_dir}/manifest.json"

    # The dump below runs inside the ALREADY-RUNNING container, so the .env
    # limit has not taken effect yet — raise the live cgroup first (#1737).
    database_raise_runtime_memory_limit

    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if [[ -n "$source_database" ]]; then
        dump_command=(sh -ceu 'exec pg_dump --format=custom --no-owner --no-acl --username="$POSTGRES_USER" --dbname="$1"' sh "$source_database")
    else
        dump_command=(sh -ceu 'exec pg_dump --format=custom --no-owner --no-acl --username="$POSTGRES_USER" --dbname="$POSTGRES_DB"')
    fi
    if ! installer_run_live_compose exec -T timescaledb \
        "${dump_command[@]}" \
        2>> "$LOG_FILE" \
        | $SUDO /usr/bin/tee "$dump_file" >/dev/null; then
        fail "PostgreSQL recovery dump failed; the active database was not changed."
        if [[ "${DATABASE_MEMORY_RAISE_FAILED:-false}" == "true" ]]; then
            # Connect the two events. The raise warned minutes ago; this is its
            # consequence, and on its own it reads as an unrelated failure.
            fail "The database container memory limit could not be raised earlier (#1737)."
            fail "A large database is OOM-killed by the default 2g cgroup limit here."
            fail "Check 'dmesg | grep oom-kill', then retry with --timescaledb-memory-limit=8g."
        fi
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi
    if ! $SUDO chmod 0600 "$dump_file" \
        || ! $SUDO test -s "$dump_file"; then
        fail "PostgreSQL recovery dump is empty; the active database was not changed."
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi
    {
        $SUDO cat "$dump_file" 2>> "$LOG_FILE" \
            | database_read_archive_then_drain \
                installer_run_live_compose exec -T timescaledb \
                sh -ceu 'exec pg_restore --list' >> "$LOG_FILE" 2>&1
        archive_status=("${PIPESTATUS[@]}")
    } || true
    if ! database_archive_feed_status_is_ok "${archive_status[0]:-1}" \
        || [[ "${archive_status[1]:-1}" != 0 ]]; then
        # Name both halves. "failed archive validation" alone is what made the
        # production abort unreadable: the complete table of contents had
        # already printed, so the archive was demonstrably fine and only the
        # status was wrong.
        fail "PostgreSQL recovery dump failed archive validation (feeder=${archive_status[0]:-unset} reader=${archive_status[1]:-unset})."
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi

    checksum=$(database_root_file_sha256 "$dump_file") || {
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    }
    if ! jq -n \
        --arg backup_id "$backup_id" \
        --arg source_version "$source_version" \
        --arg target_version "$target_version" \
        --arg database "$database" \
        --arg migration_version "$migration_version" \
        --arg created_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        --arg sha256 "$checksum" \
        '{format_version: 1, backup_id: $backup_id,
          source_version: $source_version, target_version: $target_version,
          database: $database, migration_version: $migration_version,
          created_at: $created_at, dump_file: "database.dump", sha256: $sha256}' \
        | $SUDO /usr/bin/tee "$manifest_file" >/dev/null \
        || ! $SUDO chmod 0600 "$manifest_file" \
        || ! $SUDO test -s "$manifest_file"; then
        fail "Could not write the private database recovery manifest."
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi
    if ! $SUDO mv "$staging_dir" "$final_dir"; then
        fail "Could not publish the private database recovery backup."
        database_discard_backup_staging || true
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""

    CREATED_DATABASE_BACKUP_ID="$backup_id"
    info "Database recovery backup created: ${backup_id}"
}

database_close_validated_backup_dump() {
    local status=0
    if [[ -n "${DATABASE_ROLLBACK_VALIDATION_STAGING_DIR:-}" ]] \
        && ! database_discard_validation_staging; then
        status=1
    fi
    VALIDATED_DATABASE_BACKUP_DUMP_PATH=""
    VALIDATED_DATABASE_BACKUP_DUMP_IDENTITY=""
    VALIDATED_DATABASE_BACKUP_DUMP_METADATA=""
    return "$status"
}

database_snapshot_file_metadata() {
    local path="$1"
    case "$(uname -s 2>/dev/null || true)" in
        Linux)
            $SUDO /usr/bin/stat -Lc '%u:%g:%a:%h' "$path" 2>/dev/null
            ;;
        Darwin)
            $SUDO /usr/bin/stat -L -f '%u:%g:%Lp:%l' "$path" 2>/dev/null
            ;;
        *)
            return 1
            ;;
    esac
}

database_snapshot_file_identity() {
    local path="$1"
    case "$(uname -s 2>/dev/null || true)" in
        Linux)
            $SUDO /usr/bin/stat -Lc '%d:%i' "$path" 2>/dev/null
            ;;
        Darwin)
            $SUDO /usr/bin/stat -L -f '%d:%i' "$path" 2>/dev/null
            ;;
        *)
            return 1
            ;;
    esac
}

database_root_file_sha256() {
    local path="$1"
    local output checksum
    case "$(uname -s 2>/dev/null || true)" in
        Linux)
            output="$($SUDO /usr/bin/sha256sum "$path")" || return 1
            ;;
        Darwin)
            output="$($SUDO /usr/bin/shasum -a 256 "$path")" || return 1
            ;;
        *)
            return 1
            ;;
    esac
    checksum="${output%%[[:space:]]*}"
    [[ "$checksum" =~ ^[0-9a-f]{64}$ ]] || return 1
    printf '%s\n' "$checksum"
}

database_discard_validation_staging() {
    local staging_dir="${DATABASE_ROLLBACK_VALIDATION_STAGING_DIR:-}"
    [[ -n "$staging_dir" ]] || return 0
    if ! database_path_is_safe_direct_child \
        "/tmp" "$staging_dir" "llap-database-rollback."; then
        warn "Refusing to remove an unsafe rollback validation staging path."
        DATABASE_ROLLBACK_VALIDATION_STAGING_DIR=""
        return 1
    fi
    if $SUDO test -e "$staging_dir" || $SUDO test -L "$staging_dir"; then
        if ! installer_private_staging_is_safe \
            "$staging_dir" "directory" "700"; then
            warn "Refusing to remove rollback validation staging with unsafe ownership."
            DATABASE_ROLLBACK_VALIDATION_STAGING_DIR=""
            return 1
        fi
        if ! $SUDO rm -rf -- "$staging_dir"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_VALIDATION_STAGING_DIR=""
}

database_validated_dump_is_safe() {
    local staging_dir="${DATABASE_ROLLBACK_VALIDATION_STAGING_DIR:-}"
    local dump_path="${VALIDATED_DATABASE_BACKUP_DUMP_PATH:-}"
    [[ -n "$staging_dir" && -n "$dump_path" \
        && -n "${VALIDATED_DATABASE_BACKUP_DUMP_IDENTITY:-}" \
        && -n "${VALIDATED_DATABASE_BACKUP_DUMP_METADATA:-}" ]] || return 1
    database_path_is_safe_direct_child \
        "/tmp" "$staging_dir" "llap-database-rollback." || return 1
    database_path_is_strict_child "$staging_dir" "$dump_path" || return 1
    [[ "$(dirname -- "$dump_path")" == "$staging_dir" \
        && "$(basename -- "$dump_path")" == "database.dump" ]] || return 1
    installer_private_staging_is_safe \
        "$staging_dir" "directory" "700" || return 1
    $SUDO test -s "$dump_path" && ! $SUDO test -L "$dump_path" \
        && installer_path_has_single_link "$dump_path" || return 1
    [[ "$(database_snapshot_file_metadata "$dump_path")" \
        == "$VALIDATED_DATABASE_BACKUP_DUMP_METADATA" ]] || return 1
    [[ "$(database_snapshot_file_identity "$dump_path")" \
        == "$VALIDATED_DATABASE_BACKUP_DUMP_IDENTITY" ]]
}

# Validate a kind == "database" rollback artifact: a frozen PostgreSQL database
# rather than a dump file.
#
# All of it runs BEFORE the proxy is quiesced, so a bad artifact costs zero
# downtime. There is deliberately no checksum and no `pg_restore --list`
# equivalent: `pg_restore --list` proves only that a table of contents parses,
# it costs a full re-read of the archive, and there is no cheap byte-identity
# check for a live database — autovacuum wraparound processing touches
# datallowconn = false databases, so size or checksum equality would be
# brittle. The contract that IS enforced is stronger where it matters: the
# database exists, nothing has been able to write to it since it was frozen,
# and (after adoption, while the swap is still reversible by rename) its
# migration history equals the manifest's.
database_validate_database_rollback_artifact() {
    local backup_id="$1"
    local snapshot_manifest="$2"
    local requested_version="$3"
    local installed_version="$4"
    local manifest_values="" artifact_database="" catalog_state=""
    # shellcheck disable=SC2016  # jq variables are intentionally single-quoted.
    if ! manifest_values="$(
        set -o pipefail
        $SUDO cat "$snapshot_manifest" \
            | jq -er \
                --arg backup_id "$backup_id" \
                --arg requested "$requested_version" \
                --arg installed "$installed_version" \
                'if (.format_version == 2 and .kind == "database" and
                     .backup_id == $backup_id and
                     .source_version == $requested and
                     .target_version == $installed and
                     (.database | type == "string" and
                         test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                     (.artifact_database | type == "string" and
                         test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                     (.migration_version | type == "string" and
                         test("^[0-9]+$")))
                 then [.artifact_database, .migration_version, .database] | @tsv
                 else error("rollback manifest mismatch")
                 end' 2>> "$LOG_FILE"
    )"; then
        fail "Rollback artifact manifest does not match the requested recovery transition."
        return 1
    fi
    IFS=$'\t' read -r artifact_database \
        VALIDATED_DATABASE_BACKUP_MIGRATION \
        DATABASE_ROLLBACK_ACTIVE_DATABASE <<< "$manifest_values"
    if ! database_recovery_identifier_is_safe "$artifact_database" \
        || [[ ! "$VALIDATED_DATABASE_BACKUP_MIGRATION" =~ ^[0-9]+$ ]] \
        || ! database_recovery_identifier_is_safe \
            "$DATABASE_ROLLBACK_ACTIVE_DATABASE"; then
        fail "Rollback artifact manifest authority is malformed."
        return 1
    fi

    # Catalog probe. Exactly one row, and still closed to connections: an
    # artifact that has been reopened may have been written to, and nothing may
    # have written to it since it was frozen.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    catalog_state=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --no-align --tuples-only --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="catalog_database=${artifact_database}" \
        2>> "$LOG_FILE" <<'SQL'
SELECT count(*) || ':' || COALESCE(bool_and(datallowconn)::text, 'none')
FROM pg_database WHERE datname = :'catalog_database';
SQL
    ) || {
        fail "Could not probe the rollback artifact database in the catalog."
        return 1
    }
    catalog_state=$(printf '%s' "$catalog_state" | tr -d '[:space:]')
    if [[ "$catalog_state" != "1:false" ]]; then
        case "$catalog_state" in
            0:*|:*|"")
                fail "Rollback artifact database ${artifact_database} is absent; the artifact cannot be used." ;;
            1:true)
                fail "Rollback artifact database ${artifact_database} is open to connections and can no longer be trusted as frozen." ;;
            *)
                fail "Rollback artifact database ${artifact_database} is not a single frozen database (catalog reported '${catalog_state}')." ;;
        esac
        VALIDATED_DATABASE_BACKUP_MIGRATION=""
        DATABASE_ROLLBACK_ACTIVE_DATABASE=""
        return 1
    fi
    VALIDATED_DATABASE_BACKUP_ARTIFACT_DATABASE="$artifact_database"
    VALIDATED_DATABASE_BACKUP_KIND="database"
}

database_validate_rollback_backup() {
    local backup_id="$1"
    local requested_version="$2"
    local installed_version="$3"
    local backup_dir manifest dump expected_checksum="" actual_checksum=""
    local snapshot_dir="" suffix snapshot_manifest snapshot_dump
    local expected_uid expected_gid expected_metadata
    local manifest_identity="" dump_identity="" manifest_values=""
    local capture_error="" validation_error="" artifact_kind=""
    local -a archive_status=()

    if ! database_close_validated_backup_dump; then
        fail "A prior validated rollback snapshot could not be removed."
        return 1
    fi
    VALIDATED_DATABASE_BACKUP_KIND=""
    VALIDATED_DATABASE_BACKUP_ARTIFACT_DATABASE=""
    if ! database_backup_id_is_safe "$backup_id"; then
        fail "Rollback backup ID is invalid."
        return 1
    fi
    backup_dir="${METADATA_DIR}/database-rollback/${backup_id}"
    manifest="${backup_dir}/manifest.json"
    dump="${backup_dir}/database.dump"
    if ! $SUDO test -d "$backup_dir" || ! $SUDO test -s "$manifest"; then
        fail "Rollback backup not found or incomplete: ${backup_id}"
        return 1
    fi
    if $SUDO test -L "$backup_dir" || $SUDO test -L "$manifest"; then
        fail "Rollback backup contains a symbolic link and is rejected."
        return 1
    fi
    # Which artifact shape is this? format_version 1 (or no kind) is the
    # original dump artifact and keeps its entire validation and restore path,
    # so pre-existing pre-upgrade-* directories on operator hosts stay usable.
    # This probe only SELECTS a branch: each branch re-proves the shape from the
    # root-only snapshot with a predicate that pins format_version and kind, so
    # a manifest exchanged between the two reads fails closed either way.
    # shellcheck disable=SC2016  # jq programs are intentionally single-quoted.
    artifact_kind="$(
        set -o pipefail
        $SUDO cat "$manifest" 2>> "$LOG_FILE" \
            | jq -er 'if (.format_version == 2 and .kind == "database")
                      then "database"
                      elif (.format_version == 3 and .kind == "restic")
                      then "restic"
                      elif .format_version == 1 then "dump"
                      else error("unsupported rollback artifact kind") end' \
                2>> "$LOG_FILE"
    )" || {
        fail "Rollback backup manifest does not declare a supported artifact kind: ${backup_id}"
        return 1
    }
    # An in-place upgrade left no on-host artifact. Say so precisely, name the
    # snapshot, and refuse — rather than accepting the flag and then failing
    # somewhere less recoverable. Restoring a restic snapshot into production
    # is a separately approved procedure, not an installer flag.
    if [[ "$artifact_kind" == "restic" ]]; then
        local recorded_snapshot=""
        recorded_snapshot="$(
            $SUDO cat "$manifest" 2>> "$LOG_FILE" \
                | jq -r '.recovery_snapshot_id // ""' 2>> "$LOG_FILE"
        )" || recorded_snapshot=""
        fail "Rollback backup ${backup_id} records an in-place upgrade; there is no on-host artifact to restore."
        if [[ -n "$recorded_snapshot" ]]; then
            fail "  Its recovery point is restic snapshot ${recorded_snapshot}."
        else
            fail "  No recovery point was recorded for that upgrade."
        fi
        fail "  Restoring it is an operator procedure — see docs/runbooks/database-rollback.md."
        return 1
    fi
    if [[ "$artifact_kind" == "dump" ]] \
        && { ! $SUDO test -s "$dump" || $SUDO test -L "$dump"; }; then
        fail "Rollback backup not found or incomplete: ${backup_id}"
        return 1
    fi

    # Root snapshots both inputs from their first byte into a root-only 0700
    # directory. Every dump consumer is privileged and revalidates the captured
    # dev:inode, ownership, mode, and link count before opening it. No pathname
    # is ever made readable or writable to the invoking operator or its group.
    suffix="$(installer_private_staging_suffix)" || {
        fail "Rollback backup snapshot identity could not be generated."
        return 1
    }
    DATABASE_ROLLBACK_VALIDATION_STAGING_DIR="/tmp/llap-database-rollback.${suffix}"
    snapshot_dir="$DATABASE_ROLLBACK_VALIDATION_STAGING_DIR"
    if ! database_path_is_safe_direct_child \
        "/tmp" "$snapshot_dir" "llap-database-rollback." \
        || ! installer_create_private_staging_directory "$snapshot_dir"; then
        database_discard_validation_staging || true
        fail "Rollback backup snapshot could not be allocated."
        return 1
    fi
    snapshot_manifest="${snapshot_dir}/manifest.json"
    snapshot_dump="${snapshot_dir}/database.dump"
    expected_uid="$($SUDO /usr/bin/id -u)" \
        || capture_error="Rollback snapshot owner could not be resolved."
    expected_gid="$($SUDO /usr/bin/id -g)" \
        || capture_error="Rollback snapshot group could not be resolved."
    if [[ -z "$capture_error" ]] \
        && { [[ ! "$expected_uid" =~ ^[0-9]+$ ]] \
            || [[ ! "$expected_gid" =~ ^[0-9]+$ ]]; }; then
        capture_error="Rollback snapshot ownership is invalid."
    fi
    if [[ -z "$capture_error" ]] \
        && ! $SUDO install -m 0400 "$manifest" "$snapshot_manifest"; then
        capture_error="Rollback backup could not be captured."
    fi
    if [[ -z "$capture_error" && "$artifact_kind" == "dump" ]] \
        && ! $SUDO install -m 0400 "$dump" "$snapshot_dump"; then
        capture_error="Rollback backup could not be captured."
    fi
    if [[ -z "$capture_error" ]] \
        && { ! $SUDO chown "${expected_uid}:${expected_gid}" \
                "$snapshot_manifest" \
            || ! $SUDO chmod 0400 "$snapshot_manifest"; }; then
        capture_error="Rollback backup snapshot could not be protected."
    fi
    if [[ -z "$capture_error" && "$artifact_kind" == "dump" ]] \
        && { ! $SUDO chown "${expected_uid}:${expected_gid}" \
                "$snapshot_dump" \
            || ! $SUDO chmod 0400 "$snapshot_dump"; }; then
        capture_error="Rollback backup snapshot could not be protected."
    fi
    expected_metadata="${expected_uid}:${expected_gid}:400:1"
    if [[ -z "$capture_error" ]] \
        && { [[ "$(database_snapshot_file_metadata "$snapshot_manifest")" \
                != "$expected_metadata" ]] \
            || ! $SUDO test -s "$snapshot_manifest" \
            || $SUDO test -L "$snapshot_manifest"; }; then
        capture_error="Rollback backup snapshot ownership or type is unsafe."
    fi
    if [[ -z "$capture_error" && "$artifact_kind" == "dump" ]] \
        && { [[ "$(database_snapshot_file_metadata "$snapshot_dump")" \
                != "$expected_metadata" ]] \
            || ! $SUDO test -s "$snapshot_dump" \
            || $SUDO test -L "$snapshot_dump"; }; then
        capture_error="Rollback backup snapshot ownership or type is unsafe."
    fi
    if [[ -z "$capture_error" ]]; then
        manifest_identity="$(database_snapshot_file_identity "$snapshot_manifest")" \
            || capture_error="Rollback manifest identity could not be read."
    fi
    if [[ -z "$capture_error" && "$artifact_kind" == "dump" ]]; then
        dump_identity="$(database_snapshot_file_identity "$snapshot_dump")" \
            || capture_error="Rollback dump identity could not be read."
    fi
    if [[ -n "$capture_error" ]]; then
        database_discard_validation_staging || true
        fail "$capture_error"
        return 1
    fi

    if [[ "$(database_snapshot_file_metadata "$snapshot_manifest")" \
            != "$expected_metadata" \
        || "$(database_snapshot_file_identity "$snapshot_manifest")" \
            != "$manifest_identity" ]]; then
        validation_error="Rollback manifest identity changed before validation."
    fi
    # The frozen-database artifact carries no bytes of its own on this
    # filesystem, so there is nothing to checksum, copy or feed to pg_restore.
    if [[ -z "$validation_error" && "$artifact_kind" == "database" ]]; then
        if ! database_validate_database_rollback_artifact \
            "$backup_id" "$snapshot_manifest" \
            "$requested_version" "$installed_version"; then
            VALIDATED_DATABASE_BACKUP_MIGRATION=""
            DATABASE_ROLLBACK_ACTIVE_DATABASE=""
            VALIDATED_DATABASE_BACKUP_KIND=""
            VALIDATED_DATABASE_BACKUP_ARTIFACT_DATABASE=""
            database_discard_validation_staging || true
            return 1
        fi
        if ! database_discard_validation_staging; then
            fail "Rollback artifact manifest snapshot could not be removed."
            return 1
        fi
        info "Rollback artifact validated: ${backup_id} (frozen database ${VALIDATED_DATABASE_BACKUP_ARTIFACT_DATABASE})"
        return 0
    fi
    # shellcheck disable=SC2016  # jq variables are intentionally single-quoted.
    if [[ -z "$validation_error" ]] \
        && ! manifest_values="$(
            set -o pipefail
            $SUDO cat "$snapshot_manifest" \
                | jq -er \
                    --arg backup_id "$backup_id" \
                    --arg requested "$requested_version" \
                    --arg installed "$installed_version" \
                    'if (.format_version == 1 and .backup_id == $backup_id and
                         .source_version == $requested and
                         .target_version == $installed and
                         (.database | type == "string" and
                             test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")) and
                         (.migration_version | type == "string" and
                             test("^[0-9]+$")) and
                         .dump_file == "database.dump" and
                         (.sha256 | type == "string" and
                             test("^[0-9a-f]{64}$")))
                     then [.sha256, .migration_version, .database] | @tsv
                     else error("rollback manifest mismatch")
                     end' 2>> "$LOG_FILE"
        )"; then
        validation_error="Rollback backup manifest does not match the requested recovery transition."
    fi
    if [[ -z "$validation_error" ]]; then
        IFS=$'\t' read -r expected_checksum \
            VALIDATED_DATABASE_BACKUP_MIGRATION \
            DATABASE_ROLLBACK_ACTIVE_DATABASE <<< "$manifest_values"
        if [[ ! "$expected_checksum" =~ ^[0-9a-f]{64}$ \
            || ! "$VALIDATED_DATABASE_BACKUP_MIGRATION" =~ ^[0-9]+$ \
            || ! "$DATABASE_ROLLBACK_ACTIVE_DATABASE" =~ \
                ^[A-Za-z_][A-Za-z0-9_]{0,62}$ ]]; then
            validation_error="Rollback backup manifest authority is malformed."
        fi
    fi
    if [[ -z "$validation_error" ]] \
        && { [[ "$(database_snapshot_file_metadata "$snapshot_dump")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_identity "$snapshot_dump")" \
                != "$dump_identity" ]]; }; then
        validation_error="Rollback dump identity changed before checksum validation."
    fi
    if [[ -z "$validation_error" ]] \
        && ! actual_checksum="$(database_root_file_sha256 "$snapshot_dump")"; then
        validation_error="Rollback backup checksum could not be calculated."
    fi
    if [[ -z "$validation_error" \
        && "$actual_checksum" != "$expected_checksum" ]]; then
        validation_error="Rollback backup checksum mismatch; the active database was not changed."
    fi
    if [[ -z "$validation_error" ]] \
        && { [[ "$(database_snapshot_file_metadata "$snapshot_dump")" \
                != "$expected_metadata" ]] \
            || [[ "$(database_snapshot_file_identity "$snapshot_dump")" \
                != "$dump_identity" ]]; }; then
        validation_error="Rollback dump identity changed before archive validation."
    fi
    if [[ -z "$validation_error" ]]; then
        {
            $SUDO cat "$snapshot_dump" 2>> "$LOG_FILE" \
                | database_read_archive_then_drain \
                    installer_run_live_compose exec -T timescaledb \
                    sh -ceu 'exec pg_restore --list' >> "$LOG_FILE" 2>&1
            archive_status=("${PIPESTATUS[@]}")
        } || true
        if ! database_archive_feed_status_is_ok "${archive_status[0]:-1}" \
            || [[ "${archive_status[1]:-1}" != 0 ]]; then
            validation_error="Rollback backup archive validation failed; the active database was not changed."
        fi
    fi
    if [[ -n "$validation_error" ]]; then
        VALIDATED_DATABASE_BACKUP_MIGRATION=""
        DATABASE_ROLLBACK_ACTIVE_DATABASE=""
        database_discard_validation_staging || true
        fail "$validation_error"
        return 1
    fi

    VALIDATED_DATABASE_BACKUP_DUMP_PATH="$snapshot_dump"
    VALIDATED_DATABASE_BACKUP_DUMP_IDENTITY="$dump_identity"
    VALIDATED_DATABASE_BACKUP_DUMP_METADATA="$expected_metadata"
    VALIDATED_DATABASE_BACKUP_KIND="dump"
    info "Rollback backup validated: ${backup_id}"
}

database_swap_sql() {
    local active_database="$1"
    local replacement_database="$2"
    local safety_database="$3"
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="active_database=${active_database}" \
        --set="replacement_database=${replacement_database}" \
        --set="safety_database=${safety_database}" \
        >> "$LOG_FILE" 2>&1 <<'SQL'
\set ON_ERROR_STOP on
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname IN (:'active_database', :'replacement_database')
  AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I RENAME TO %I', :'active_database', :'safety_database') \gexec
SELECT format('ALTER DATABASE %I RENAME TO %I', :'replacement_database', :'active_database') \gexec
SQL
}

# Re-open the frozen safety database so a deferred read can connect.
database_allow_safety_database_connections() {
    local safety_database="$1"
    database_recovery_identifier_is_safe "$safety_database" || return 1
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="safety_database=${safety_database}" \
        >> "$LOG_FILE" 2>&1 <<'SQL'
\set ON_ERROR_STOP on
SELECT format('ALTER DATABASE %I WITH ALLOW_CONNECTIONS true', :'safety_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database') \gexec
SQL
}

# Open or close a database to new connections.
#
# `datallowconn = false` is what makes a rollback artifact frozen: it is both
# the reason CREATE DATABASE ... TEMPLATE can copy it and the reason TimescaleDB
# cannot restart a per-database background worker against it. The artifact must
# be closed at all times except for the single round trip that reads its
# migration version.
#
# `allow` is validated to be exactly true or false in the shell, so it is safe
# to interpolate as a literal; the identifier goes through %I regardless.
database_set_database_connections() {
    local database="$1"
    local allow="$2"
    database_recovery_identifier_is_safe "$database" || return 1
    [[ "$allow" == "true" || "$allow" == "false" ]] || return 1
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="connections_database=${database}" \
        --set="allow_connections=${allow}" \
        >> "$LOG_FILE" 2>&1 <<'SQL'
\set ON_ERROR_STOP on
SELECT format('ALTER DATABASE %I WITH ALLOW_CONNECTIONS %s',
              :'connections_database', :'allow_connections')
WHERE EXISTS (SELECT 1 FROM pg_database
              WHERE datname = :'connections_database') \gexec
SQL
}

# Echo pg_database_size() for a database, in bytes. Reads from `postgres`, so it
# works against a frozen artifact with datallowconn = false.
database_measure_database_size() {
    local database="$1"
    local size_bytes
    database_recovery_identifier_is_safe "$database" || return 1
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    size_bytes=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --no-align --tuples-only --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="target_database=${database}" \
        2>> "$LOG_FILE" <<'SQL'
SELECT COALESCE(pg_database_size(:'target_database'), 0)
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'target_database');
SQL
    ) || return 1
    size_bytes=$(printf '%s' "$size_bytes" | tr -d '[:space:]')
    [[ "$size_bytes" =~ ^[0-9]+$ ]] || return 1
    printf '%s\n' "$size_bytes"
}

# Echo `<free_bytes> <total_bytes> <wal_bytes> <reserve_bytes> <data_directory>`
# for the volume PostgreSQL's data directory lives on.
#
#   wal      = max(4 * max_wal_size, 1 GiB) — read from the server, not guessed.
#              A `CREATE DATABASE ... TEMPLATE` on PostgreSQL 15+ defaults to
#              STRATEGY = WAL_LOG, which WAL-logs the whole copy, and production
#              already logs "checkpoints are occurring too frequently".
#   reserve  = max(2 GiB, total/20) — the floor the installer will never
#              consume, so a fully successful upgrade still leaves headroom.
database_probe_volume_budget() {
    local data_directory df_output free_kb total_kb max_wal_bytes
    local free_bytes total_bytes wal_bytes reserve_bytes
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    data_directory=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --no-align --tuples-only --set=ON_ERROR_STOP=1 --command="SHOW data_directory"' \
        </dev/null 2>> "$LOG_FILE") || {
        fail "Could not locate the database data directory."
        return 1
    }
    data_directory=$(printf '%s' "$data_directory" | tr -d '\r' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
    if ! database_recovery_install_dir_is_safe "$data_directory"; then
        fail "Database data directory is not a safe absolute path."
        return 1
    fi

    # `df` runs in the container because the volume is only mounted there; the
    # output is parsed on the host so container output never becomes shell.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    df_output=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec df -Pk -- "$1"' sh "$data_directory" </dev/null 2>> "$LOG_FILE") || {
        fail "Could not read free space on the database volume."
        return 1
    }
    free_kb=$(printf '%s\n' "$df_output" | awk 'NR == 2 { print $4 }' | tr -d '[:space:]')
    total_kb=$(printf '%s\n' "$df_output" | awk 'NR == 2 { print $2 }' | tr -d '[:space:]')
    if [[ ! "$free_kb" =~ ^[0-9]+$ || ! "$total_kb" =~ ^[0-9]+$ ]]; then
        fail "Free and total space on the database volume could not be parsed."
        return 1
    fi

    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    max_wal_bytes=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --no-align --tuples-only --set=ON_ERROR_STOP=1 --command="SELECT pg_size_bytes(current_setting('"'"'max_wal_size'"'"'))"' \
        </dev/null 2>> "$LOG_FILE") || max_wal_bytes=""
    max_wal_bytes=$(printf '%s' "$max_wal_bytes" | tr -d '[:space:]')
    # An unreadable max_wal_size must not silently shrink the budget.
    [[ "$max_wal_bytes" =~ ^[0-9]+$ ]] || max_wal_bytes=$(( 1024 * 1024 * 1024 ))

    free_bytes=$(( free_kb * 1024 ))
    total_bytes=$(( total_kb * 1024 ))
    wal_bytes=$(( max_wal_bytes * 4 ))
    (( wal_bytes >= 1024 * 1024 * 1024 )) || wal_bytes=$(( 1024 * 1024 * 1024 ))
    reserve_bytes=$(( total_bytes / 20 ))
    (( reserve_bytes >= 2 * 1024 * 1024 * 1024 )) \
        || reserve_bytes=$(( 2 * 1024 * 1024 * 1024 ))

    printf '%s %s %s %s %s\n' "$free_bytes" "$total_bytes" "$wal_bytes" \
        "$reserve_bytes" "$data_directory"
}

# The disk precondition for an in-place forward upgrade.
#
# It runs BEFORE database_quiesce_proxy, so a refusal costs no downtime at all.
#
# What it budgets is deliberately NOT a function of database size. The upgrade
# no longer copies the database: sqlx applies migrations to the live database,
# which is what migrations are for (#1757 Direction item 1). The previous gate
# required `size * 1.2` for a physical clone and the run then took a second,
# entirely unbudgeted O(size) write for the durable dump — 37 GB of database
# meant ~44 GB required against 17 GB free, so production could not upgrade at
# all (#1762). With the copy gone there is nothing left that scales with size:
#
#   required = wal + churn + reserve
#     wal     max(4 * max_wal_size, 1 GiB), read from the server
#     churn   a fixed allowance for what a migration itself writes
#     reserve max(2 GiB, volume total / 20), never consumed by the installer
#
# `churn` is an engineering constant, not a measurement: the installer cannot
# know what the TARGET release's migrations will do before running them. It is
# sized for the metadata-only DDL this project's migrations are required to be
# (ALTER ... SET DEFAULT, policy changes, catalog updates). A migration that
# rewrites or recompresses table data is O(size) again and is outside this
# budget by construction — such a migration must be sized separately and must
# not be shipped as an inline upgrade step. See
# docs/runbooks/database-rollback.md.
DATABASE_IN_PLACE_MIGRATION_CHURN_BYTES=$(( 2 * 1024 * 1024 * 1024 ))

database_require_in_place_upgrade_headroom() {
    local budget free_bytes total_bytes wal_bytes reserve_bytes data_directory
    local churn_bytes required_bytes releasable_bytes=0
    local backup_id target_version artifact_database artifact_size
    local installed_version=""
    local -a releasable_ids=()

    # Explicit consent, honoured before anything is measured, so its space is
    # counted by the very first measurement.
    if [[ -n "${OPT_RELEASE_ROLLBACK_ARTIFACT:-}" ]] \
        && ! database_release_requested_rollback_artifact; then
        return 1
    fi

    if ! budget=$(database_probe_volume_budget); then
        fail "Could not budget the database volume before the in-place upgrade."
        return 1
    fi
    read -r free_bytes total_bytes wal_bytes reserve_bytes data_directory \
        <<< "$budget"
    churn_bytes="$DATABASE_IN_PLACE_MIGRATION_CHURN_BYTES"
    required_bytes=$(( wal_bytes + churn_bytes + reserve_bytes ))

    # Artifacts that can never validate again are free to reclaim. This is now
    # housekeeping rather than a precondition — the requirement above is small
    # and fixed — but a nearly-full volume is still worth reclaiming before a
    # migration runs.
    if (( free_bytes < required_bytes )); then
        database_release_superseded_rollback_artifacts \
            || warn "Some superseded rollback artifacts could not be released."
        if ! budget=$(database_probe_volume_budget); then
            fail "Could not re-measure the database volume after releasing superseded rollback artifacts."
            return 1
        fi
        read -r free_bytes total_bytes wal_bytes reserve_bytes \
            data_directory <<< "$budget"
    fi

    if (( free_bytes >= required_bytes )); then
        info "Database volume headroom verified for the in-place upgrade: $(( free_bytes / 1024 / 1024 )) MiB free, $(( required_bytes / 1024 / 1024 )) MiB required"
        return 0
    fi

    installed_version="$(existing_install_version 2>/dev/null || true)"
    if is_stable_semver "$installed_version"; then
        while IFS=$'\t' read -r backup_id target_version artifact_database \
            artifact_size; do
            [[ -n "$backup_id" ]] || continue
            [[ "$target_version" == "$installed_version" ]] || continue
            [[ "$artifact_size" =~ ^[0-9]+$ ]] || artifact_size=0
            releasable_ids+=("$backup_id")
            releasable_bytes=$(( releasable_bytes + artifact_size ))
        done < <(database_enumerate_rollback_artifacts)
    fi

    fail "Insufficient database volume headroom for the in-place upgrade."
    fail "  Volume: ${data_directory} ($(( total_bytes / 1024 / 1024 )) MiB total)"
    fail "  WAL allowance: $(( wal_bytes / 1024 / 1024 )) MiB"
    fail "  Migration churn allowance: $(( churn_bytes / 1024 / 1024 )) MiB"
    fail "  Reserve kept free: $(( reserve_bytes / 1024 / 1024 )) MiB"
    fail "  Required: $(( required_bytes / 1024 / 1024 )) MiB"
    fail "  Available: $(( free_bytes / 1024 / 1024 )) MiB"
    fail "  Short by: $(( (required_bytes - free_bytes) / 1024 / 1024 )) MiB"
    if (( ${#releasable_ids[@]} > 0 )); then
        fail "  Releasable rollback artifacts: $(( releasable_bytes / 1024 / 1024 )) MiB"
        for backup_id in "${releasable_ids[@]}"; do
            fail "    --release-rollback-artifact=${backup_id}"
        done
        fail "Releasing one gives up the ability to roll this installation back to that artifact's source version."
    fi
    fail "The proxy was not stopped."
    return 1
}

# The rollback precondition. Adopting a frozen artifact renames two databases
# and copies nothing, so unlike the upgrade it does NOT need room for another
# copy — deliberately, because a tight disk is exactly when a rollback is
# needed. It still refuses to start on a volume with no working room at all.
database_require_rollback_headroom() {
    local budget free_bytes total_bytes wal_bytes reserve_bytes data_directory
    local required_bytes
    if ! budget=$(database_probe_volume_budget); then
        fail "Could not budget the database volume before the rollback."
        return 1
    fi
    read -r free_bytes total_bytes wal_bytes reserve_bytes data_directory \
        <<< "$budget"
    required_bytes=$(( wal_bytes + reserve_bytes ))
    if (( free_bytes < required_bytes )); then
        fail "Insufficient database volume headroom for the rollback."
        fail "  Volume: ${data_directory} ($(( total_bytes / 1024 / 1024 )) MiB total)"
        fail "  WAL allowance: $(( wal_bytes / 1024 / 1024 )) MiB"
        fail "  Reserve kept free: $(( reserve_bytes / 1024 / 1024 )) MiB"
        fail "  Required: $(( required_bytes / 1024 / 1024 )) MiB"
        fail "  Available: $(( free_bytes / 1024 / 1024 )) MiB"
        fail "The proxy was not stopped; free space on the database volume and retry."
        return 1
    fi
    info "Database volume headroom verified for the rollback: $(( free_bytes / 1024 / 1024 )) MiB free, $(( required_bytes / 1024 / 1024 )) MiB required"
}

# Release the artifact the operator named with --release-rollback-artifact.
#
# This is destructive and irreversible, so it states exactly what it is about to
# destroy before it does it, and it refuses an ID that does not resolve to a
# published artifact rather than treating an absent one as "already released".
database_release_requested_rollback_artifact() {
    local requested="${OPT_RELEASE_ROLLBACK_ARTIFACT:-}"
    local backup_id target_version artifact_database artifact_size
    local matched="false"
    [[ -n "$requested" ]] || return 0
    if ! database_backup_id_is_safe "$requested"; then
        fail "--release-rollback-artifact must be an installer-issued backup ID, not a path."
        return 1
    fi
    while IFS=$'\t' read -r backup_id target_version artifact_database \
        artifact_size; do
        [[ "$backup_id" == "$requested" ]] || continue
        matched="true"
        [[ "$artifact_size" =~ ^[0-9]+$ ]] || artifact_size=0
        warn "Releasing rollback artifact ${backup_id} at operator request."
        warn "  Frozen database to drop: ${artifact_database:-<none; dump artifact>}"
        warn "  Reclaims approximately: $(( artifact_size / 1024 / 1024 )) MiB"
        warn "  This permanently gives up the ability to roll this installation back"
        warn "  to the source version recorded in ${backup_id}."
        if ! database_release_rollback_artifact \
            "$backup_id" "$artifact_database"; then
            fail "Could not release the requested rollback artifact ${backup_id}."
            return 1
        fi
    done < <(database_enumerate_rollback_artifacts)
    if [[ "$matched" != "true" ]]; then
        fail "--release-rollback-artifact=${requested} does not name a published rollback artifact."
        fail "If it has already been released, re-run without the flag."
        return 1
    fi
}

database_drop_replacement_database() {
    local replacement_database="${DATABASE_ROLLBACK_REPLACEMENT_DATABASE:-}"
    [[ -n "$replacement_database" ]] || return 0
    if ! database_recovery_identifier_is_safe "$replacement_database"; then
        warn "Refusing to drop an unsafe rollback replacement database identifier."
        return 1
    fi
    # THE replacement database is not always disposable.
    #
    # On the adopt path the "replacement" IS the durable rollback artifact — a
    # frozen database this installer did not create and cannot recreate. It is
    # reached here through database_recover_interrupted_rollback, i.e. on a
    # FAILED rollback, which is exactly when the artifact must survive. Dropping
    # it would mean a failed rollback destroys the only rollback path. Restore
    # it to the frozen state it was found in instead, and never dropdb it.
    if [[ "${DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT:-false}" \
        == "true" ]]; then
        if ! database_set_database_connections "$replacement_database" "false"; then
            warn "Could not re-freeze the adopted rollback artifact ${replacement_database}; it is retained but open to connections."
            return 1
        fi
        DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="false"
        info "Adopted rollback artifact re-frozen and retained: ${replacement_database}"
        return 0
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec dropdb --if-exists --force --username="$POSTGRES_USER" "$1"' \
        sh "$replacement_database" >> "$LOG_FILE" 2>&1; then
        warn "Could not remove the installer-managed rollback replacement database."
        return 1
    fi
    info "Rollback replacement database removed"
}

database_run_timescaledb_restore_lifecycle() {
    local database="$1"
    local lifecycle_stage="$2"
    local statement
    database_recovery_identifier_is_safe "$database" || return 1
    case "$lifecycle_stage" in
        create-extension)
            statement='CREATE EXTENSION IF NOT EXISTS timescaledb;'
            ;;
        pre-restore)
            statement='SELECT timescaledb_pre_restore();'
            ;;
        post-restore)
            statement='SELECT timescaledb_post_restore();'
            ;;
        *)
            return 1
            ;;
    esac
    # The database identifier is a validated positional argument, never SQL.
    # POSTGRES_USER expands only inside the configured database container.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname="$1" --set=ON_ERROR_STOP=1 --command="$2"' \
        sh "$database" "$statement" >> "$LOG_FILE" 2>&1
}

database_stage_validated_backup_for_swap() {
    local operation_label="$1"
    local replacement_prefix="$2"
    local safety_prefix="$3"
    local timestamp restored_migration
    local -a restore_status=()

    if ! database_validated_dump_is_safe; then
        fail "${operation_label} validated root-only dump snapshot is absent or changed."
        database_close_validated_backup_dump || true
        database_abort_rollback || true
        return 1
    fi
    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE="${replacement_prefix}_${timestamp}_$$"
    DATABASE_ROLLBACK_SAFETY_DATABASE="${safety_prefix}_${timestamp}_$$"
    # This replacement is a database this installer just created from a dump, so
    # it is disposable. Say so explicitly rather than inheriting whatever a
    # previous adoption left behind.
    DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="false"
    if ! database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" \
        || ! database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE"; then
        fail "${operation_label} database staging identity is unsafe."
        database_abort_rollback || true
        return 1
    fi
    if ! database_write_recovery_journal "staging"; then
        fail "Could not persist ${operation_label} database staging identity."
        database_abort_rollback || true
        return 1
    fi

    # Restore into an isolated database. The active database remains unchanged
    # until the dump and its migration identity have both been verified.
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! installer_run_live_compose exec -T timescaledb \
        sh -ceu 'dropdb --if-exists --force --username="$POSTGRES_USER" "$1"; createdb --username="$POSTGRES_USER" --owner="$POSTGRES_USER" "$1"' \
        sh "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" >> "$LOG_FILE" 2>&1; then
        fail "Could not create the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "create-extension"; then
        fail "Could not enable TimescaleDB in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "pre-restore"; then
        fail "Could not enter TimescaleDB pre-restore mode in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi

    if ! database_validated_dump_is_safe; then
        database_close_validated_backup_dump || true
        fail "${operation_label} validated dump changed before isolated restore."
        database_abort_rollback || true
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    {
        $SUDO cat "$VALIDATED_DATABASE_BACKUP_DUMP_PATH" 2>> "$LOG_FILE" \
            | database_read_archive_then_drain \
                installer_run_live_compose exec -T timescaledb \
                sh -ceu 'exec pg_restore --exit-on-error --single-transaction --no-owner --no-acl --username="$POSTGRES_USER" --dbname="$1"' \
                sh "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" \
                >> "$LOG_FILE" 2>&1
        restore_status=("${PIPESTATUS[@]}")
    } || true
    # A pg_restore that stops reading — because it finished, or because
    # --exit-on-error aborted it — SIGPIPEs the feeder. Its own status below
    # is what decides success, so the feeder's 141 is never load-bearing.
    if ! database_archive_feed_status_is_ok "${restore_status[0]:-1}" \
        || [[ "${restore_status[1]:-1}" != 0 ]]; then
        database_close_validated_backup_dump || true
        fail "${operation_label} restore failed in the isolated staging database (feeder=${restore_status[0]:-unset} reader=${restore_status[1]:-unset}); the active database was not changed."
        database_abort_rollback || true
        return 1
    fi
    if ! database_close_validated_backup_dump; then
        fail "${operation_label} validated dump snapshot could not be removed."
        database_abort_rollback || true
        return 1
    fi
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "post-restore"; then
        fail "Could not leave TimescaleDB restore mode in the isolated ${operation_label} staging database."
        database_abort_rollback || true
        return 1
    fi
    if ! restored_migration=$(database_query_migration_version "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE") \
        || [[ "$restored_migration" != "$VALIDATED_DATABASE_BACKUP_MIGRATION" ]]; then
        fail "${operation_label} staging database migration history does not match its immutable manifest."
        database_abort_rollback || true
        return 1
    fi

    if ! database_remove_quiesced_proxy_container; then
        database_abort_rollback || true
        return 1
    fi

    if ! database_write_recovery_journal "swap-active"; then
        fail "Could not persist ${operation_label} database swap identity before mutation."
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="true"
    if ! database_swap_sql "$DATABASE_ROLLBACK_ACTIVE_DATABASE" \
        "$DATABASE_ROLLBACK_REPLACEMENT_DATABASE" "$DATABASE_ROLLBACK_SAFETY_DATABASE"; then
        fail "${operation_label} database-name swap failed; attempting automatic recovery."
        database_recover_interrupted_rollback || true
        return 1
    fi
    info "${operation_label} database restored and verified at migration ${restored_migration}"
}

# Adopt a validated frozen artifact as the active database.
#
# This is the rename-only counterpart of database_stage_validated_backup_for_swap
# and it copies nothing: the artifact is renamed into place, and the database
# being rolled back FROM is renamed aside and frozen, which makes it a zero-copy
# rollback artifact in its own right and the swap reversible by rename. That is
# why there is no pre-rollback pg_dump on this path — a rollback is the
# emergency path and must work when the disk is tight, which is exactly when a
# full extra copy is unaffordable.
database_adopt_frozen_artifact_for_swap() {
    local operation_label="$1"
    local safety_prefix="$2"
    local artifact_database="${VALIDATED_DATABASE_BACKUP_ARTIFACT_DATABASE:-}"
    local timestamp adopted_migration

    if ! database_recovery_identifier_is_safe "$artifact_database"; then
        fail "${operation_label} validated rollback artifact identity is absent or unsafe."
        database_abort_rollback || true
        return 1
    fi
    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    # The artifact IS the replacement. Recording it under its own name is what
    # lets database_recover_interrupted_rollback rename it back, and the adopted
    # flag is what stops database_drop_replacement_database destroying it.
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE="$artifact_database"
    DATABASE_ROLLBACK_SAFETY_DATABASE="${safety_prefix}_${timestamp}_$$"
    DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="true"
    if ! database_recovery_identifier_is_safe "$DATABASE_ROLLBACK_SAFETY_DATABASE"; then
        fail "${operation_label} database staging identity is unsafe."
        database_abort_rollback || true
        return 1
    fi
    if ! database_write_recovery_journal "staging"; then
        fail "Could not persist ${operation_label} database staging identity."
        database_abort_rollback || true
        return 1
    fi
    if ! database_remove_quiesced_proxy_container; then
        database_abort_rollback || true
        return 1
    fi
    if ! database_write_recovery_journal "swap-active"; then
        fail "Could not persist ${operation_label} database swap identity before mutation."
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="true"
    if ! database_adopt_sql "$DATABASE_ROLLBACK_ACTIVE_DATABASE" \
        "$DATABASE_ROLLBACK_SAFETY_DATABASE" "$artifact_database"; then
        fail "${operation_label} database adoption failed; attempting automatic recovery."
        database_recover_interrupted_rollback || true
        return 1
    fi
    # Unconditionally. A frozen artifact may carry timescaledb.restoring = on
    # from whatever put it there, and a database left in restoring mode runs no
    # background workers at all — it would come back as the live database with
    # retention, compression and every other policy silently stopped.
    if ! database_run_timescaledb_restore_lifecycle \
        "$DATABASE_ROLLBACK_ACTIVE_DATABASE" "post-restore"; then
        fail "Could not leave TimescaleDB restore mode on the adopted ${operation_label} database."
        database_recover_interrupted_rollback || true
        return 1
    fi
    if ! adopted_migration=$(database_query_migration_version \
            "$DATABASE_ROLLBACK_ACTIVE_DATABASE") \
        || [[ "$adopted_migration" != "$VALIDATED_DATABASE_BACKUP_MIGRATION" ]]; then
        fail "${operation_label} adopted database migration history does not match its immutable manifest."
        database_recover_interrupted_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_REPLACEMENT_IS_ADOPTED_ARTIFACT="false"
    info "${operation_label} database adopted and verified at migration ${adopted_migration}"
}

# The rename-only adoption swap.
#
# The database being rolled back FROM is renamed aside and CLOSED before the
# artifact is opened, so at no point are two databases carrying the same
# identity both connectable.
database_adopt_sql() {
    local active_database="$1"
    local safety_database="$2"
    local artifact_database="$3"
    database_recovery_identifier_is_safe "$active_database" || return 1
    database_recovery_identifier_is_safe "$safety_database" || return 1
    database_recovery_identifier_is_safe "$artifact_database" || return 1
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="active_database=${active_database}" \
        --set="safety_database=${safety_database}" \
        --set="artifact_database=${artifact_database}" \
        >> "$LOG_FILE" 2>&1 <<'SQL'
\set ON_ERROR_STOP on
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname IN (:'active_database', :'artifact_database')
  AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I RENAME TO %I', :'active_database', :'safety_database') \gexec
SELECT format('ALTER DATABASE %I WITH ALLOW_CONNECTIONS false', :'safety_database') \gexec
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname = :'safety_database' AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I WITH ALLOW_CONNECTIONS true', :'artifact_database') \gexec
SELECT format('ALTER DATABASE %I RENAME TO %I', :'artifact_database', :'active_database') \gexec
SQL
}

database_restore_version_backup() {
    local installed_version="$1"
    local requested_version="$2"
    local backup_id="$3"

    if ! database_validate_rollback_backup "$backup_id" "$requested_version" "$installed_version"; then
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_VERSION="$installed_version"
    if [[ "${VALIDATED_DATABASE_BACKUP_KIND:-}" == "database" ]]; then
        if ! database_require_rollback_headroom; then
            database_abort_rollback || true
            return 1
        fi
        if ! database_quiesce_proxy; then
            database_abort_rollback || true
            return 1
        fi
        database_adopt_frozen_artifact_for_swap "Rollback" "llap_pre_rollback"
        return $?
    fi
    database_create_version_backup "$installed_version" "$requested_version" "pre-rollback" \
        || return 1
    database_stage_validated_backup_for_swap \
        "Rollback" "llap_restore" "llap_pre_rollback"
}

# Forward upgrades apply migrations IN PLACE (#1757 Direction item 1).
#
# The previous design rebuilt the database to upgrade it: first a logical
# dump + restore (a ~35-minute outage on 11 GB), then a physical
# `CREATE DATABASE ... TEMPLATE` clone (no outage, but still a full second
# copy). Both made every upgrade cost O(database size) in disk, and the clone
# left a 1.2x free-space requirement that production could no longer meet:
# 37 GB of database against 17 GB free (#1762).
#
# Migrations exist precisely to evolve a database in place. sqlx applies them
# to the live database, so the upgrade writes only what the migrations
# themselves write. Disk stops being a function of database size, and the
# proxy-stopped window collapses to the duration of the migration.
#
# WHAT THIS GIVES UP, EXPLICITLY. The clone existed because sqlx refuses to
# start an older binary against a database carrying migrations it does not
# know, so the pre-upgrade state had to survive untouched. Migrating in place
# destroys that state by construction: after this runs there is no on-host
# copy of the source schema, and rolling back means restoring the recorded
# recovery point (the restic snapshot resolved below) — an operator procedure
# measured in tens of minutes, not a rename. That trade is the point of #1757
# and it is documented in docs/runbooks/database-rollback.md; it is announced
# to the operator before the proxy is stopped, not discovered afterwards.
database_prepare_forward_upgrade() {
    local source_version="$1"
    local target_version="$2"
    local database source_migration

    if ! is_stable_semver "$source_version" \
        || ! is_stable_semver "$target_version"; then
        database_abort_rollback || true
        return 1
    fi
    if ! database=$(database_install_identifier); then
        database_abort_rollback || true
        return 1
    fi

    # Before the proxy stops: a headroom failure must cost zero downtime.
    #
    # It must still restore the source deploy tree. By the time this runs,
    # run_deploy has already executed deploy_extract_files, deploy_upgrade_env,
    # deploy_write_compose_command and deploy_pull_images, and journalled
    # "deploy-mutating" — so docker-compose.yml, .env and compose-command.sh
    # already point at the TARGET release while the OLD stack is still running.
    # The systemd unit is `ExecStart=${INSTALL_DIR}/compose-command.sh up -d`,
    # so a reboot or `systemctl restart llm-api-proxy` in that window would
    # start the NEW binary and migrate the database outside this function's
    # control. Restoring the source tree on refusal closes that window.
    if ! database_require_in_place_upgrade_headroom; then
        database_abort_rollback || true
        return 1
    fi

    # Resolve the recovery point BEFORE anything is mutated, so what it names
    # is unambiguously the pre-upgrade state.
    #
    # Refuses when NO recovery point exists at all. That is not a health gate:
    # snapshot AGE and backup-agent health never block an upgrade, because a
    # stale snapshot is a scheduling fact the installer cannot fix at 03:00.
    # Absence is different in kind. Once the migration runs in place there is no
    # second copy to fall back to, so a missing snapshot means an irreversible
    # change with no recovery path — and `AGENTS.md` requires a tested recovery
    # path for a destructive action. Proceeding on a warning here is exactly the
    # #1758 failure class: believing a recovery point exists because a warning
    # scrolled past.
    database_resolve_upgrade_recovery_point
    if [[ -z "$DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID" \
        && "${DATABASE_ROLLBACK_RECOVERY_EXPECTED:-false}" == "true" \
        && "${DATABASE_ROLLBACK_RECOVERY_REPOSITORY_READ:-false}" == "true" ]]; then
        if [[ "${OPT_ACCEPT_NO_RECOVERY_POINT:-false}" != "true" ]]; then
            fail "No recovery point exists for this in-place upgrade."
            fail "  Migrating in place cannot be reversed by the installer, and no"
            fail "  PostgreSQL snapshot was found in the backup repository to restore from."
            fail "  Take a backup first, then re-run this installer; or pass"
            fail "  --accept-no-recovery-point to upgrade with no way back."
            database_abort_rollback || true
            return 1
        fi
        warn "Proceeding with NO recovery point: --accept-no-recovery-point was given."
    fi

    DATABASE_ROLLBACK_SOURCE_VERSION="$source_version"
    # Announce the irreversibility before taking it, not after.
    step "  Applying ${target_version} migrations in place to ${database}..."
    warn "This upgrade migrates the live database in place and cannot be reversed by the installer."
    if [[ -n "$DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID" ]]; then
        warn "  Recovery point: restic snapshot ${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID} (${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME})"
    else
        warn "  Recovery point: NONE could be resolved from the backup repository."
    fi
    warn "  Restoring it is an operator procedure — see docs/runbooks/database-rollback.md."

    if ! database_quiesce_proxy; then
        database_abort_rollback || true
        return 1
    fi
    if ! source_migration=$(database_query_migration_version "$database"); then
        fail "Could not read the current migration version before the in-place upgrade."
        database_abort_rollback || true
        return 1
    fi
    DATABASE_ROLLBACK_SOURCE_MIGRATION="$source_migration"

    # The durable no-return boundary. Everything before it is reversible by
    # restoring the source deploy tree and restarting the source binary against
    # an untouched database; everything after it is not, because the target
    # binary is about to migrate that database. There is deliberately no
    # safety or replacement database: nothing is being copied or swapped.
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    if ! database_write_recovery_journal "target-migrating-in-place"; then
        fail "Could not persist the in-place upgrade boundary before mutation."
        database_abort_rollback || true
        return 1
    fi
    if ! database_remove_quiesced_proxy_container; then
        database_abort_rollback || true
        return 1
    fi
    DATABASE_FORWARD_UPGRADE_ACTIVE="true"
    info "In-place upgrade authorized from migration ${source_migration}; the target binary applies its own migrations"
}

# Resolve the recovery point for an in-place upgrade: the newest PostgreSQL
# snapshot in the restic repository.
#
# Deliberately best-effort. It reads through the backup container that already
# holds RESTIC_REPOSITORY and RESTIC_PASSWORD — the same `compose exec` channel
# the installer already uses for the database — so it needs no new credentials
# and no Consul client. It NEVER refuses the upgrade: gating an upgrade on the
# backup agent responding would couple the installer's critical path to a
# component whose health reporting is separately tracked (#1758), and a
# not-yet-taken snapshot is a scheduling fact for the deploy plan to handle,
# not something the installer can fix at 03:00.
#
# The timeout runs INSIDE the container: an unreachable object store must cost
# seconds, not a stalled upgrade.
database_resolve_upgrade_recovery_point() {
    local snapshot_output="" snapshot_id="" snapshot_time=""
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID=""
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME=""
    # Distinguishes "the operator opted out of backups" from "backups are on and
    # the snapshot is missing". Only the second is a broken expectation the
    # installer should refuse on; refusing the first would permanently block
    # upgrades for a deliberately backup-less install.
    DATABASE_ROLLBACK_RECOVERY_EXPECTED="false"
    DATABASE_ROLLBACK_RECOVERY_REPOSITORY_READ="false"
    if [[ "${OPT_BACKUP:-false}" != "true" ]]; then
        warn "Backups are disabled, so this in-place upgrade has no recorded recovery point."
        return 0
    fi
    DATABASE_ROLLBACK_RECOVERY_EXPECTED="true"
    # shellcheck disable=SC2016  # Expanded by sh inside the backup container.
    if ! snapshot_output=$(installer_run_live_compose exec -T backup \
        sh -ceu 'exec timeout 60 restic snapshots --json --latest 1 --tag postgres' \
        </dev/null 2>> "$LOG_FILE"); then
        warn "Could not read the restic repository; this in-place upgrade has no recorded recovery point."
        return 0
    fi
    # An unreadable repository is NOT proof that no snapshot exists, so it must
    # not arm the refusal — only a repository that answered, and answered
    # "none", proves absence. Anything else warns and proceeds, which keeps a
    # transient object-store outage from blocking an upgrade.
    if ! printf '%s' "$snapshot_output" | jq -e 'type == "array"' >/dev/null 2>> "$LOG_FILE"; then
        warn "The restic repository returned an unreadable snapshot listing; this in-place upgrade has no recorded recovery point."
        return 0
    fi
    DATABASE_ROLLBACK_RECOVERY_REPOSITORY_READ="true"
    if ! snapshot_output=$(
        printf '%s' "$snapshot_output" \
            | jq -er 'if (type == "array" and length > 0) then
                          (.[0] | [(.short_id // .id), .time] | @tsv)
                      else error("no snapshot") end' 2>> "$LOG_FILE"
    ); then
        warn "The restic repository reported no PostgreSQL snapshot; this in-place upgrade has no recorded recovery point."
        return 0
    fi
    IFS=$'\t' read -r snapshot_id snapshot_time <<< "$snapshot_output"
    if [[ ! "$snapshot_id" =~ ^[0-9a-f]{8,64}$ ]] \
        || [[ ! "$snapshot_time" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+ ]]; then
        warn "The restic repository returned an unusable snapshot identity; this in-place upgrade has no recorded recovery point."
        return 0
    fi
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID="$snapshot_id"
    DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME="$snapshot_time"
    info "Recovery point for this upgrade: restic snapshot ${snapshot_id} taken ${snapshot_time}"
}

database_recover_interrupted_rollback() {
    [[ "${DATABASE_ROLLBACK_SWAP_ACTIVE:-false}" == "true" ]] || return 0
    local failed_database
    failed_database="${DATABASE_ROLLBACK_REPLACEMENT_DATABASE:-llap_failed_rollback_$$}"
    installer_run_live_compose stop proxy >> "$LOG_FILE" 2>&1 || true
    DATABASE_ROLLBACK_PROXY_STOPPED="true"

    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="active_database=${DATABASE_ROLLBACK_ACTIVE_DATABASE}" \
        --set="failed_database=${failed_database}" \
        --set="safety_database=${DATABASE_ROLLBACK_SAFETY_DATABASE}" \
        >> "$LOG_FILE" 2>&1 <<'SQL'
\set ON_ERROR_STOP on
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname = :'active_database' AND pid <> pg_backend_pid();
SELECT format('ALTER DATABASE %I RENAME TO %I', :'active_database', :'failed_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database')
  AND EXISTS (SELECT 1 FROM pg_database WHERE datname = :'active_database')
  AND NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'failed_database') \gexec
SELECT format('ALTER DATABASE %I WITH ALLOW_CONNECTIONS true', :'safety_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database') \gexec
SELECT format('ALTER DATABASE %I RENAME TO %I', :'safety_database', :'active_database')
WHERE EXISTS (SELECT 1 FROM pg_database WHERE datname = :'safety_database')
  AND NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'active_database') \gexec
SQL
    then
        warn "Automatic interrupted-rollback database recovery failed; preserved backups require operator escalation."
        return 1
    fi
    if ! database_drop_replacement_database; then
        return 1
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
    DATABASE_FORWARD_UPGRADE_ACTIVE="false"
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]] \
        && ! database_write_recovery_journal "deploy-mutating"; then
        warn "Database swap was reversed, but durable source-state recovery could not be updated."
        return 1
    fi
    info "Interrupted rollback database swap was reversed"
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        database_restore_source_deploy_state
    else
        database_resume_proxy
    fi
}

# Drop an installer-managed rollback artifact database. `--if-exists` makes
# process-loss recovery idempotent when PostgreSQL completed the drop before
# the installer recorded its local result.
database_drop_rollback_artifact_database() {
    local artifact_database="$1"
    [[ -n "$artifact_database" ]] || return 0
    if ! database_recovery_identifier_is_safe "$artifact_database"; then
        warn "Refusing to drop an unsafe rollback artifact database identifier."
        return 1
    fi
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    if ! installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec dropdb --if-exists --force --username="$POSTGRES_USER" "$1"' \
        sh "$artifact_database" >> "$LOG_FILE" 2>&1; then
        warn "Could not remove the rollback artifact database ${artifact_database}."
        return 1
    fi
}

# Remove a published rollback artifact: its frozen database, then its manifest
# directory. The directory goes last so a process loss between the two leaves a
# manifest naming an absent database — which database_validate_rollback_backup
# rejects at its catalog probe — rather than an orphaned 30 GB database with no
# record of what it was.
database_release_rollback_artifact() {
    local backup_id="$1"
    local artifact_database="$2"
    local rollback_root="${METADATA_DIR}/database-rollback"
    local backup_dir="${rollback_root}/${backup_id}"
    database_backup_id_is_safe "$backup_id" || return 1
    if ! database_path_is_strict_child "$rollback_root" "$backup_dir" \
        || [[ "$(dirname -- "$backup_dir")" != "$rollback_root" ]]; then
        warn "Refusing to release a rollback artifact outside its own directory."
        return 1
    fi
    if [[ -n "$artifact_database" ]] \
        && ! database_drop_rollback_artifact_database "$artifact_database"; then
        return 1
    fi
    if $SUDO test -L "$backup_dir"; then
        warn "Refusing to remove a symlinked rollback artifact directory."
        return 1
    fi
    if $SUDO test -e "$backup_dir" && ! $SUDO rm -rf -- "$backup_dir"; then
        warn "Could not remove the rollback artifact directory ${backup_id}."
        return 1
    fi
    installer_durable_sync_path "$rollback_root" || return 1
    info "Rollback artifact released: ${backup_id}"
}

# Enumerate published rollback artifacts as `backup_id<TAB>target_version<TAB>
# artifact_database<TAB>size_bytes`, one per line. `artifact_database` is empty
# for a format_version 1 dump artifact, whose bytes live in its directory.
# Unreadable or malformed manifests are skipped rather than fatal: an operator
# hand-made directory must never be able to stop an upgrade.
database_enumerate_rollback_artifacts() {
    local rollback_root="${METADATA_DIR}/database-rollback"
    local manifest backup_id record
    $SUDO test -d "$rollback_root" || return 0
    while IFS= read -r manifest; do
        [[ -n "$manifest" ]] || continue
        backup_id="$(basename -- "$(dirname -- "$manifest")")"
        database_backup_id_is_safe "$backup_id" || continue
        $SUDO test -L "$manifest" && continue
        # shellcheck disable=SC2016  # jq variables are intentionally quoted.
        record="$(
            $SUDO cat "$manifest" 2>/dev/null \
                | jq -er --arg backup_id "$backup_id" '
                    if (.backup_id == $backup_id and
                        (.target_version | type == "string" and
                            test("^[0-9]+[.][0-9]+[.][0-9]+$")))
                    then [
                        .backup_id,
                        .target_version,
                        (if (.format_version == 2 and .kind == "database" and
                             (.artifact_database | type == "string" and
                               test("^[A-Za-z_][A-Za-z0-9_]{0,62}$")))
                         then .artifact_database else "" end),
                        (if (.size_bytes | type == "string" and
                             test("^[0-9]+$"))
                         then .size_bytes else "0" end)
                    ] | @tsv
                    else empty end' 2>> "$LOG_FILE"
        )" || continue
        [[ -n "$record" ]] || continue
        printf '%s\n' "$record"
    done < <($SUDO find "$rollback_root" -mindepth 2 -maxdepth 2 \
        -name manifest.json -type f 2>/dev/null | LC_ALL=C sort)
}

# Release every artifact that can never be validated again.
#
# database_validate_rollback_backup requires `.target_version == <currently
# installed version>`, so an artifact recorded against any other target is
# already unusable — keeping it only consumes the volume this whole change
# exists to protect. The artifact for the INSTALLED version is never touched
# here; releasing that one needs the operator's explicit
# --release-rollback-artifact consent.
database_release_superseded_rollback_artifacts() {
    local installed_version="" backup_id target_version artifact_database size
    local released=0 failed=0
    installed_version="$(existing_install_version 2>/dev/null || true)"
    if ! is_stable_semver "$installed_version"; then
        # Without a trustworthy installed version nothing can be proven
        # superseded, so nothing is released.
        return 0
    fi
    while IFS=$'\t' read -r backup_id target_version artifact_database size; do
        [[ -n "$backup_id" ]] || continue
        [[ "$target_version" != "$installed_version" ]] || continue
        info "Releasing superseded rollback artifact ${backup_id} (target ${target_version}, installed ${installed_version})"
        if database_release_rollback_artifact \
            "$backup_id" "$artifact_database"; then
            released=$(( released + 1 ))
        else
            failed=$(( failed + 1 ))
        fi
    done < <(database_enumerate_rollback_artifacts)
    (( released == 0 )) || info "Released ${released} superseded rollback artifact(s)"
    (( failed == 0 ))
}

database_complete_forward_upgrade_transition() {
    # Latch before anything can fail. Every `return 1` below leaves the guard
    # set, so `trap cleanup EXIT` -> database_abort_rollback cannot dispatch on
    # the still-current forward-target-healthy phase and re-run this body.
    DATABASE_FORWARD_TRANSITION_IN_PROGRESS="true"
    # Persist the no-reversal boundary while both the exact source database and
    # source deploy snapshot still exist. A process loss from this point keeps
    # the proven-healthy target and resumes only idempotent cleanup.
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" != \
        "forward-target-healthy" ]]; then
        # The target deployment may live on a filesystem separate from the
        # recovery journal. Flush it before the durable no-reversal phase allows
        # the exact source safety database to be dropped.
        if ! installer_durable_sync_path "$INSTALL_DIR" \
            || ! database_write_recovery_journal \
                "forward-target-healthy"; then
            return 1
        fi
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_FORWARD_UPGRADE_ACTIVE="false"
    if ! database_publish_upgrade_recovery_record; then
        return 1
    fi
    # The frozen safety database is NOT dropped here any more: it IS the
    # rollback artifact. What is released instead is every artifact recorded
    # against a target_version other than the one now installed — those can
    # never pass validation again, so they are pure dead weight. GC failing is
    # not a correctness failure, so it warns rather than stranding the journal.
    database_release_superseded_rollback_artifacts \
        || warn "Superseded rollback artifacts could not all be released; free space may be lower than expected."
    if ! database_discard_source_deploy_snapshot; then
        return 1
    fi
    # Success is the ONLY path that clears the guard.
    DATABASE_FORWARD_TRANSITION_IN_PROGRESS="false"
}

# Publish the durable record of how this upgrade can be recovered, AFTER the
# target has proven healthy.
#
# Two shapes, decided by what the run actually did rather than by a flag:
#
#   - An in-place upgrade copied nothing, so there is no on-host artifact. The
#     record names the restic snapshot resolved before the migration ran.
#   - A journal written by <= 0.0.135 names a frozen safety database left by
#     the old clone path. That database IS a usable rollback artifact, so it is
#     manifested rather than dumped or dropped — which is what unpins the 32 GB
#     production has been holding since 2026-08-03 (#1762).
database_publish_upgrade_recovery_record() {
    if [[ -n "${DATABASE_ROLLBACK_SAFETY_DATABASE:-}" ]]; then
        database_publish_frozen_safety_artifact
        return $?
    fi
    database_publish_restic_recovery_manifest
}

# Record the restic snapshot that is the recovery point for an in-place
# upgrade. O(1): a few hundred bytes, no database bytes read or written.
#
# The manifest is deliberately NOT consumable by --rollback-backup. Restoring a
# restic snapshot into production is a separately approved procedure with its
# own dual control (docs/operations/backups.md), and pretending the installer
# can do it in one flag would be the most dangerous kind of convenience. What
# this buys is that the recovery point is unambiguous and written down at the
# moment it was true, instead of being reconstructed from cron schedules after
# an incident.
database_publish_restic_recovery_manifest() {
    local source_version="${DATABASE_ROLLBACK_SOURCE_VERSION:-}"
    local target_version="" database timestamp backup_id
    local rollback_root final_dir staging_dir manifest_file
    local migration_version="${DATABASE_ROLLBACK_SOURCE_MIGRATION:-}"
    target_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$target_version" \
        || target_version="${OPT_VERSION:-}"
    if ! is_stable_semver "$source_version" \
        || ! is_stable_semver "$target_version"; then
        fail "In-place upgrade has no stable version identity; its recovery point cannot be recorded."
        return 1
    fi
    if ! database=$(database_install_identifier); then
        fail "Could not resolve the installer-managed database identifier for the recovery record."
        return 1
    fi
    [[ "$migration_version" =~ ^[0-9]+$ ]] || migration_version="0"

    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    backup_id="pre-upgrade-${source_version}-to-${target_version}-${timestamp}"
    database_backup_id_is_safe "$backup_id" || return 1
    rollback_root="${METADATA_DIR}/database-rollback"
    final_dir="${rollback_root}/${backup_id}"
    staging_dir="${rollback_root}/.partial-${backup_id}-$$"
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-"; then
        fail "Recovery record staging path is unsafe."
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR="$staging_dir"
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || $SUDO test -e "$final_dir" \
        || $SUDO test -e "$staging_dir" \
        || ! installer_install_private_directories "$staging_dir"; then
        fail "Recovery record staging could not be allocated safely."
        database_discard_backup_staging || true
        return 1
    fi
    manifest_file="${staging_dir}/manifest.json"
    if ! jq -n \
        --arg backup_id "$backup_id" \
        --arg source_version "$source_version" \
        --arg target_version "$target_version" \
        --arg database "$database" \
        --arg migration_version "$migration_version" \
        --arg created_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        --arg snapshot_id "${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID:-}" \
        --arg snapshot_time "${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME:-}" \
        '{format_version: 3, kind: "restic", backup_id: $backup_id,
          source_version: $source_version, target_version: $target_version,
          database: $database, migration_version: $migration_version,
          created_at: $created_at,
          recovery_snapshot_id: $snapshot_id,
          recovery_snapshot_time: $snapshot_time,
          migrated_in_place: true}' \
        | $SUDO /usr/bin/tee "$manifest_file" >/dev/null \
        || ! $SUDO chmod 0600 "$manifest_file" \
        || ! $SUDO test -s "$manifest_file" \
        || ! installer_durable_sync_path "$manifest_file"; then
        fail "Could not write the private in-place upgrade recovery record."
        database_discard_backup_staging || true
        return 1
    fi
    if ! $SUDO mv "$staging_dir" "$final_dir" \
        || ! installer_durable_sync_path "$rollback_root"; then
        fail "Could not publish the private in-place upgrade recovery record."
        database_discard_backup_staging || true
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""
    CREATED_DATABASE_BACKUP_ID="$backup_id"
    if [[ -n "${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID:-}" ]]; then
        info "In-place upgrade recorded: recovery point is restic snapshot ${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID} (${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME})"
    else
        warn "In-place upgrade recorded with NO recovery point; the pre-upgrade database state is not recoverable from this host."
    fi
    info "Recovery record: ${backup_id}"
}

# True (exit 0) only when a query against `postgres` positively confirms the
# named database does not exist. False (exit 1) for a connectivity or
# permission failure too — "confirmed absent" must never be inferred from "the
# check itself failed". Connects to the `postgres` maintenance database, never
# to the target, so it works whether or not the target exists.
database_confirmed_absent() {
    local database="$1"
    local result
    database_recovery_identifier_is_safe "$database" || return 1
    # shellcheck disable=SC2016  # Expanded by sh inside the database container.
    result=$(installer_run_live_compose exec -T timescaledb \
        sh -ceu 'exec psql --no-psqlrc --username="$POSTGRES_USER" --dbname=postgres --no-align --tuples-only --set=ON_ERROR_STOP=1 "$@"' sh \
        --set="absence_check_database=${database}" \
        2>> "$LOG_FILE" <<'SQL'
SELECT NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = :'absence_check_database');
SQL
    ) || return 1
    [[ "$result" == "t" ]]
}

# Publish the durable rollback artifact AFTER the target has proven healthy.
#
# The artifact IS the frozen safety database the forward upgrade's physical
# clone produced, so publishing it is a few hundred bytes of manifest instead
# of an O(database size) pg_dump. That dump was the defect: it was unbudgeted,
# ran against the same volume PostgreSQL lives on, and on 2026-08-03 could not
# complete against a 33 GB source with 8.5 GB free — pinning the safety database
# and leaving production unable to upgrade at all (#1762).
#
# The one thing that must be read from inside the frozen database is its
# migration version. Prefer the value the forward upgrade already recorded in
# the journal; only when that is absent (a v3 journal written by an older
# release) reopen it for a single round trip and close it again. An artifact
# left open is one TimescaleDB retention cycle away from being silently
# gutted, so the re-freeze is not optional and its failure is fatal.
#
# A v3 journal's safety database can also be CONFIRMED gone — not a read
# failure, a positive "no such row in pg_database" — when an operator removed
# it out-of-band after the installer got stuck (exactly production's
# 2026-08-11 state, #1780: the database named in the stuck journal was
# permanently released to unblock the same upgrade this function is trying to
# complete). There is nothing left to publish an artifact from. Treat that as
# "no artifact for this already-superseded transition", not as a failure —
# the alternative is a journal that can never reconcile again.
database_publish_frozen_safety_artifact() {
    local safety_database="${DATABASE_ROLLBACK_SAFETY_DATABASE:-}"
    local source_version="${DATABASE_ROLLBACK_SOURCE_VERSION:-}"
    local target_version="" database timestamp backup_id
    local rollback_root final_dir staging_dir manifest_file
    local migration_version="" size_bytes=""
    [[ -n "$safety_database" ]] || return 0
    if ! database_recovery_identifier_is_safe "$safety_database"; then
        fail "Refusing to publish an unsafe forward-upgrade safety database identifier."
        return 1
    fi
    # The INSTALLED version is authoritative here, not $OPT_VERSION.
    #
    # deploy_write_metadata has already published the target by the time this
    # boundary is reachable, so existing_install_version is what actually got
    # deployed. $OPT_VERSION is not: this point is re-entered on a resumed run
    # (process or host loss between "forward-target-healthy" and the publish),
    # and the recovery reconciler runs BEFORE target-argument validation — so an
    # operator resuming with a different --version would stamp that version into
    # the manifest. database_validate_rollback_backup requires
    # `.target_version == <currently installed version>`, so such an artifact
    # could never be used, and rollback capability would be lost silently,
    # behind a success message.
    target_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$target_version" \
        || target_version="${OPT_VERSION:-}"
    if ! is_stable_semver "$source_version" \
        || ! is_stable_semver "$target_version"; then
        fail "Forward-upgrade rollback artifact has no stable version identity; the source safety database is retained."
        return 1
    fi
    if ! database=$(database_install_identifier); then
        fail "Could not resolve the installer-managed database identifier for the rollback artifact."
        return 1
    fi

    step "  Publishing the frozen source database as the rollback artifact..."
    migration_version="${DATABASE_ROLLBACK_SOURCE_MIGRATION:-}"
    if [[ ! "$migration_version" =~ ^[0-9]+$ ]]; then
        if ! database_set_database_connections "$safety_database" "true"; then
            fail "Could not reopen the frozen source database to read its migration version."
            return 1
        fi
        migration_version=$(database_query_migration_version "$safety_database") \
            || migration_version=""
        if ! database_set_database_connections "$safety_database" "false"; then
            fail "Could not re-freeze the source database after reading its migration version."
            return 1
        fi
        if [[ ! "$migration_version" =~ ^[0-9]+$ ]]; then
            if database_confirmed_absent "$safety_database"; then
                warn "Forward-upgrade safety database ${safety_database} no longer exists; no rollback artifact can be published for this already-superseded transition."
                DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""
                DATABASE_ROLLBACK_SAFETY_DATABASE=""
                DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""
                return 0
            fi
            fail "Could not read the migration version of the frozen source database; it is retained for operator recovery."
            return 1
        fi
    fi
    # Advisory only: it sizes the headroom budget's releasable term. It is
    # deliberately NOT an integrity check — autovacuum wraparound processing
    # touches datallowconn=false databases, so byte equality would be brittle.
    size_bytes=$(database_measure_database_size "$safety_database") || size_bytes="0"

    timestamp=$(date -u +%Y%m%dT%H%M%SZ)
    backup_id="pre-upgrade-${source_version}-to-${target_version}-${timestamp}"
    database_backup_id_is_safe "$backup_id" || return 1
    rollback_root="${METADATA_DIR}/database-rollback"
    final_dir="${rollback_root}/${backup_id}"
    staging_dir="${rollback_root}/.partial-${backup_id}-$$"
    if ! database_path_is_safe_direct_child \
        "$rollback_root" "$staging_dir" ".partial-"; then
        fail "Rollback artifact staging path is unsafe; the source safety database is retained."
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR="$staging_dir"
    if ! installer_install_private_directories "$rollback_root" \
        || $SUDO test -L "$rollback_root" \
        || $SUDO test -e "$final_dir" \
        || $SUDO test -e "$staging_dir" \
        || ! installer_install_private_directories "$staging_dir"; then
        fail "Rollback artifact staging could not be allocated safely."
        database_discard_backup_staging || true
        return 1
    fi
    manifest_file="${staging_dir}/manifest.json"
    if ! jq -n \
        --arg backup_id "$backup_id" \
        --arg source_version "$source_version" \
        --arg target_version "$target_version" \
        --arg database "$database" \
        --arg artifact_database "$safety_database" \
        --arg migration_version "$migration_version" \
        --arg created_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        --arg size_bytes "$size_bytes" \
        '{format_version: 2, kind: "database", backup_id: $backup_id,
          source_version: $source_version, target_version: $target_version,
          database: $database, artifact_database: $artifact_database,
          migration_version: $migration_version, created_at: $created_at,
          size_bytes: $size_bytes}' \
        | $SUDO /usr/bin/tee "$manifest_file" >/dev/null \
        || ! $SUDO chmod 0600 "$manifest_file" \
        || ! $SUDO test -s "$manifest_file" \
        || ! installer_durable_sync_path "$manifest_file"; then
        fail "Could not write the private rollback artifact manifest."
        database_discard_backup_staging || true
        return 1
    fi
    if ! $SUDO mv "$staging_dir" "$final_dir" \
        || ! installer_durable_sync_path "$rollback_root"; then
        fail "Could not publish the private rollback artifact."
        database_discard_backup_staging || true
        return 1
    fi
    DATABASE_ROLLBACK_BACKUP_STAGING_DIR=""
    DATABASE_ROLLBACK_SAFETY_DATABASE=""
    DATABASE_ROLLBACK_REPLACEMENT_DATABASE=""

    CREATED_DATABASE_BACKUP_ID="$backup_id"
    info "Rollback artifact published: frozen database ${safety_database} at migration ${migration_version}"
    info "Retain rollback backup ID: ${CREATED_DATABASE_BACKUP_ID}"
}

database_abort_rollback() {
    # The forward transition runs from inside one of this function's own
    # branches, and `trap cleanup EXIT` calls this function. Without this guard
    # a failed transition is re-run in full by the installer's own exit path.
    [[ "${DATABASE_FORWARD_TRANSITION_IN_PROGRESS:-false}" != "true" ]] || return 1
    database_close_validated_backup_dump || true
    database_discard_backup_staging || true
    database_discard_restore_staging || true
    database_discard_source_snapshot_staging || true
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == \
        "target-migrating-in-place" ]]; then
        database_reconcile_in_place_migration
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "forward-target-healthy" ]]; then
        database_complete_forward_upgrade_transition
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "target-healthy" ]]; then
        database_discard_source_deploy_snapshot
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_SWAP_ACTIVE:-false}" == "true" ]]; then
        database_recover_interrupted_rollback
        return $?
    fi
    if [[ "${DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED:-false}" == "true" ]]; then
        if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == \
            "deploy-files-mutating" ]]; then
            database_restore_source_deploy_state true
            return $?
        fi
        if [[ "${DATABASE_ROLLBACK_RECOVERY_PHASE:-}" == "staging" ]] \
            && ! database_drop_replacement_database; then
            return 1
        fi
        database_restore_source_deploy_state
        return $?
    fi
    database_resume_proxy
}

# There is no automatic recovery from an interrupted in-place migration.
#
# The database may sit at any migration between the recorded source version and
# the target's. Reversing is impossible — a migration is not undoable — and
# restoring the SOURCE deploy tree would be actively harmful: sqlx refuses to
# start the older binary against a database carrying migrations it does not
# know, so the old release would crash-loop against its own data.
#
# So this does the only two useful things. It states the exact situation and
# the recorded recovery point, and it clears the journal so the installer is
# not permanently wedged — leaving the TARGET deploy tree in place, which is
# what a re-run needs. sqlx is idempotent, so re-running the target simply
# finishes or no-ops the remaining migrations.
database_reconcile_in_place_migration() {
    local source_version="${DATABASE_ROLLBACK_SOURCE_VERSION:-unknown}"
    local source_migration="${DATABASE_ROLLBACK_SOURCE_MIGRATION:-unknown}"
    warn "This deployment was interrupted while migrating the database IN PLACE."
    warn "  Source release: ${source_version} at migration ${source_migration}"
    warn "  The database may carry migrations the source release cannot start against."
    warn "  The installer cannot reverse this and will not try."
    if [[ -n "${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID:-}" ]]; then
        warn "  Recovery point: restic snapshot ${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_ID} (${DATABASE_ROLLBACK_RECOVERY_SNAPSHOT_TIME})"
    else
        warn "  Recovery point: NONE was recorded for this upgrade."
    fi
    warn "  To go forward, re-run this installer for the same target version."
    warn "  To go back, follow docs/runbooks/database-rollback.md — it is an operator procedure."
    # The target deploy tree stays. Only the durable snapshot of the SOURCE
    # tree is discarded, because restoring it can no longer help.
    if ! database_discard_source_deploy_snapshot; then
        fail "Interrupted in-place migration state could not be cleared safely."
        return 1
    fi
    info "Interrupted in-place migration acknowledged; the deployment is at the target release"
}

database_reconcile_pending_recovery() {
    if ! database_load_recovery_journal; then
        return 1
    fi
    if [[ "$DATABASE_ROLLBACK_RECOVERY_PHASE" == "target-healthy" ]]; then
        if ! database_discard_source_deploy_snapshot; then
            fail "Pending healthy-target cleanup could not be completed safely."
            return 1
        fi
        info "Pending healthy-target snapshot cleanup completed"
        return 0
    fi
    if ! database_abort_rollback; then
        fail "Pending interrupted database rollback could not be recovered safely."
        return 1
    fi
    info "Pending interrupted database rollback recovered to exact source state"
}

# Pending durable recovery must run before target argument/configuration
# validation. The target install metadata may already have been finalized when
# a process or host stops, and validating the repeated rollback command against
# that transient metadata would otherwise make source recovery unreachable.
database_reconcile_pending_recovery_before_configuration() {
    local recovery_journal managed_uid managed_group
    recovery_journal=$(database_recovery_journal_path)
    if ! $SUDO test -e "$recovery_journal"; then
        return 0
    fi
    if ! database_load_recovery_journal; then
        return 1
    fi
    managed_uid="$(installer_managed_deployment_uid)" || return 1
    managed_group="$(installer_managed_deployment_group)" || return 1
    # Revoke legacy service-user namespace mutation at the install-root anchor
    # before enumerating crash staging. Do not recurse until stale failed target
    # trees have been removed while still privileged-private.
    if ! $SUDO test -d "$INSTALL_DIR" || $SUDO test -L "$INSTALL_DIR" \
        || ! $SUDO chown "${managed_uid}:${managed_group}" "$INSTALL_DIR" \
        || ! $SUDO chmod 0750 "$INSTALL_DIR" \
        || ! installer_managed_path_is_safe \
            "$INSTALL_DIR" "directory" "750"; then
        fail "Pending recovery install root is not safe to mutate."
        return 1
    fi
    if ! database_validate_stale_failed_deploy_staging; then
        fail "Pending recovery failed-target staging is not safe to preserve."
        return 1
    fi
    # A journal may have been written by an older release whose deployment
    # directories were service-owned. Revoke descendant namespace mutation
    # before privileged recovery enumerates or copies into the live tree. The
    # durable deploy-stack-stopped phase deliberately permits docker/ to be
    # absent: process loss may land after it was renamed and before the source
    # snapshot was installed.
    if $SUDO test -d "${INSTALL_DIR}/docker" \
        || $SUDO test -L "${INSTALL_DIR}/docker"; then
        if ! deploy_protect_existing_managed_tree true; then
            fail "Pending recovery deployment tree is not safe to mutate."
            return 1
        fi
    elif [[ "$DATABASE_ROLLBACK_RECOVERY_PHASE" != "deploy-stack-stopped" ]] \
        || ! installer_managed_path_is_safe \
            "$INSTALL_DIR" "directory" "700:750:755"; then
        fail "Pending recovery deployment tree is missing outside its durable stopped phase."
        return 1
    fi
    if ! database_reconcile_pending_recovery; then
        return 1
    fi
    fail "Reconciled pending durable recovery state. Re-run this verified installer to begin a new deployment."
    return 1
}

database_wait_for_services_healthy() {
    local timeout="${DATABASE_ROLLBACK_HEALTH_TIMEOUT_SECONDS:-120}"
    [[ "$timeout" =~ ^[0-9]+$ ]] && (( timeout > 0 && timeout <= 600 )) || timeout=120
    local started container_id status service all_healthy
    local -a services=("$@")
    [[ ${#services[@]} -gt 0 ]] || return 1
    started=$(date +%s)
    while (( $(date +%s) - started < timeout )); do
        all_healthy="true"
        for service in "${services[@]}"; do
            container_id=$(installer_run_live_compose ps -q "$service" 2>/dev/null || true)
            status=""
            if [[ -n "$container_id" ]]; then
                status=$(installer_docker inspect --format='{{if .State.Health}}{{.State.Health.Status}}{{else}}{{.State.Status}}{{end}}' \
                    "$container_id" 2>/dev/null || true)
            fi
            [[ "$status" == "exited" || "$status" == "dead" ]] && return 1
            [[ "$status" == "healthy" ]] || all_healthy="false"
        done
        [[ "$all_healthy" == "true" ]] && return 0
        sleep 2
    done
    return 1
}

database_wait_for_proxy_healthy() {
    database_wait_for_services_healthy proxy
}

database_wait_for_source_stack_healthy() {
    # Traefik's built-in ping proves ingress-process liveness; the watchdog
    # proves the Consul TLS option needed by its ingress routes remains readable.
    # A public HTTPS probe is deliberately avoided because recovery must also
    # work for installations without a configured public DNS name.
    database_wait_for_services_healthy \
        timescaledb consul proxy traefik consul-kv-watchdog
}

database_wait_for_target_stack_healthy() {
    database_wait_for_services_healthy \
        timescaledb consul proxy traefik consul-kv-watchdog
}

database_source_snapshot_required_for_deploy() {
    [[ "$COMMAND" == "upgrade" ]] || return 1
    local installed_version
    installed_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$installed_version" || return 1
    is_stable_semver "$OPT_VERSION" || return 1
    [[ -n "$OPT_ROLLBACK_BACKUP_ID" ]] \
        || stable_semver_gt "$OPT_VERSION" "$installed_version"
}

deploy_handle_database_transition() {
    [[ "$COMMAND" == "upgrade" ]] || return 0
    local installed_version
    installed_version=$(existing_install_version 2>/dev/null || true)
    is_stable_semver "$installed_version" || return 0
    is_stable_semver "$OPT_VERSION" || return 0

    if [[ -n "$OPT_ROLLBACK_BACKUP_ID" ]]; then
        database_restore_version_backup "$installed_version" "$OPT_VERSION" \
            "$OPT_ROLLBACK_BACKUP_ID"
    elif stable_semver_gt "$OPT_VERSION" "$installed_version"; then
        database_prepare_forward_upgrade "$installed_version" "$OPT_VERSION" \
            || return 1
        info "Migrations apply in place; the recovery point is recorded after the target proves healthy."
    elif stable_semver_gt "$installed_version" "$OPT_VERSION"; then
        fail "Database rollback backup is required before starting an older binary."
        return 1
    fi
}

deploy_complete_database_transition() {
    if [[ "$DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED" == "true" ]]; then
        # Compose has started the recovered proxy, so it is no longer quiesced.
        # Keep source recovery available until the complete target stack proves
        # healthy after every fallible deploy finalizer.
        DATABASE_ROLLBACK_PROXY_STOPPED="false"
        if ! database_wait_for_target_stack_healthy; then
            fail "Target stack did not become healthy; restoring the exact source deployment."
            database_abort_rollback || true
            return 1
        fi
        info "Target database, Consul, proxy, and ingress are healthy"
        if [[ "$DATABASE_FORWARD_UPGRADE_ACTIVE" == "true" ]]; then
            if ! database_complete_forward_upgrade_transition; then
                fail "Target stack is healthy, but durable forward-upgrade cleanup could not be completed."
                return 1
            fi
        elif ! database_discard_source_deploy_snapshot; then
            fail "Target stack is healthy, but durable recovery cleanup could not be completed."
            return 1
        fi
    fi
    DATABASE_ROLLBACK_SWAP_ACTIVE="false"
    DATABASE_ROLLBACK_PROXY_STOPPED="false"
}

# Determine the expected filesystem type ("file" or "dir") of a compose
# bind-mount SOURCE path. Pure function — derives the answer from the path's
# final segment: a segment containing a dot (e.g. default.conf, prometheus.yml)
# is a file mount; a segment with no extension (e.g. traefik-dynamic, rules,
# provisioning) is a directory mount. This matches every bind-mount source
# declared across docker-compose.yml and its overlays today.
#
# LIMITATION: the heuristic would misclassify an extensionless config FILE
# (e.g. Caddyfile) or a dotted DIRECTORY (e.g. conf.d). If such a source is ever
# added to a compose overlay, extend this function with an explicit override
# list and update the manifest-coverage test accordingly.
# Echoes "file" or "dir".
bind_mount_expected_type() {
    local src="$1"
    local base="${src##*/}"
    if [[ "$base" == *.* ]]; then
        echo "file"
    else
        echo "dir"
    fi
}

# Extract bind-mount SOURCE paths (the `./...` host paths) from the compose
# overlays that are actually active for this deployment. Echoes one relative
# source path per line (with the leading `./` stripped), de-duplicated.
# Reads the compose files already extracted under ${INSTALL_DIR}/docker.
collect_active_bind_mount_sources() {
    local -a overlays=("docker-compose.yml" "docker-compose.hardened.yml")
    [[ "$OPT_WAF" == "true" ]] && overlays+=("docker-compose.waf.yml")
    [[ "$OPT_TLS" == "true" ]] && overlays+=("docker-compose.tls.yml")
    [[ "$OPT_MONITORING" == "true" ]] && overlays+=("docker-compose.monitoring.yml")
    [[ "$OPT_BACKUP" == "true" ]] && overlays+=("docker-compose.backup.yml")
    $SUDO test -f "${INSTALL_DIR}/docker/docker-compose.dns.yml" \
        && overlays+=("docker-compose.dns.yml")
    if [[ "$IS_MACOS" == "true" ]] && [[ "$MACOS_HOST_NETWORKING" == "true" ]]; then
        :
    elif [[ "$IS_MACOS" == "true" ]] || [[ "$OPT_MDNS" != "true" ]]; then
        overlays+=("docker-compose.no-mdns.yml")
    fi
    [[ "$OPT_DEBUG" == "true" ]] && overlays+=("docker-compose.debug.yml")

    local overlay path
    for overlay in "${overlays[@]}"; do
        path="${INSTALL_DIR}/docker/${overlay}"
        $SUDO test -f "$path" || continue
        # Match `- ./SRC:/container/path[:opts]` bind-mount lines and emit SRC
        # with the leading `./` removed. Named volumes (no leading `./`) and
        # absolute host paths are intentionally skipped.
        #
        # `|| true` is REQUIRED: grep exits 1 when a compose file declares no
        # `./` bind mounts (e.g. docker-compose.hardened.yml, always active).
        # Under the installer's `set -euo pipefail` that non-match would abort
        # the whole run before the preflight could report anything. The bats
        # suite sources with --source-only (no strict mode) so it would not
        # catch this — see bind_mount_preflight.bats strict-mode case.
        { $SUDO grep -oE '^\s*-\s*\./[^:]+' "$path" || true; } \
            | sed -E 's/^\s*-\s*\.\///'
    done | sort -u
}

# Defensive preflight: BEFORE `compose up`, verify every active bind-mount
# SOURCE path exists on the host as the correct type. This is the permanent fix
# for #1390: when a file-type bind-mount source is absent, Docker auto-creates a
# DIRECTORY at the mount path and `compose up` aborts mid-deploy ("not a
# directory"), which took prod ingress DOWN on the v0.0.87 upgrade.
#
# Runs AFTER deploy_extract_files (so every embedded config is on disk) and
# BEFORE any container is started, so a missing/mistyped mount fails the deploy
# cleanly instead of part-way through bringing the stack up.
#
# Behaviour per source:
#   - file expected, file present       -> OK
#   - dir  expected, dir  present       -> OK
#   - dir  expected, missing            -> create it (directory mounts, e.g.
#                                          traefik-dynamic, are allowed to be
#                                          empty; Docker would create them anyway)
#   - dir  expected, file present       -> FAIL (clearly wrong)
#   - file expected, missing            -> FAIL (extract should have created it)
#   - file expected, directory present  -> remove the stray (empty) dir if it is
#                                          empty, else FAIL — never let Docker
#                                          mount a dir onto a file path
deploy_verify_bind_mounts() {
    step "  Verifying bind-mount sources..."
    local docker_dir="${INSTALL_DIR}/docker"
    local -a problems=()
    local src abs expected

    while IFS= read -r src; do
        [[ -z "$src" ]] && continue
        abs="${docker_dir}/${src}"
        expected="$(bind_mount_expected_type "$src")"

        if [[ "$expected" == "dir" ]]; then
            if $SUDO test -f "$abs"; then
                problems+=("expected DIRECTORY but found a file: docker/${src}")
            elif ! $SUDO test -d "$abs"; then
                # Directory mounts may legitimately be empty; create it so
                # Docker mounts a real dir rather than failing.
                $SUDO mkdir -p "$abs"
                info "Created missing bind-mount directory: docker/${src}"
            fi
            continue
        fi

        # expected == "file"
        if $SUDO test -f "$abs"; then
            continue
        fi
        if $SUDO test -d "$abs"; then
            # The exact #1390 failure mode: a (usually empty) directory sitting
            # where a config FILE must be — left behind by a prior failed
            # `compose up`. Remove it only if empty, then report it missing so
            # the operator knows extraction did not produce the file.
            if $SUDO rmdir "$abs" 2>/dev/null; then
                problems+=("config file missing (removed stray empty directory): docker/${src}")
            else
                problems+=("expected FILE but found a non-empty directory: docker/${src}")
            fi
            continue
        fi
        problems+=("config file missing: docker/${src}")
    done < <(collect_active_bind_mount_sources)

    if [[ ${#problems[@]} -gt 0 ]]; then
        local -a box_lines=(
            ""
            "One or more docker-compose bind-mount sources are missing or"
            "have the wrong type. Starting the stack now would let Docker"
            "auto-create a directory at a config-file mount path and abort"
            "\`compose up\` mid-deploy (this took prod ingress down — #1390)."
            ""
            "Problems:"
        )
        for src in "${problems[@]}"; do
            box_lines+=("  - ${src}")
        done
        box_lines+=(
            ""
            "Re-run install.sh to re-extract the embedded config files."
            ""
            "Full log: ${LOG_FILE}"
        )
        draw_box "FAILED: bind-mount preflight" "${box_lines[@]}"
        die "Aborting before touching the running stack — bind-mount sources are invalid (#1390)"
    fi

    info "All bind-mount sources present and correctly typed"
}

deploy_start_stack() {
    step "  Starting services..."
    # docker-compose.backup.yml declares proxy_ca_data as external:true.
    # Docker Compose validates all declared volumes before starting any
    # containers. Create the volume idempotently so compose up never fails
    # with "external volume not found" on the first install or after a purge.
    installer_docker volume create proxy_ca_data >> "$LOG_FILE" 2>&1 || true
    info "proxy_ca_data volume ready"

    # Start only the infrastructure services first. consul-init requires a
    # Consul ACL token which doesn't exist until deploy_consul_acl_bootstrap()
    # runs. Starting the full stack here would cause consul-init to exit 1
    # (no token) and abort compose up. The full stack is brought up after
    # ACL bootstrap in deploy_start_remaining_services().
    local -a bootstrap_services=("timescaledb" "consul")
    [[ "$OPT_MONITORING" == "true" ]] && bootstrap_services+=("prometheus" "grafana")
    if ! installer_run_live_compose up -d "${bootstrap_services[@]}" >> "$LOG_FILE" 2>&1; then
        draw_box "FAILED: Start infrastructure services" \
            "" \
            "Docker Compose failed while starting:" \
            "  ${bootstrap_services[*]}" \
            "" \
            "Retry command:" \
            "  ${INSTALL_DIR}/compose-command.sh up -d ${bootstrap_services[*]}" \
            "" \
            "Check logs:" \
            "  ${INSTALL_DIR}/compose-command.sh logs ${bootstrap_services[0]}" \
            "  tail -n 80 ${LOG_FILE}" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi

    local timeout=120
    local start_time
    start_time=$(date +%s)

    for svc in "${bootstrap_services[@]}"; do
        local status="starting"
        while [[ "$status" != "healthy" ]]; do
            status=$(installer_docker inspect --format='{{.State.Health.Status}}' \
                "$(installer_run_live_compose ps -q "$svc" 2>/dev/null || true)" \
                2>/dev/null || echo "starting")

            local elapsed=$(( $(date +%s) - start_time ))
            if [[ $elapsed -ge $timeout ]]; then
                draw_box "FAILED: Health check timeout" \
                    "" \
                    "Service '${svc}' did not become healthy in ${timeout}s." \
                    "" \
                    "Check logs:" \
                    "  ${INSTALL_DIR}/compose-command.sh logs ${svc}" \
                    "" \
                    "Full log: ${LOG_FILE}"
                exit 1
            fi
            sleep 2
        done
        info "${svc} healthy"
    done
    info "Infrastructure services running"
}

deploy_start_remaining_services() {
    step "  Starting remaining services..."
    local service
    # An unsafe legacy-owned bind source is atomically replaced so a retained
    # writable descriptor cannot corrupt the published file. Recreate only the
    # affected container before the final full-stack reconciliation so Docker
    # drops its mount of the now-unlinked legacy inode.
    for service in "${DEPLOY_BIND_MOUNT_RECREATE_SERVICES[@]}"; do
        if ! installer_run_live_compose up -d \
            --no-deps --force-recreate "$service" >> "$LOG_FILE" 2>&1; then
            draw_box "FAILED: Refresh protected bind mount" \
                "" \
                "Docker Compose could not recreate service '${service}'." \
                "The service may still hold a legacy bind-mount inode." \
                "" \
                "Full log: ${LOG_FILE}"
            exit 1
        fi
    done
    DEPLOY_BIND_MOUNT_RECREATE_SERVICES=()

    # Bring up the full stack now that Consul ACL tokens are in .env.
    # consul-init will succeed this time because CONSUL_HTTP_TOKEN is set.
    if ! installer_run_live_compose up -d >> "$LOG_FILE" 2>&1; then
        draw_box "FAILED: Start remaining services" \
            "" \
            "Docker Compose failed while starting the full stack." \
            "" \
            "Retry command:" \
            "  ${INSTALL_DIR}/compose-command.sh up -d" \
            "" \
            "Check logs:" \
            "  ${INSTALL_DIR}/compose-command.sh logs" \
            "  tail -n 80 ${LOG_FILE}" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi
    info "All services running"
}

deploy_consul_acl_bootstrap() {
    step "  Bootstrapping Consul ACLs..."

    local env_file="${INSTALL_DIR}/docker/.env"
    local bootstrap_token_file="${METADATA_DIR}/consul-bootstrap-token"
    local managed_uid managed_group macos_home
    local reconcile_status=0
    local -a reconcile_command=()

    # Skip-gate (#1550/#1552): only short-circuit when ALL THREE Consul token keys
    # carry a NON-EMPTY value. The original gate used `grep -q "^CONSUL_HTTP_TOKEN="`
    # which matches a blank `CONSUL_HTTP_TOKEN=` line — so a token that had been
    # emptied read as "already bootstrapped", the reconcile was skipped, and every
    # cold start served a silent 404. `-qE "^KEY=.+"` requires at least one char
    # after the `=`. If the gate does NOT pass we fall through to the reconciler,
    # which runs its own LIVE traefik/ write probe (presence is never trust — it
    # re-mints only when the probe fails).
    if grep -qE "^CONSUL_HTTP_TOKEN=.+" "$env_file" 2>/dev/null && \
       grep -qE "^BACKUP_CONSUL_HTTP_TOKEN=.+" "$env_file" 2>/dev/null && \
       grep -qE "^PROXY_BACKUP_CONSUL_TOKEN=.+" "$env_file" 2>/dev/null; then
        info "Consul ACL tokens already present — running reconciler to validate + seed"
    fi

    # Delegate to the ONE shared reconciler (docker/consul-acl-ensure.sh) that
    # install/upgrade AND every boot (systemd ExecStartPre / launchd llap-boot.sh)
    # invoke. It: polls consul liveness (non-blocking if transient), validates the
    # existing token via a live traefik/ write probe, reuses/recovers/bootstraps a
    # management token, mints scoped tokens ONLY when the probe fails, atomically
    # key-replaces the .env (never appends → no duplicate keys), seeds via
    # consul-init WITHOUT `|| true` (loud — feeds the #1551 gate), and restarts the
    # token consumers. Raw SecretIDs never touch the log; masked only.
    #
    # Consul was just started healthy by deploy_start_stack(), so the reconciler's
    # liveness poll passes immediately here. A non-zero exit on THIS path means
    # "consul up but ACL unrecoverable" (permutation a') — a hard install failure,
    # exactly like the old inline `exit 1`.
    if [[ "$IS_MACOS" == "true" ]]; then
        # Never elevate an operator-owned deploy hook. Migrate only the exact
        # private bootstrap-token leaf left by an older installer, then execute
        # the reconciler as the logged-in Docker Desktop user with a clean,
        # deterministic tool environment. Its Docker calls route through the
        # canonical Compose launcher and pinned Desktop socket.
        managed_uid="$(installer_managed_deployment_uid)" \
            || die "Could not resolve the macOS deployment user."
        managed_group="$(installer_managed_deployment_group)" \
            || die "Could not resolve the macOS deployment group."
        macos_home="$(installer_macos_operator_home \
            "$(installer_macos_operator_user)")" \
            || die "Could not resolve the macOS deployment home."
        if $SUDO test -e "$bootstrap_token_file" \
            || $SUDO test -L "$bootstrap_token_file"; then
            if ! $SUDO test -f "$bootstrap_token_file" \
                || $SUDO test -L "$bootstrap_token_file" \
                || ! installer_path_has_single_link "$bootstrap_token_file" \
                || ! $SUDO chown "${managed_uid}:${managed_group}" \
                    "$bootstrap_token_file" \
                || ! $SUDO chmod 0600 "$bootstrap_token_file"; then
                die "Existing macOS Consul bootstrap-token authority is unsafe."
            fi
        fi
        reconcile_command=(
            /usr/bin/env -i
            "PATH=/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin"
            "HOME=${macos_home}"
            "INSTALL_DIR=${INSTALL_DIR}"
            "METADATA_DIR=${METADATA_DIR}"
            "SERVICE_USER=${SERVICE_USER}"
            "IS_MACOS=true"
            "OPT_BACKUP=${OPT_BACKUP}"
            "SUDO="
            "${INSTALL_DIR}/docker/consul-acl-ensure.sh"
        )
        "${reconcile_command[@]}" >> "$LOG_FILE" 2>&1 \
            || reconcile_status=$?
    else
        $SUDO /usr/bin/env -i \
            PATH=/usr/bin:/bin \
            HOME=/root \
            LC_ALL=C \
            INSTALL_DIR="${INSTALL_DIR}" \
            METADATA_DIR="${METADATA_DIR}" \
            SERVICE_USER="${SERVICE_USER}" \
            IS_MACOS=false \
            OPT_BACKUP="${OPT_BACKUP}" \
            "${INSTALL_DIR}/docker/consul-acl-ensure.sh" \
            >> "$LOG_FILE" 2>&1 || reconcile_status=$?
    fi
    if (( reconcile_status != 0 )); then
        draw_box "FAILED: Consul ACL reconcile" \
            "" \
            "The Consul ACL reconciler could not provision a valid token." \
            "This usually means Consul is up but its ACL state is" \
            "unrecoverable (bootstrapped, but no valid token survives)." \
            "" \
            "Recovery options:" \
            "  1. Re-run with --purge to reset all state (DATA LOSS)" \
            "  2. Recover a management token and save it to:" \
            "       ${METADATA_DIR}/consul-bootstrap-token" \
            "     then re-run: ${INSTALL_DIR}/docker/consul-acl-ensure.sh" \
            "" \
            "Full log: ${LOG_FILE}"
        exit 1
    fi

    info "Consul ACLs reconciled with scoped tokens"
}

# ── Deploy: system service ───────────────────────────────────────────────────

deploy_install_service() {
    step "  Installing system service..."

    if [[ "$IS_MACOS" == "true" ]]; then
        local plist_dir="${HOME}/Library/LaunchAgents"
        local plist_staging
        mkdir -p "$plist_dir"
        local plist_file="${plist_dir}/com.llm-api-proxy.plist"
        plist_staging="$(mktemp "${plist_file}.XXXXXX")" \
            || die "Could not allocate LaunchAgent staging."
        CLEANUP_FILES+=("$plist_staging")
        cat > "$plist_staging" <<PLISTEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>com.llm-api-proxy</string>
    <key>ProgramArguments</key>
    <array>
        <string>${INSTALL_DIR}/docker/llap-boot.sh</string>
    </array>
    <key>EnvironmentVariables</key>
    <dict>
        <key>INSTALL_DIR</key>
        <string>${INSTALL_DIR}</string>
        <key>METADATA_DIR</key>
        <string>${METADATA_DIR}</string>
        <key>SERVICE_USER</key>
        <string>${SERVICE_USER}</string>
        <key>IS_MACOS</key>
        <string>true</string>
        <key>OPT_BACKUP</key>
        <string>${OPT_BACKUP}</string>
        <key>HOME</key>
        <string>${HOME}</string>
        <key>PATH</key>
        <string>/usr/local/bin:/opt/homebrew/bin:/usr/bin:/bin</string>
        <key>SUDO</key>
        <string></string>
    </dict>
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <false/>
    <key>WorkingDirectory</key>
    <string>${INSTALL_DIR}/docker</string>
</dict>
</plist>
PLISTEOF
        chmod 0644 "$plist_staging" \
            || die "Could not protect LaunchAgent staging."
        mv "$plist_staging" "$plist_file" \
            || die "Could not atomically publish the LaunchAgent."
        # Reload idempotently, but never report boot recovery as installed
        # unless launchd accepted and registered the exact new plist.
        launchctl unload "$plist_file" >/dev/null 2>&1 || true
        if ! launchctl load "$plist_file" >> "$LOG_FILE" 2>&1 \
            || ! launchctl list com.llm-api-proxy \
                >> "$LOG_FILE" 2>&1; then
            die "launchd rejected the LLAP boot recovery service."
        fi
        info "launchd service installed"
        return 0
    fi

    local unit_file="/etc/systemd/system/llm-api-proxy.service"
    local unit_staging
    unit_staging="$($SUDO mktemp \
        /etc/systemd/system/.llm-api-proxy.service.XXXXXX)" \
        || die "Could not allocate systemd unit staging."
    CLEANUP_FILES+=("$unit_staging")
    $SUDO /usr/bin/tee "$unit_staging" > /dev/null <<UNITEOF
[Unit]
Description=LLM API Proxy
Documentation=https://llm-api-proxy.com/docs
After=docker.service
Requires=docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
User=${SERVICE_USER}
Group=${SERVICE_USER}
WorkingDirectory=${INSTALL_DIR}/docker
# Consul ACL self-heal BEFORE the stack comes up (#1552). On a cold start the
# .env token may be empty/stale (the #1550 incident); the reconciler validates,
# recovers, and re-mints so consul-init can seed traefik/* and Traefik can read
# it — no silent 404. It is NON-BLOCKING on a transient/unreachable Consul (exits
# 0 so 'compose up' still brings proxy/DB up) and only fails ExecStartPre when
# Consul is UP but its ACL state is unrecoverable — in which case starting
# Traefik would just reproduce the outage, so we WANT the boot to fail loud.
#
# The '+' prefix runs THIS line with full privileges (root) regardless of the
# User= above: the reconciler must read the 0600 root:root bootstrap-token file
# and write the root:${SERVICE_USER} .env. The reconciler SELF-LOCKS via flock
# (single-flight, so a manual run and this boot hook cannot mint concurrently);
# no external flock wrapper is needed here.
ExecStartPre=+/usr/bin/env -i PATH=/usr/bin:/bin HOME=/root LC_ALL=C INSTALL_DIR=${INSTALL_DIR} METADATA_DIR=${METADATA_DIR} SERVICE_USER=${SERVICE_USER} IS_MACOS=false OPT_BACKUP=${OPT_BACKUP} ${INSTALL_DIR}/docker/consul-acl-ensure.sh
ExecStart=${INSTALL_DIR}/compose-command.sh up -d
ExecStop=${INSTALL_DIR}/compose-command.sh down
ExecReload=${INSTALL_DIR}/compose-command.sh up -d
# Budget covers the reconciler's bounded liveness poll (~60s worst case) + the
# flock wait + 'compose up -d'. Bounded so a wedged boot fails fast instead of
# hanging systemd's start job indefinitely.
TimeoutStartSec=300
TimeoutStopSec=60

[Install]
WantedBy=multi-user.target
UNITEOF
    if ! $SUDO chmod 0644 "$unit_staging" \
        || ! $SUDO mv "$unit_staging" "$unit_file"; then
        die "Could not atomically publish the systemd service."
    fi

    $SUDO systemctl daemon-reload
    $SUDO systemctl enable llm-api-proxy >> "$LOG_FILE" 2>&1
    info "systemd service installed and enabled"
}

# ── Deploy: install metadata ─────────────────────────────────────────────────

deploy_write_metadata() {
    step "  Writing install metadata..."
    local meta_file="${METADATA_DIR}/install.json"
    local version_file="${INSTALL_DIR}/.version"
    local managed_uid managed_group

    local features="["
    [[ "$OPT_WAF" == "true" ]] && features+='"waf",'
    [[ "$OPT_TLS" == "true" ]] && features+='"tls",'
    [[ "$OPT_BACKUP" == "true" ]] && features+='"backup",'
    [[ "$OPT_MONITORING" == "true" ]] && features+='"monitoring",'
    [[ "$OPT_MDNS" == "true" ]] && features+='"mdns",'
    features="${features%,}]"

    if [[ "$IS_MACOS" == "true" ]]; then
        managed_uid="$(installer_managed_deployment_uid)" \
            || die "Could not resolve the macOS metadata owner."
        managed_group="$(installer_managed_deployment_group)" \
            || die "Could not resolve the macOS metadata group."
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        /usr/bin/tee "$meta_file" > /dev/null <<METAEOF
{
  "install_dir": "${INSTALL_DIR}",
  "installed_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "installed_by": "install.sh ${INSTALLER_VERSION}",
  "version": "${OPT_VERSION}",
  "os": "${OS_ID}-${OS_VERSION}",
  "arch": "${ARCH}",
  "features": ${features},
  "tos_accepted_at": "${TOS_ACCEPTED_AT:-}",
  "tos_sha256": "${TOS_SHA256:-}",
  "tos_accepted_by": "$(whoami)"
}
METAEOF
    else
        $SUDO /usr/bin/tee "$meta_file" > /dev/null <<METAEOF
{
  "install_dir": "${INSTALL_DIR}",
  "installed_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "installed_by": "install.sh ${INSTALLER_VERSION}",
  "version": "${OPT_VERSION}",
  "os": "${OS_ID}-${OS_VERSION}",
  "arch": "${ARCH}",
  "features": ${features},
  "tos_accepted_at": "${TOS_ACCEPTED_AT:-}",
  "tos_sha256": "${TOS_SHA256:-}",
  "tos_accepted_by": "$(whoami)"
}
METAEOF
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        chmod 0644 "$meta_file"
        printf '%s\n' "${OPT_VERSION}" \
            | /usr/bin/tee "$version_file" >/dev/null
        chmod 0644 "$version_file"
        installer_managed_path_is_safe "$meta_file" "file" "644" \
            || die "macOS install metadata authority is unsafe."
        installer_managed_path_is_safe "$version_file" "file" "644" \
            || die "macOS version metadata authority is unsafe."
    else
        $SUDO chmod 0644 "$meta_file"
        printf '%s\n' "${OPT_VERSION}" \
            | $SUDO /usr/bin/tee "$version_file" >/dev/null
    fi
    info "Metadata written to ${meta_file}"
}

# ── Deploy: open browser ─────────────────────────────────────────────────────

deploy_open_browser() {
    if [[ "$OPT_NON_INTERACTIVE" == "true" ]]; then
        return 0
    fi

    local url
    if [[ "$OPT_TLS" == "true" ]]; then
        url="https://${OPT_DOMAIN}"
    else
        local ip
        ip=$(ip -6 addr show scope global 2>/dev/null | awk '/inet6 /{split($2,a,"/"); print a[1]; exit}' || true)
        [[ -z "$ip" ]] && ip=$(hostname -I 2>/dev/null | awk '{print $1}' || echo "localhost")
        url="http://${ip}"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        open "$url" 2>/dev/null || true
    elif [[ -n "${DISPLAY:-}" ]] || [[ -n "${WAYLAND_DISPLAY:-}" ]]; then
        if command -v xdg-open &>/dev/null; then
            xdg-open "$url" 2>/dev/null || true
        fi
    fi
}

# ── Deploy: post-install summary ─────────────────────────────────────────────

deploy_post_install_summary() {
    local url service_cmd log_cmd
    if [[ "$OPT_TLS" == "true" ]]; then
        url="https://${OPT_DOMAIN}"
    else
        local ip
        ip=$(ip -6 addr show scope global 2>/dev/null | awk '/inet6 /{split($2,a,"/"); print a[1]; exit}' || true)
        [[ -z "$ip" ]] && ip=$(hostname -I 2>/dev/null | awk '{print $1}' || echo "localhost")
        url="http://${ip}"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        service_cmd="launchctl list | grep llm-api-proxy"
        log_cmd="${INSTALL_DIR}/compose-command.sh logs -f"
    else
        service_cmd="systemctl status llm-api-proxy"
        log_cmd="${INSTALL_DIR}/compose-command.sh logs -f"
    fi

    draw_box "Installation complete!" \
        "" \
        "Dashboard:  ${url}" \
        "Status:     ${service_cmd}" \
        "Logs:       ${log_cmd}" \
        "Config:     ${INSTALL_DIR}/docker/.env" \
        "" \
        "Complete the setup wizard in your browser" \
        "to create your first admin account." \
        "" \
        "Useful commands:" \
        "  Restart: systemctl restart llm-api-proxy" \
        "  Stop:    systemctl stop llm-api-proxy" \
        "  Upgrade: re-run install.sh" \
        "" \
        "Docs: https://llm-api-proxy.com/docs"
}

# ── Deploy: orchestrator ─────────────────────────────────────────────────────

run_deploy() {
    step "[5/5] Deploying..."

    # Capture source bytes and durable recovery identity before the first target
    # Compose/.env mutation for both stable forward upgrades and database-backed
    # rollbacks. Recovery reassigns the archived legacy metadata to the current
    # platform authority before publication.
    if database_source_snapshot_required_for_deploy; then
        database_snapshot_source_deploy_state
    fi

    # Establish the platform deployment authority before any privileged backup
    # or writer traverses the live tree: privileged/root-owned on Linux, invoking
    # current-user-owned on macOS. The source snapshot above preserves the
    # pre-upgrade bytes; recovered ownership is deliberately re-hardened.
    deploy_create_dirs
    deploy_sweep_stale_compose_command_staging \
        || die "Could not safely clear stale Compose command staging."
    deploy_sweep_stale_image_lock_staging \
        || die "Could not safely clear stale release image-lock staging."

    if [[ "$COMMAND" == "upgrade" ]]; then
        deploy_backup_compose_files
    fi

    deploy_extract_files

    if [[ "$COMMAND" == "upgrade" ]]; then
        deploy_upgrade_env
    else
        deploy_write_env
    fi

    deploy_write_container_dns_overlay
    deploy_write_compose_command
    # Fail BEFORE touching the running stack if any bind-mount source is missing
    # or the wrong type (#1390) — never let `compose up` auto-create a directory
    # at a config-file mount path and take ingress down mid-deploy.
    deploy_verify_bind_mounts
    ghcr_login
    deploy_pull_images
    deploy_verify_locked_images
    if [[ "$DATABASE_ROLLBACK_DEPLOY_RESTORE_REQUIRED" == "true" ]] \
        && ! database_write_recovery_journal "deploy-mutating"; then
        die "Could not persist the runtime-mutation recovery boundary."
    fi
    deploy_handle_database_transition
    deploy_start_stack
    deploy_consul_acl_bootstrap
    deploy_start_remaining_services
    configure_nftables_docker_forward
    deploy_install_service
    deploy_write_metadata
    deploy_complete_database_transition
    deploy_post_install_summary
    deploy_open_browser
}

run_verified_recovery_preflight() {
    INSTALL_PHASE="verification"
    if ! run_installer_verification; then
        return 1
    fi
    # Verification is intentionally concurrent and read-only. Serialize only
    # after the installer checksum, published signature, and host privilege
    # boundary are authenticated, but before journal recovery or target
    # bootstrap can mutate host state.
    acquire_installer_single_flight_lock

    # A journaled source deployment must be recovered immediately after the
    # installer and host-access boundary is verified. Target credentials,
    # debug prompts, registry probes, and image/network checks are deliberately
    # later so a broken or unavailable target cannot make recovery unreachable.
    INSTALL_PHASE="recovery"
    if ! database_reconcile_pending_recovery_before_configuration; then
        return 1
    fi

    INSTALL_PHASE="target-bootstrap"
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" \
        && "$COMMAND" == "upgrade" ]]; then
        # A receipt-bound existing upgrade must reach run_deploy's source
        # snapshot without package-manager or other generic host convergence.
        # Verification already required a GPG implementation and curl; require
        # the complete target verifier toolset to be present and fail closed.
        if ! command -v curl >/dev/null 2>&1 \
            || ! command -v jq >/dev/null 2>&1 \
            || { ! command -v gpg >/dev/null 2>&1 \
                && ! command -v gpgv >/dev/null 2>&1; }; then
            fail "Receipt-bound upgrade requires preinstalled curl, jq, and gpg/gpgv before source snapshot."
            return 1
        fi
    else
        ensure_preflight_tools \
            || warn "curl/jq unavailable — target preflight may fail closed"
    fi

    resolve_github_token
    if [[ -n "${GITHUB_TOKEN_RESOLVED:-}" ]]; then
        detect_github_user
    fi
    load_debug_state_from_env
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" \
        && "$OPT_DEBUG" == "true" ]]; then
        die "Signed-receipt-bound stable execution does not permit debug images."
    fi
    warn_debug_mode

    INSTALL_PHASE="preflight"
    run_preflight
    verify_receipt_authorized_recovery_source
}

run_verified_uninstall() {
    INSTALL_PHASE="verification"
    if ! run_installer_verification; then
        return 1
    fi
    acquire_installer_single_flight_lock
    INSTALL_PHASE="uninstall"
    run_uninstall
    INSTALL_PHASE=""
}

run_post_preflight_phases() {
    INSTALL_PHASE="legal"
    run_tos

    INSTALL_PHASE="prepare"
    if [[ "$RELEASE_IMAGE_LOCK_ACTIVE" == "true" \
        && "$COMMAND" == "upgrade" \
        && -n "${EXISTING_INSTALL:-}" ]]; then
        # The receipt-bound preflight has already authenticated the existing
        # source stack and pulled its recovery images. Package, Docker,
        # firewall, user, and unattended-upgrade mutations must not happen
        # before run_deploy captures the exact recoverable source state.
        info "Verified existing receipt-bound upgrade; skipping generic host preparation"
    else
        run_prepare
    fi

    INSTALL_PHASE="configure"
    run_configure

    INSTALL_PHASE="deploy"
    run_deploy
}

# ── Uninstall ────────────────────────────────────────────────────────────────

run_uninstall() {
    step "Uninstalling LLM API Proxy..."

    local meta_file="${METADATA_DIR:-/etc/llm-api-proxy}/install.json"
    if [[ -f "$meta_file" ]]; then
        INSTALL_DIR=$(jq -r '.install_dir' "$meta_file" 2>/dev/null || echo "$INSTALL_DIR")
    fi

    if [[ ! -d "$INSTALL_DIR" ]]; then
        die "No installation found at ${INSTALL_DIR}"
    fi

    if [[ -x "${INSTALL_DIR}/compose-command.sh" ]]; then
        installer_run_live_compose down >> "$LOG_FILE" 2>&1 || true
        info "Stack stopped"
    fi

    if [[ "$IS_MACOS" == "true" ]]; then
        local plist="${HOME}/Library/LaunchAgents/com.llm-api-proxy.plist"
        launchctl unload "$plist" 2>/dev/null || true
        rm -f "$plist"
    else
        $SUDO systemctl stop llm-api-proxy 2>/dev/null || true
        $SUDO systemctl disable llm-api-proxy 2>/dev/null || true
        $SUDO rm -f /etc/systemd/system/llm-api-proxy.service
        $SUDO systemctl daemon-reload 2>/dev/null || true
    fi
    info "System service removed"

    $SUDO rm -rf "$INSTALL_DIR"
    info "Install directory removed: ${INSTALL_DIR}"

    if [[ "$IS_MACOS" != "true" ]] && id "$SERVICE_USER" &>/dev/null; then
        $SUDO userdel "$SERVICE_USER" 2>/dev/null || true
        info "System user '${SERVICE_USER}' removed"
    fi

    $SUDO rm -rf "$METADATA_DIR"
    info "Metadata removed"

    if [[ "$OPT_PURGE" == "true" ]]; then
        echo ""
        warn "WARNING: --purge will delete ALL data including the database!"
        if [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
            local confirm
            read -r -p "  Type YES to confirm volume deletion: " confirm
            if [[ "$confirm" != "YES" ]]; then
                info "Volume purge cancelled"
                return 0
            fi
        fi

        local -a volumes=("docker_timescaledb_data" "docker_consul_data")
        installer_docker volume rm "${volumes[@]}" 2>/dev/null || true
        installer_docker volume rm "docker_acme_data" "docker_proxy_ca_data" 2>/dev/null || true
        installer_docker volume rm "docker_prometheus_data" "docker_grafana_data" 2>/dev/null || true
        info "Docker volumes purged"
    fi

    info "Uninstall complete"
}

# ── Main entry point ─────────────────────────────────────────────────────────

run_installer_main() {
    log_init "$@"
    apply_env_defaults

    # Auto-detect non-TTY automation and force non-interactive mode.
    # Interactive prompts (dialog, read) cannot work with redirected stdin.
    if [[ ! -t 0 ]] && [[ "$OPT_NON_INTERACTIVE" != "true" ]]; then
        OPT_NON_INTERACTIVE="true"
        OPT_ACCEPT_TOS="true"
        log "Auto-detected non-TTY execution — forcing non-interactive mode"
    fi

    detect_dialog
    detect_os
    detect_arch

    case "${COMMAND:-}" in
        uninstall)
            if ! run_verified_uninstall; then
                return 1
            fi
            exit 0
            ;;
    esac

    if ! run_verified_recovery_preflight; then
        return 1
    fi
    run_post_preflight_phases

    INSTALL_PHASE=""
    info "Installation complete!"
}

main() {
    require_file_backed_execution
    parse_args "$@"
    read_release_image_lock
    verify_self_checksum
    INSTALLER_SELF_CHECK_VERIFIED="true"
    if [[ "$OPT_VERIFY_SELF_CHECKSUM" == "true" ]]; then
        return 0
    fi
    run_installer_main "$@"
}

